import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || '';

export const getWellnessAdvice = async (userQuery: string): Promise<string> => {
  if (!API_KEY) {
    return "Omlouvám se, ale AI asistent není momentálně dostupný (chybí API klíč).";
  }

  try {
    const ai = new GoogleGenAI({ apiKey: API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userQuery,
      config: {
        systemInstruction: `Jsi empatický wellness asistent pro platformu "Centrum Unity". 
        Tvá role je pomoci uživatelům najít rovnováhu a doporučit vhodné typy praktiků (terapeuty, kouče, jogíny).
        Odpovídej stručně, česky, povzbudivě a profesionálně. 
        Pokud se uživatel ptá na vážné zdravotní problémy, vždy doporuč návštěvu lékaře.`,
        thinkingConfig: { thinkingBudget: 0 } // Low latency preferred for chat
      }
    });

    return response.text || "Omlouvám se, ale momentálně nemohu odpovědět. Zkuste to prosím později.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Došlo k chybě při komunikaci s AI asistentem.";
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none";

  const variants = {
    primary: "bg-sage-600 text-white hover:bg-sage-700 focus:ring-sage-500",
    secondary: "bg-stone-200 text-stone-900 hover:bg-stone-300 focus:ring-stone-500",
    outline: "border border-stone-300 text-stone-700 hover:bg-stone-50 focus:ring-sage-500",
    ghost: "text-stone-600 hover:bg-stone-100 hover:text-stone-900 focus:ring-stone-500",
  };

  const sizes = {
    sm: "px-3 py-1.5 text-sm",
    md: "px-4 py-2 text-base",
    lg: "px-6 py-3 text-lg",
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export default Button;

