const Directory = ({ onBook }: { onBook: (p: Practitioner) => void }) => {
  const [selectedCategory, setSelectedCategory] = useState('Vše');
  const [searchQuery, setSearchQuery] = useState('');

  const filteredPractitioners = PRACTITIONERS.filter(p => {
    const matchesCategory = selectedCategory === 'Vše' || p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          p.specialties.some(s => s.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Hero Section */}
      <div className="bg-sage-800 rounded-3xl p-8 md:p-12 text-white shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-sage-700 rounded-full mix-blend-multiply filter blur-3xl opacity-50 transform translate-x-1/2 -translate-y-1/2"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-sage-500 rounded-full mix-blend-multiply filter blur-3xl opacity-50 transform -translate-x-1/2 translate-y-1/2"></div>

        <div className="relative z-10 max-w-2xl">
            <h1 className="text-4xl md:text-5xl font-bold mb-4 leading-tight">Najděte svou cestu k rovnováze.</h1>
            <p className="text-sage-100 text-lg mb-8">Propojte se s ověřenými terapeuty, kouči a mentory pro váš osobní rozvoj.</p>

            <div className="flex flex-col md:flex-row gap-4">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-stone-400 w-5 h-5" />
                    <input 
                        type="text" 
                        placeholder="Hledat jméno nebo specializaci..." 
                        className="w-full pl-10 pr-4 py-3 rounded-xl text-stone-900 focus:outline-none focus:ring-2 focus:ring-sage-400 shadow-lg"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
            </div>
        </div>
      </div>

      {/* Filters */}
      <div className="flex overflow-x-auto pb-2 gap-2 scrollbar-hide">
        {CATEGORIES.map(cat => (
          <button
            key={cat}
            onClick={() => setSelectedCategory(cat)}
            className={`px-4 py-2 rounded-full whitespace-nowrap text-sm font-medium transition-all ${
              selectedCategory === cat 
                ? 'bg-sage-600 text-white shadow-md' 
                : 'bg-white text-stone-600 hover:bg-stone-100 border border-stone-200'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredPractitioners.map(practitioner => (
          <PractitionerCard 
            key={practitioner.id} 
            practitioner={practitioner} 
            onBook={onBook} 
          />
        ))}
        {filteredPractitioners.length === 0 && (
            <div className="col-span-full text-center py-12">
                <p className="text-stone-500 text-lg">Nebyly nalezeny žádné výsledky pro vaše zadání.</p>
                <button onClick={() => {setSelectedCategory('Vše'); setSearchQuery('')}} className="text-sage-600 hover:underline mt-2">Obnovit filtry</button>
            </div>
        )}
      </div>
    </div>
  );
};

const BookingModal = ({ 
    practitioner, 
    onClose, 
    onConfirm 
}: { 
    practitioner: Practitioner | null, 
    onClose: () => void, 
    onConfirm: (date: string, time: string) => void 
}) => {
    const [selectedDate, setSelectedDate] = useState<string>('');
    const [selectedTime, setSelectedTime] = useState<string>('');

    if (!practitioner) return null;

    // Mock upcoming 3 days
    const dates = Array.from({length: 3}, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() + i + 1);
        return d.toISOString().split('T')[0];
    });

    const times = ['09:00', '10:00', '13:00', '14:30', '16:00'];

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl">
                <div className="bg-sage-50 p-6 border-b border-sage-100">
                    <h2 className="text-xl font-bold text-stone-900">Rezervace termínu</h2>
                    <p className="text-stone-600">u {practitioner.name}</p>
                </div>

                <div className="p-6 space-y-6">
                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">Vyberte den</label>
                        <div className="grid grid-cols-3 gap-2">
                            {dates.map(date => (
                                <button
                                    key={date}
                                    onClick={() => setSelectedDate(date)}
                                    className={`p-2 rounded-lg text-sm border transition-all ${
                                        selectedDate === date 
                                        ? 'bg-sage-600 text-white border-sage-600' 
                                        : 'border-stone-200 hover:border-sage-400'
                                    }`}
                                >
                                    {new Date(date).toLocaleDateString('cs-CZ', {weekday: 'short', day: 'numeric', month: 'numeric'})}
                                </button>
                            ))}
                        </div>
                    </div>

                    {selectedDate && (
                         <div className="animate-in slide-in-from-top-2">
                            <label className="block text-sm font-medium text-stone-700 mb-2">Vyberte čas</label>
                            <div className="grid grid-cols-3 gap-2">
                                {times.map(time => (
                                    <button
                                        key={time}
                                        onClick={() => setSelectedTime(time)}
                                        className={`p-2 rounded-lg text-sm border transition-all ${
                                            selectedTime === time 
                                            ? 'bg-sage-600 text-white border-sage-600' 
                                            : 'border-stone-200 hover:border-sage-400'
                                        }`}
                                    >
                                        {time}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                <div className="p-6 bg-stone-50 border-t border-stone-100 flex justify-end gap-3">
                    <Button variant="ghost" onClick={onClose}>Zrušit</Button>
                    <Button 
                        disabled={!selectedDate || !selectedTime} 
                        onClick={() => onConfirm(selectedDate, selectedTime)}
                    >
                        Potvrdit rezervaci
                    </Button>
                </div>
            </div>
        </div>
    );
};

const App = () => {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedPractitioner, setSelectedPractitioner] = useState<Practitioner | null>(null);

  const handleBook = (practitioner: Practitioner) => {
    setSelectedPractitioner(practitioner);
  };

  const confirmBooking = (date: string, time: string) => {
    if (selectedPractitioner) {
        const newBooking: Booking = {
            id: Date.now().toString(),
            practitionerId: selectedPractitioner.id,
            practitionerName: selectedPractitioner.name,
            date: date,
            time: time,
            status: 'confirmed'
        };
        setBookings(prev => [...prev, newBooking]);
        setSelectedPractitioner(null);
        // In a real app, we would redirect or show a toast here
        alert("Rezervace byla úspěšná!");
    }
  };

  return (
    <Router>
      <div className="min-h-screen bg-stone-50 font-sans text-stone-800">
        <Navbar />

        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          <Routes>
            <Route path="/" element={<Directory onBook={handleBook} />} />
            <Route path="/dashboard" element={<Dashboard bookings={bookings} />} />
          </Routes>
        </main>

        <footer className="bg-white border-t border-stone-200 mt-12 py-12">
            <div className="max-w-7xl mx-auto px-4 text-center text-stone-500">
                <p className="mb-4 font-semibold text-stone-900">Centrum Unity</p>
                <p>&copy; 2026 Centrum Unity. Všechna práva vyhrazena.</p>
            </div>
        </footer>

        {selectedPractitioner && (
            <BookingModal 
                practitioner={selectedPractitioner} 
                onClose={() => setSelectedPractitioner(null)} 
                onConfirm={confirmBooking}
            />
        )}

        <AIChatBot />
      </div>
    </Router>
  );
};

export default App;

