  );
};

const BookingModal = ({ 
    practitioner, 
    onClose, 
    onConfirm 
}: { 
    practitioner: Practitioner | null, 
    onClose: () => void, 
    onConfirm: (date: string, time: string) => void 
}) => {
    const [selectedDate, setSelectedDate] = useState<string>('');
    const [selectedTime, setSelectedTime] = useState<string>('');

    if (!practitioner) return null;

    // Mock upcoming 3 days
    const dates = Array.from({length: 3}, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() + i + 1);
        return d.toISOString().split('T')[0];
    });

    const times = ['09:00', '10:00', '13:00', '14:30', '16:00'];

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl">
                <div className="bg-sage-50 p-6 border-b border-sage-100">
                    <h2 className="text-xl font-bold text-stone-900">Rezervace termínu</h2>
                    <p className="text-stone-600">u {practitioner.name}</p>
                </div>

                <div className="p-6 space-y-6">
                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">Vyberte den</label>
                        <div className="grid grid-cols-3 gap-2">
                            {dates.map(date => (
                                <button
                                    key={date}
                                    onClick={() => setSelectedDate(date)}
                                    className={`p-2 rounded-lg text-sm border transition-all ${
                                        selectedDate === date 
                                        ? 'bg-sage-600 text-white border-sage-600' 
                                        : 'border-stone-200 hover:border-sage-400'
                                    }`}
                                >
                                    {new Date(date).toLocaleDateString('cs-CZ', {weekday: 'short', day: 'numeric', month: 'numeric'})}
                                </button>
                            ))}
                        </div>
                    </div>

                    {selectedDate && (
                         <div className="animate-in slide-in-from-top-2">
                            <label className="block text-sm font-medium text-stone-700 mb-2">Vyberte čas</label>
                            <div className="grid grid-cols-3 gap-2">
                                {times.map(time => (
                                    <button
                                        key={time}
                                        onClick={() => setSelectedTime(time)}
                                        className={`p-2 rounded-lg text-sm border transition-all ${
                                            selectedTime === time 
                                            ? 'bg-sage-600 text-white border-sage-600' 
                                            : 'border-stone-200 hover:border-sage-400'
                                        }`}
                                    >
                                        {time}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                <div className="p-6 bg-stone-50 border-t border-stone-100 flex justify-end gap-3">
                    <Button variant="ghost" onClick={onClose}>Zrušit</Button>
                    <Button 
                        disabled={!selectedDate || !selectedTime} 
                        onClick={() => onConfirm(selectedDate, selectedTime)}
                    >
                        Potvrdit rezervaci
                    </Button>
                </div>
            </div>
        </div>
    );
};

