const BookingModal = ({ 
    practitioner, 
    onClose, 
    onConfirm 
}: { 
    practitioner: Practitioner | null, 
    onClose: () => void, 
    onConfirm: (date: string, time: string) => void 
}) => {
    const [selectedDate, setSelectedDate] = useState<string>('');
    const [selectedTime, setSelectedTime] = useState<string>('');

    if (!practitioner) return null;

    // Generování termínů na 5 dní dopředu
    const dates = Array.from({length: 5}, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() + i + 1);
        return d.toISOString().split('T')[0];
    });

    const ALL_TIMES = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00'];

    // LOGIKA PRO SIMULACI DOSTUPNOSTI
    // V reálné aplikaci by toto řešil backend dotaz:
    // SELECT count(*) FROM bookings WHERE time = X AND date = Y -> Pokud >= 2 (počet místností), vrátit FULL
    const getSlotStatus = (time: string): 'available' | 'room_full' | 'practitioner_busy' => {
        // Pseudo-náhodná logika pro demonstraci
        // Hash stringu pro konzistentní výsledky při re-renderu
        const hash = (selectedDate + time + practitioner.id).split('').reduce((a,b)=>a+b.charCodeAt(0),0);

        if (hash % 7 === 0) return 'room_full'; // 1 ze 7 případů jsou plné místnosti
        if (hash % 5 === 0) return 'practitioner_busy'; // 1 z 5 případů má lektor plno
        return 'available';
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl w-full max-w-2xl overflow-hidden shadow-2xl flex flex-col md:flex-row h-[600px] md:h-auto">

                {/* Left Side - Info */}
                <div className="bg-sage-600 text-white p-8 md:w-1/3 flex flex-col justify-between">
                    <div>
                        <h2 className="text-2xl font-bold font-heading mb-2">Rezervace</h2>
                        <div className="w-12 h-1 bg-white/30 rounded-full mb-6"></div>

                        <div className="mb-6">
                            <p className="text-sage-200 text-sm uppercase tracking-wider mb-1">Terapeut</p>
                            <p className="font-bold text-lg">{practitioner.name}</p>
                            <p className="text-sage-100 text-sm">{practitioner.title}</p>
                        </div>

                        <div>
                            <p className="text-sage-200 text-sm uppercase tracking-wider mb-1">Cena</p>
                            <p className="font-bold text-xl">{practitioner.pricePerHour} Kč <span className="text-sm font-normal text-sage-200">/ hod</span></p>
                        </div>
                    </div>

                    <div className="mt-8 bg-white/10 p-4 rounded-xl text-sm">
                        <div className="flex items-center gap-2 mb-2 font-bold">
                            <Info className="w-4 h-4" /> Důležité
                        </div>
                        <p className="leading-relaxed opacity-90">
                            Systém automaticky hlídá dostupnost místností. Pokud vidíte čas jako obsazený, může to znamenat plnou kapacitu centra, i když má lektor čas.
                        </p>
                    </div>
                </div>

                {/* Right Side - Selection */}
                <div className="p-8 md:w-2/3 flex flex-col h-full bg-white overflow-y-auto">
                    <div className="flex-grow space-y-6">
                        {/* Date Selection */}
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-3">1. Vyberte termín</label>
                            <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                                {dates.map(date => {
                                    const d = new Date(date);
                                    const dayName = d.toLocaleDateString('cs-CZ', {weekday: 'short'});
                                    const dayNum = d.getDate();
                                    const isSelected = selectedDate === date;

                                    return (
                                        <button
                                            key={date}
                                            onClick={() => { setSelectedDate(date); setSelectedTime(''); }}
                                            className={`flex flex-col items-center justify-center min-w-[70px] p-3 rounded-xl border-2 transition-all duration-200 ${
                                                isSelected 
                                                ? 'border-sage-600 bg-sage-50 text-sage-800 shadow-sm transform scale-105' 
                                                : 'border-stone-100 text-stone-500 hover:border-sage-200 hover:bg-stone-50'
                                            }`}
                                        >
                                            <span className="text-xs font-medium uppercase">{dayName}</span>
                                            <span className="text-xl font-bold font-heading">{dayNum}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>

                        {/* Time Selection */}
                        <div className={`transition-all duration-300 ${selectedDate ? 'opacity-100 translate-y-0' : 'opacity-50 translate-y-4 pointer-events-none'}`}>
                            <label className="block text-sm font-medium text-stone-700 mb-3">2. Vyberte čas</label>
                            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                                {ALL_TIMES.map(time => {
                                    const status = selectedDate ? getSlotStatus(time) : 'available';
                                    const isSelected = selectedTime === time;
                                    const isAvailable = status === 'available';

                                    let statusText = '';
                                    let statusColor = '';

                                    if (status === 'room_full') { statusText = 'Centrum plné'; statusColor = 'text-orange-400'; }
                                    if (status === 'practitioner_busy') { statusText = 'Obsazeno'; statusColor = 'text-stone-300'; }

                                    return (
                                        <button
                                            key={time}
                                            disabled={!isAvailable}
                                            onClick={() => setSelectedTime(time)}
                                            className={`relative p-3 rounded-xl border text-left transition-all ${
                                                isSelected 
                                                ? 'border-sage-600 bg-sage-600 text-white shadow-md ring-2 ring-sage-200 ring-offset-2' 
                                                : isAvailable
                                                    ? 'border-stone-200 hover:border-sage-400 hover:bg-sage-50 text-stone-800'
                                                    : 'border-stone-100 bg-stone-50 opacity-60 cursor-not-allowed'
                                            }`}
                                        >
                                            <span className="block font-bold text-lg">{time}</span>
                                            {!isAvailable && (
                                                <span className={`text-xs font-medium flex items-center gap-1 mt-1 ${statusColor}`}>
                                                    {status === 'room_full' && <AlertCircle className="w-3 h-3" />}
                                                    {statusText}
                                                </span>
                                            )}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    </div>

                    {/* Footer Actions */}
                    <div className="pt-6 border-t border-stone-100 flex justify-end gap-3 mt-4">
                        <Button variant="ghost" onClick={onClose}>Zrušit</Button>
                        <Button 
                            disabled={!selectedDate || !selectedTime} 
                            onClick={() => onConfirm(selectedDate, selectedTime)}
                            className="px-8"
                        >
                            Potvrdit rezervaci
                        </Button>
                    </div>
                </div>
            </div>
        </div>
    );
};

