import React, { useState } from 'react';
import { Practitioner, Booking } from '../types';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon, Clock, Users, Sparkles, AlertCircle } from 'lucide-react';

interface CalendarViewProps {
  practitioners: Practitioner[];
  bookings: Booking[];
  onBook: (practitioner: Practitioner, date: string, time: string) => void;
}

const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];
const TIMES = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00'];

const CalendarView: React.FC<CalendarViewProps> = ({ practitioners, bookings, onBook }) => {
  const [currentWeekStart, setCurrentWeekStart] = useState(new Date());

  // Helper to move weeks
  const changeWeek = (offset: number) => {
    const newDate = new Date(currentWeekStart);
    newDate.setDate(newDate.getDate() + (offset * 7));
    setCurrentWeekStart(newDate);
  };

  // Generate dates for the view (Monday to Friday)
  const weekDays = Array.from({ length: 5 }, (_, i) => {
    const d = new Date(currentWeekStart);
    // Adjust to Monday of current week if today isn't Monday
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
    d.setDate(diff + i);
    return d;
  });

  const formatDate = (date: Date) => date.toISOString().split('T')[0];

  const getAvailablePractitionersForSlot = (date: Date, time: string) => {
    const dateStr = formatDate(date);
    const dayName = DAYS_MAP[date.getDay()]; // "Po", "Út"...
    const availabilityKey = `${dayName}-${time}`;

    // 1. Check Room Capacity Global
    const bookingsAtTime = bookings.filter(b => b.date === dateStr && b.time === time);
    if (bookingsAtTime.length >= 2) return []; // Room full

    // 2. Find practitioners who list this slot in their availability
    return practitioners.filter(p => {
      // Is practitioner working this generic day/time?
      if (!p.availability.includes(availabilityKey)) return false;

      // Is practitioner already booked specifically this date/time?
      const isBooked = bookingsAtTime.some(b => b.practitionerId === p.id);
      return !isBooked;
    });
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 pt-4 px-2">
        <div>
           <h1 className="text-3xl font-bold text-stone-900 font-heading">Rozvrh aktivit</h1>
           <p className="text-stone-600">Přehled všech volných termínů v Centru Unity.</p>
        </div>

        <div className="flex items-center gap-4 bg-white p-2 rounded-xl shadow-sm border border-stone-200">
            <button onClick={() => changeWeek(-1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600">
                <ChevronLeft className="w-5 h-5" />
            </button>
            <div className="flex items-center gap-2 font-medium min-w-[140px] justify-center text-stone-800">
                <CalendarIcon className="w-4 h-4 text-sage-600" />
                <span>
                    {weekDays[0].getDate()}. {weekDays[0].getMonth() + 1}. – {weekDays[4].getDate()}. {weekDays[4].getMonth() + 1}.
                </span>
            </div>
            <button onClick={() => changeWeek(1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600">
                <ChevronRight className="w-5 h-5" />
            </button>
        </div>
      </div>

      {/* Calendar Grid */}
      <div className="overflow-x-auto pb-4">
        <div className="min-w-[1000px] bg-white rounded-2xl shadow-sm border border-stone-200 overflow-hidden">
            {/* Header Row */}
            <div className="grid grid-cols-6 border-b border-stone-200 bg-stone-50">
                <div className="p-4 text-center font-bold text-stone-400 border-r border-stone-200 flex items-center justify-center">
                    <Clock className="w-5 h-5" />
                </div>
                {weekDays.map(d => (
                    <div key={d.toString()} className="p-4 text-center border-r border-stone-200 last:border-0">
                        <div className="font-bold text-sage-900">{DAYS_MAP[d.getDay()]}</div>
                        <div className="text-sm text-stone-500">{d.getDate()}. {d.getMonth() + 1}.</div>
                    </div>
                ))}
            </div>

            {/* Time Rows */}
            {TIMES.map(time => (
                <div key={time} className="grid grid-cols-6 border-b border-stone-100 last:border-0 hover:bg-stone-50/30 transition-colors">
                    {/* Time Column */}
                    <div className="p-4 flex items-center justify-center font-bold text-stone-600 border-r border-stone-200 bg-stone-50/50">
                        {time}
                    </div>

                    {/* Days Columns */}
                    {weekDays.map(date => {
                        const availablePeople = getAvailablePractitionersForSlot(date, time);
                        const isPast = date < new Date(new Date().setHours(0,0,0,0));

                        return (
                            <div key={`${date}-${time}`} className="p-2 border-r border-stone-200 last:border-0 min-h-[100px] relative">
                                {isPast ? (
                                    <div className="absolute inset-0 bg-stone-100/50 flex items-center justify-center">
                                        {/* Grayed out for past */}
                                    </div>
                                ) : (
                                    <div className="space-y-2">
                                        {availablePeople.length === 0 ? (
                                            <div className="h-full flex items-center justify-center text-stone-300 text-xs">
                                                -
                                            </div>
                                        ) : (
                                            availablePeople.map(p => (
                                                <button
                                                    key={p.id}
                                                    onClick={() => onBook(p, formatDate(date), time)}
                                                    className="w-full text-left bg-white border border-stone-200 rounded-lg p-2 shadow-sm hover:shadow-md hover:border-sage-300 hover:ring-1 hover:ring-sage-300 transition-all group"
                                                >
                                                    <div className="flex items-start justify-between gap-1 mb-1">
                                                        <span className="text-[10px] font-bold uppercase tracking-wider text-sage-600 bg-sage-50 px-1.5 py-0.5 rounded-sm">
                                                            {p.category}
                                                        </span>
                                                        <Sparkles className="w-3 h-3 text-stone-300 group-hover:text-sage-500" />
                                                    </div>
                                                    <div className="text-xs font-bold text-stone-800 leading-tight mb-0.5">
                                                        {p.name}
                                                    </div>
                                                    <div className="text-[10px] text-stone-500 truncate">
                                                        {p.title}
                                                    </div>
                                                </button>
                                            ))
                                        )}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            ))}
        </div>
      </div>

      <div className="bg-sage-50 p-4 rounded-xl flex items-start gap-3 border border-sage-100 max-w-2xl mx-auto">
        <AlertCircle className="w-5 h-5 text-sage-600 mt-0.5" />
        <div className="text-sm text-sage-800">
            <p className="font-bold mb-1">Jak číst rozvrh?</p>
            <p>Zobrazují se pouze termíny, kde je volná místnost a lektor má čas. Kliknutím na kartičku rovnou přejdete k potvrzení rezervace.</p>
        </div>
      </div>
    </div>
  );
};

