import React, { useState } from 'react';
import { Practitioner, Booking } from '../types';
import Button from '../components/Button';
import { Calendar, Check, Clock, Save, User, Settings, AlertCircle, Users } from 'lucide-react';

interface PractitionerDashboardProps {
  practitioners: Practitioner[];
  updatePractitioner: (updated: Practitioner) => void;
  allBookings: Booking[];
}

const DAYS = ['Po', 'Út', 'St', 'Čt', 'Pá'];
const TIMES = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00'];

const PractitionerDashboard: React.FC<PractitionerDashboardProps> = ({ 
  practitioners, 
  updatePractitioner,
  allBookings 
}) => {
  // Login simulation
  const [currentPractitionerId, setCurrentPractitionerId] = useState<string>(practitioners[0].id);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  const currentPractitioner = practitioners.find(p => p.id === currentPractitionerId)!;

  // Temporary state for editing
  const [tempAvailability, setTempAvailability] = useState<string[]>(currentPractitioner.availability);

  // Sync temp state when switching users
  React.useEffect(() => {
    setTempAvailability(currentPractitioner.availability);
    setHasUnsavedChanges(false);
  }, [currentPractitionerId, currentPractitioner]);

  // Filter bookings for current practitioner
  const myBookings = allBookings.filter(b => b.practitionerId === currentPractitionerId);

  // Helper: Count how many active bookings exist for a specific generic slot (e.g., how many "Monday 09:00" bookings across all dates)
  const getBookingCountForSlot = (dayName: string, time: string) => {
    return myBookings.filter(b => {
      const d = new Date(b.date);
      const bookingDayName = d.toLocaleDateString('cs-CZ', {weekday: 'short'}).replace('.', '');
      return bookingDayName === dayName && b.time === time && b.status === 'confirmed';
    }).length;
  };

  const toggleSlot = (day: string, time: string) => {
    const slotId = `${day}-${time}`;
    const bookingCount = getBookingCountForSlot(day, time);
    const isCurrentlyAvailable = tempAvailability.includes(slotId);

    // Safety check: If trying to disable a slot that has bookings
    if (isCurrentlyAvailable && bookingCount > 0) {
        const confirmRemove = window.confirm(
            `POZOR: Na čas ${day} ${time} máte již ${bookingCount} potvrzené rezervace!\n\nOpravdu chcete zrušit dostupnost? Rezervace zůstanou platné, ale noví klienti se již nebudou moci objednat.`
        );
        if (!confirmRemove) return;
    }

    setTempAvailability(prev => {
      if (prev.includes(slotId)) {
        return prev.filter(id => id !== slotId);
      } else {
        return [...prev, slotId];
      }
    });
    setHasUnsavedChanges(true);
  };

  const handleSave = () => {
    updatePractitioner({
      ...currentPractitioner,
      availability: tempAvailability
    });
    setHasUnsavedChanges(false);
    alert('Dostupnost byla aktualizována. Klienti nyní vidí vaše nové termíny.');
  };

  return (
    <div className="animate-in fade-in duration-500 pb-12 space-y-8">

      {/* Top Bar / Login Simulator */}
      <div className="bg-white p-4 rounded-xl border border-stone-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex items-center gap-3">
          <div className="bg-sage-100 p-2 rounded-full">
            <User className="w-6 h-6 text-sage-700" />
          </div>
          <div>
             <span className="text-xs font-bold text-stone-400 uppercase tracking-wider">Přihlášen jako</span>
             <h2 className="font-heading font-bold text-lg text-stone-900">{currentPractitioner.name}</h2>
          </div>
        </div>

        <div className="flex items-center gap-2">
            <span className="text-sm text-stone-500">Přepnout profil (Demo):</span>
            <select 
                className="bg-stone-50 border border-stone-200 text-stone-700 text-sm rounded-lg focus:ring-sage-500 focus:border-sage-500 block p-2.5"
                value={currentPractitionerId}
                onChange={(e) => setCurrentPractitionerId(e.target.value)}
            >
                {practitioners.map(p => (
                    <option key={p.id} value={p.id}>{p.name}</option>
                ))}
            </select>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* LEFT COL: Availability Editor */}
        <div className="lg:col-span-2 space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold font-heading text-stone-900">Správa kalendáře</h2>
                <Button 
                    onClick={handleSave} 
                    disabled={!hasUnsavedChanges}
                    className={`flex items-center gap-2 ${hasUnsavedChanges ? 'animate-pulse' : ''}`}
                >
                    <Save className="w-4 h-4" /> Uložit změny
                </Button>
            </div>

            <div className="bg-white rounded-xl border border-stone-200 shadow-sm overflow-hidden">
                <div className="p-4 bg-stone-50 border-b border-stone-200 text-sm text-stone-500 flex items-center gap-2">
                    <AlertCircle className="w-4 h-4" />
                    Kliknutím na buňku označte čas jako dostupný. Číslo v kroužku značí počet již vytvořených rezervací.
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="text-xs text-stone-500 uppercase bg-stone-50 border-b border-stone-100">
                            <tr>
                                <th className="px-6 py-4 font-medium">Čas</th>
                                {DAYS.map(day => (
                                    <th key={day} className="px-6 py-4 font-bold text-center">{day}</th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {TIMES.map(time => (
                                <tr key={time} className="border-b border-stone-50 hover:bg-stone-50/50">
                                    <td className="px-6 py-4 font-medium text-stone-900 whitespace-nowrap bg-stone-50/30">
                                        {time}
                                    </td>
                                    {DAYS.map(day => {
                                        const isAvailable = tempAvailability.includes(`${day}-${time}`);
                                        const bookingCount = getBookingCountForSlot(day, time);

                                        return (
                                            <td key={`${day}-${time}`} className="p-2 text-center">
                                                <button
                                                    onClick={() => toggleSlot(day, time)}
                                                    className={`relative w-full h-12 rounded-lg transition-all duration-200 border-2 font-medium flex flex-col items-center justify-center gap-0.5 ${
                                                        isAvailable 
                                                        ? 'bg-sage-500 border-sage-500 text-white shadow-sm hover:bg-sage-600' 
                                                        : 'bg-white border-stone-200 text-stone-300 hover:border-sage-300 hover:text-sage-400'
                                                    }`}
                                                >
                                                    <div className="flex items-center gap-1">
                                                        {isAvailable ? <Check className="w-3 h-3" /> : <Settings className="w-3 h-3" />}
                                                        <span className="text-xs">{isAvailable ? 'Volno' : '-'}</span>
                                                    </div>

                                                    {/* Booking Counter Badge */}
                                                    {bookingCount > 0 && (
                                                        <div className={`absolute -top-2 -right-2 flex items-center justify-center w-5 h-5 text-[10px] font-bold rounded-full shadow-sm border ${
                                                            isAvailable ? 'bg-white text-sage-700 border-sage-200' : 'bg-stone-600 text-white border-stone-700'
                                                        }`}>
                                                            {bookingCount}
                                                        </div>
                                                    )}
                                                </button>
                                            </td>
                                        );
                                    })}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        {/* RIGHT COL: Booking Overview */}
        <div className="space-y-6">
            <h2 className="text-2xl font-bold font-heading text-stone-900">Příchozí rezervace</h2>

            <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                <div className="space-y-4">
                    {myBookings.length === 0 ? (
                        <p className="text-stone-500 text-center py-8">Zatím nemáte žádné rezervace.</p>
                    ) : (
                        myBookings.map(booking => (
                            <div key={booking.id} className="flex items-start gap-4 p-4 rounded-lg bg-stone-50 border border-stone-100">
                                <div className="bg-white p-2 rounded-full border border-stone-200 text-sage-600">
                                    <Calendar className="w-5 h-5" />
                                </div>
                                <div className="flex-1">
                                    <div className="flex justify-between items-start">
                                        <h4 className="font-bold text-stone-900">Rezervace #{booking.id.slice(-4)}</h4>
                                        <span className={`px-2 py-0.5 rounded text-xs font-bold uppercase ${
                                            booking.status === 'confirmed' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'
                                        }`}>
                                            {booking.status}
                                        </span>
                                    </div>
                                    <div className="mt-1 text-sm text-stone-600 space-y-1">
                                        <div className="flex items-center gap-2">
                                            <Clock className="w-3 h-3" />
                                            {new Date(booking.date).toLocaleDateString('cs-CZ')} v {booking.time}
                                        </div>
                                        <div className="text-xs text-stone-400">Klient: Jan Novák (Demo)</div>
                                    </div>
                                    <div className="mt-3 flex gap-2">
                                        <Button size="sm" variant="outline" className="w-full text-xs h-8">Změnit</Button>
                                        <Button size="sm" className="w-full text-xs h-8">Detail</Button>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            <div className="bg-sage-50 p-6 rounded-xl border border-sage-100">
                <div className="flex items-center gap-2 mb-2">
                    <Users className="w-5 h-5 text-sage-700" />
                    <h3 className="font-bold text-sage-900 font-heading">Vytíženost</h3>
                </div>
                <p className="text-sm text-sage-700 leading-relaxed">
                    Čísla v kroužku v kalendáři ukazují, kolikrát je daný časový slot již obsazen konkrétní rezervací v budoucnu. Systém automaticky blokuje tyto časy pro další klienty, aby nedošlo k překryvu.
                </p>
            </div>
        </div>

      </div>
    </div>
  );
};

