            </div>
        </div>
      </div>

      {/* Filters */}
      <div className="flex overflow-x-auto pb-2 gap-2 scrollbar-hide">
        {CATEGORIES.map(cat => (
          <button
            key={cat}
            onClick={() => setSelectedCategory(cat)}
            className={`px-4 py-2 rounded-full whitespace-nowrap text-sm font-medium transition-all ${
              selectedCategory === cat 
                ? 'bg-sage-600 text-white shadow-md' 
                : 'bg-white text-stone-600 hover:bg-stone-100 border border-stone-200'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredPractitioners.map(practitioner => (
          <PractitionerCard 
            key={practitioner.id} 
            practitioner={practitioner} 
            onBook={onBook} 
          />
        ))}
        {filteredPractitioners.length === 0 && (
            <div className="col-span-full text-center py-12">
                <p className="text-stone-500 text-lg">Nebyly nalezeny žádné výsledky pro vaše zadání.</p>
                <button onClick={() => {setSelectedCategory('Vše'); setSearchQuery('')}} className="text-sage-600 hover:underline mt-2">Obnovit filtry</button>
            </div>
        )}
      </div>
    </div>
  );
};

const BookingModal = ({ 
    practitioner, 
    onClose, 
    onConfirm,
    allBookings,
    initialDate,
    initialTime
}: { 
    practitioner: Practitioner | null, 
    onClose: () => void, 
    onConfirm: (date: string, time: string, paymentMethod: 'card' | 'cash') => void,
    allBookings: Booking[],
    initialDate?: string,
    initialTime?: string
}) => {
    // --- STATE ---
    const [step, setStep] = useState<1 | 2>(1); // 1: Select Date/Time, 2: Payment
    const [selectedDate, setSelectedDate] = useState<string>(initialDate || '');
    const [selectedTime, setSelectedTime] = useState<string>(initialTime || '');

    // Payment State
    const [paymentMethod, setPaymentMethod] = useState<'card' | 'cash'>('card');
    const [isProcessing, setIsProcessing] = useState(false);

    // Mock Card Data
    const [cardNumber, setCardNumber] = useState('');
    const [expiry, setExpiry] = useState('');
    const [cvc, setCvc] = useState('');

    if (!practitioner) return null;

    // --- LOGIC ---
    const dates = Array.from({length: 5}, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() + i + 1);
        return d.toISOString().split('T')[0];
    });

    if (initialDate && !dates.includes(initialDate)) {
        dates.unshift(initialDate);
    }

    const ALL_TIMES = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00'];

    const getSlotStatus = (date: string, time: string): 'available' | 'room_full' | 'practitioner_busy' => {
        const d = new Date(date);
        const dayName = d.toLocaleDateString('cs-CZ', {weekday: 'short'}).replace('.', '');
        const slotKey = `${dayName}-${time}`;

        if (!practitioner.availability.includes(slotKey)) return 'practitioner_busy';

        const bookingsAtThisTime = allBookings.filter(b => b.date === date && b.time === time);
        if (bookingsAtThisTime.length >= 2) return 'room_full';
        const isPractitionerBooked = bookingsAtThisTime.some(b => b.practitionerId === practitioner.id);
        if (isPractitionerBooked) return 'practitioner_busy';

        return 'available';
    };

    const handleNextStep = () => {
        if (selectedDate && selectedTime) {
            setStep(2);
        }
    };

    const handlePayAndBook = () => {
        setIsProcessing(true);
        // Simulate API call
        setTimeout(() => {
            setIsProcessing(false);
            onConfirm(selectedDate, selectedTime, paymentMethod);
        }, 2000);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl w-full max-w-4xl overflow-hidden shadow-2xl flex flex-col md:flex-row h-[600px] md:h-[600px]">

                {/* Left Side - Info & Summary */}
                <div className="bg-sage-600 text-white p-8 md:w-1/3 flex flex-col justify-between relative overflow-hidden">
                    <div className="relative z-10">
                        <div className="flex items-center gap-2 mb-6 cursor-pointer opacity-80 hover:opacity-100" onClick={onClose}>
                             <ChevronLeft className="w-4 h-4" /> Zpět
                        </div>

                        <h2 className="text-2xl font-bold font-heading mb-2">
                            {step === 1 ? 'Rezervace termínu' : 'Shrnutí a platba'}
                        </h2>
                        <div className="w-12 h-1 bg-white/30 rounded-full mb-6"></div>

                        <div className="space-y-6">
                             <div>
                                <p className="text-sage-200 text-xs uppercase tracking-wider mb-1">Terapeut</p>
                                <p className="font-bold text-lg leading-tight">{practitioner.name}</p>
                                <p className="text-sage-100 text-sm">{practitioner.title}</p>
                            </div>

                            {selectedDate && selectedTime && (
                                <div className="bg-white/10 p-3 rounded-lg border border-white/10 animate-in fade-in slide-in-from-left-2">
                                    <p className="text-sage-200 text-xs uppercase tracking-wider mb-1">Vybraný termín</p>
                                    <div className="flex items-center gap-2 font-bold">
                                        <CalendarIcon className="w-4 h-4" />
                                        {new Date(selectedDate).toLocaleDateString('cs-CZ')}
                                    </div>
                                    <div className="flex items-center gap-2 mt-1">
                                        <div className="bg-white/20 px-2 py-0.5 rounded text-sm">{selectedTime}</div>
                                    </div>
                                </div>
                            )}

                            <div>
                                <p className="text-sage-200 text-xs uppercase tracking-wider mb-1">Celková cena</p>
                                <p className="font-bold text-3xl">{practitioner.pricePerHour} Kč</p>
                            </div>
                        </div>
                    </div>

                    {/* Decorative Circle */}
                    <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-sage-500 rounded-full opacity-50 blur-2xl"></div>
                </div>

                {/* Right Side - Interactive Steps */}
                <div className="p-8 md:w-2/3 flex flex-col h-full bg-white overflow-y-auto">

                    {/* STEP 1: Date & Time */}
                    {step === 1 && (
                        <div className="flex-grow space-y-6 animate-in slide-in-from-right-8 duration-300">
                             <div>
                                <h3 className="text-lg font-bold text-stone-900 mb-4 flex items-center gap-2">
                                    <span className="bg-stone-900 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs">1</span>
                                    Vyberte datum
                                </h3>
                                <div className="flex gap-2 overflow-x-auto pb-4 scrollbar-hide">
                                    {dates.map(date => {
                                        const d = new Date(date);
                                        const dayName = d.toLocaleDateString('cs-CZ', {weekday: 'short'});
                                        const dayNum = d.getDate();
                                        const isSelected = selectedDate === date;

                                        return (
                                            <button
                                                key={date}
                                                onClick={() => { setSelectedDate(date); setSelectedTime(''); }}
                                                className={`flex flex-col items-center justify-center min-w-[70px] p-3 rounded-xl border-2 transition-all duration-200 ${
                                                    isSelected 
                                                    ? 'border-sage-600 bg-sage-50 text-sage-800 shadow-sm transform scale-105' 
                                                    : 'border-stone-100 text-stone-500 hover:border-sage-200 hover:bg-stone-50'
                                                }`}
                                            >
                                                <span className="text-xs font-medium uppercase">{dayName}</span>
                                                <span className="text-xl font-bold font-heading">{dayNum}</span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>

                            <div className={`transition-all duration-300 ${selectedDate ? 'opacity-100' : 'opacity-50 pointer-events-none'}`}>
                                <h3 className="text-lg font-bold text-stone-900 mb-4 flex items-center gap-2">
                                    <span className="bg-stone-900 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs">2</span>
                                    Vyberte čas
                                </h3>
                                <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                    {ALL_TIMES.map(time => {
                                        const status = selectedDate ? getSlotStatus(selectedDate, time) : 'available';
                                        const isSelected = selectedTime === time;
                                        const isAvailable = status === 'available';

                                        return (
                                            <button
                                                key={time}
                                                disabled={!isAvailable}
                                                onClick={() => setSelectedTime(time)}
                                                className={`relative p-3 rounded-xl border text-center transition-all ${
                                                    isSelected 
                                                    ? 'border-sage-600 bg-sage-600 text-white shadow-md' 
                                                    : isAvailable
                                                        ? 'border-stone-200 hover:border-sage-400 hover:bg-sage-50 text-stone-800'
                                                        : 'border-stone-100 bg-stone-50 opacity-40 cursor-not-allowed'
                                                }`}
                                            >
                                                <span className="font-bold text-sm">{time}</span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>

                            <div className="pt-8 mt-auto flex justify-end">
                                <Button 
                                    onClick={handleNextStep}
                                    disabled={!selectedDate || !selectedTime}
                                    className="w-full sm:w-auto flex items-center gap-2"
                                >
                                    Pokračovat k platbě <ChevronRight className="w-4 h-4" />
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* STEP 2: Payment */}
                    {step === 2 && (
                        <div className="flex-grow flex flex-col animate-in slide-in-from-right-8 duration-300">
                             <div className="mb-6">
                                <h3 className="text-lg font-bold text-stone-900 mb-4 flex items-center gap-2">
                                    <span className="bg-stone-900 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs">3</span>
                                    Způsob platby
                                </h3>

                                <div className="space-y-3">
                                    {/* Card Option */}
                                    <label className={`flex items-center p-4 border-2 rounded-xl cursor-pointer transition-all ${paymentMethod === 'card' ? 'border-sage-500 bg-sage-50' : 'border-stone-200 hover:border-stone-300'}`}>
                                        <input 
                                            type="radio" 
                                            name="payment" 
                                            className="hidden" 
                                            checked={paymentMethod === 'card'}
                                            onChange={() => setPaymentMethod('card')}
                                        />
                                        <div className={`p-2 rounded-full mr-4 ${paymentMethod === 'card' ? 'bg-sage-500 text-white' : 'bg-stone-100 text-stone-400'}`}>
                                            <CreditCard className="w-5 h-5" />
                                        </div>
                                        <div className="flex-1">
                                            <span className="font-bold block text-stone-900">Platební karta</span>
                                            <span className="text-xs text-stone-500">Bezpečná platba přes Stripe</span>
                                        </div>
                                        {paymentMethod === 'card' && <CheckCircle className="w-5 h-5 text-sage-600" />}
                                    </label>

                                    {/* Cash Option */}
                                    <label className={`flex items-center p-4 border-2 rounded-xl cursor-pointer transition-all ${paymentMethod === 'cash' ? 'border-sage-500 bg-sage-50' : 'border-stone-200 hover:border-stone-300'}`}>
                                        <input 
                                            type="radio" 
                                            name="payment" 
                                            className="hidden" 
                                            checked={paymentMethod === 'cash'}
                                            onChange={() => setPaymentMethod('cash')}
                                        />
                                        <div className={`p-2 rounded-full mr-4 ${paymentMethod === 'cash' ? 'bg-sage-500 text-white' : 'bg-stone-100 text-stone-400'}`}>
                                            <Wallet className="w-5 h-5" />
                                        </div>
                                        <div className="flex-1">
                                            <span className="font-bold block text-stone-900">Hotově / QR na místě</span>
                                            <span className="text-xs text-stone-500">Platba přímo lektorovi</span>
                                        </div>
                                        {paymentMethod === 'cash' && <CheckCircle className="w-5 h-5 text-sage-600" />}
                                    </label>
                                </div>
                            </div>

                            {/* Payment Form (Mock) */}
                            {paymentMethod === 'card' && (
                                <div className="bg-stone-50 p-4 rounded-xl border border-stone-200 space-y-3 mb-6 animate-in fade-in">
                                    <div>
                                        <label className="text-xs font-bold text-stone-500 uppercase">Číslo karty</label>
                                        <div className="relative">
                                            <input 
                                                type="text" 
                                                placeholder="0000 0000 0000 0000" 
                                                className="w-full p-2 pl-10 border border-stone-300 rounded-lg font-mono text-sm focus:ring-2 focus:ring-sage-500 outline-none"
                                                value={cardNumber}
                                                onChange={(e) => {
                                                    const val = e.target.value.replace(/\D/g, '').slice(0, 16);
                                                    setCardNumber(val.replace(/(.{4})/g, '$1 ').trim());
                                                }}
                                            />
                                            <Lock className="w-4 h-4 text-stone-400 absolute left-3 top-2.5" />
                                        </div>
                                    </div>
                                    <div className="flex gap-3">
                                        <div className="flex-1">
                                            <label className="text-xs font-bold text-stone-500 uppercase">Platnost</label>
                                            <input 
                                                type="text" 
                                                placeholder="MM/YY" 
                                                className="w-full p-2 border border-stone-300 rounded-lg font-mono text-sm focus:ring-2 focus:ring-sage-500 outline-none"
                                                value={expiry}
                                                onChange={(e) => setExpiry(e.target.value)}
                                            />
                                        </div>
                                        <div className="w-1/3">
                                            <label className="text-xs font-bold text-stone-500 uppercase">CVC</label>
                                            <input 
                                                type="text" 
                                                placeholder="123" 
                                                className="w-full p-2 border border-stone-300 rounded-lg font-mono text-sm focus:ring-2 focus:ring-sage-500 outline-none"
                                                value={cvc}
                                                onChange={(e) => setCvc(e.target.value)}
                                            />
                                        </div>
                                    </div>
                                </div>
                            )}

                            {paymentMethod === 'cash' && (
                                <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100 flex gap-3 items-start mb-6">
                                    <Info className="w-5 h-5 text-yellow-600 mt-0.5" />
                                    <p className="text-sm text-yellow-800">
                                        Rezervace bude potvrzena, ale místo je garantováno až po úhradě na místě. Prosíme, dostavte se 10 minut předem.
                                    </p>
                                </div>
                            )}

                            <div className="mt-auto pt-4 flex gap-3">
                                <Button variant="ghost" onClick={() => setStep(1)} disabled={isProcessing}>
                                    Změnit termín
                                </Button>
                                <Button 
                                    onClick={handlePayAndBook} 
                                    className="flex-1 relative"
                                    disabled={isProcessing || (paymentMethod === 'card' && cardNumber.length < 10)}
                                >
                                    {isProcessing ? (
                                        <>
                                            <Loader2 className="w-4 h-4 animate-spin mr-2" />
                                            Zpracovávám platbu...
                                        </>
                                    ) : (
                                        `Zaplatit a rezervovat (${practitioner.pricePerHour} Kč)`
                                    )}
                                </Button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

const App = () => {
  // Global State for Data Persistence in Session
  const [practitioners, setPractitioners] = useState<Practitioner[]>(PRACTITIONERS);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedPractitioner, setSelectedPractitioner] = useState<Practitioner | null>(null);

  // State for pre-filling modal from Calendar click
  const [initialBookingDate, setInitialBookingDate] = useState<string>('');
  const [initialBookingTime, setInitialBookingTime] = useState<string>('');

  const handleBook = (practitioner: Practitioner, date?: string, time?: string) => {
    const upToDatePractitioner = practitioners.find(p => p.id === practitioner.id) || practitioner;

    if (date) setInitialBookingDate(date);
    else setInitialBookingDate('');

    if (time) setInitialBookingTime(time);
    else setInitialBookingTime('');

    setSelectedPractitioner(upToDatePractitioner);
  };

  const confirmBooking = (date: string, time: string, paymentMethod: 'card' | 'cash') => {
    if (selectedPractitioner) {
        const newBooking: Booking = {
            id: Date.now().toString(),
            practitionerId: selectedPractitioner.id,
            practitionerName: selectedPractitioner.name,
            date: date,
            time: time,
            status: 'confirmed',
            price: selectedPractitioner.pricePerHour,
            paymentMethod: paymentMethod,
            paymentStatus: paymentMethod === 'card' ? 'paid' : 'pay_at_venue'
        };
        setBookings(prev => [...prev, newBooking]);
        setSelectedPractitioner(null);
        alert(paymentMethod === 'card' 
            ? "Platba úspěšná! Rezervace potvrzena." 
            : "Rezervace potvrzena. Platba proběhne na místě."
        );
    }
  };

  const handleUpdatePractitioner = (updated: Practitioner) => {
    setPractitioners(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  return (
    <Router>
      <div className="min-h-screen bg-stone-50 font-sans text-stone-800 flex flex-col">
        <Navbar />

        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 flex-grow w-full">
