import React, { useState, useEffect } from 'react';
import { Practitioner, Booking, Service } from '../types';
import Button from '../components/Button';
import { Calendar, Check, Clock, Save, User, Settings, AlertCircle, Users, CreditCard, Wallet, Edit2, Plus, Trash2, LayoutList, Image as ImageIcon } from 'lucide-react';

interface PractitionerDashboardProps {
  practitioners: Practitioner[];
  updatePractitioner: (updated: Practitioner) => void;
  allBookings: Booking[];
}

const DAYS = ['Po', 'Út', 'St', 'Čt', 'Pá'];
const TIMES = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00', '17:00'];

const PractitionerDashboard: React.FC<PractitionerDashboardProps> = ({ 
  practitioners, 
  updatePractitioner,
  allBookings 
}) => {
  // Login simulation
  const [currentPractitionerId, setCurrentPractitionerId] = useState<string>(practitioners[0].id);
  const [activeTab, setActiveTab] = useState<'calendar' | 'profile'>('calendar');
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  const currentPractitioner = practitioners.find(p => p.id === currentPractitionerId)!;

  // Temporary state for editing entire practitioner object
  const [tempPractitioner, setTempPractitioner] = useState<Practitioner>(currentPractitioner);

  // Sync temp state when switching users
  useEffect(() => {
    setTempPractitioner(JSON.parse(JSON.stringify(currentPractitioner))); // Deep copy
    setHasUnsavedChanges(false);
  }, [currentPractitionerId, currentPractitioner]);

  // Filter bookings for current practitioner
  const myBookings = allBookings.filter(b => b.practitionerId === currentPractitionerId);

  // --- HANDLERS ---

  const handleSave = () => {
    updatePractitioner(tempPractitioner);
    setHasUnsavedChanges(false);
    alert('Změny byly úspěšně uloženy.');
  };

  // Calendar Handlers
  const getBookingCountForSlot = (dayName: string, time: string) => {
    return myBookings.filter(b => {
      const d = new Date(b.date);
      const bookingDayName = d.toLocaleDateString('cs-CZ', {weekday: 'short'}).replace('.', '');
      return bookingDayName === dayName && b.time === time && b.status === 'confirmed';
    }).length;
  };

  const toggleSlot = (day: string, time: string) => {
    const slotId = `${day}-${time}`;
    const bookingCount = getBookingCountForSlot(day, time);
    const isCurrentlyAvailable = tempPractitioner.availability.includes(slotId);

    if (isCurrentlyAvailable && bookingCount > 0) {
        const confirmRemove = window.confirm(
            `POZOR: Na čas ${day} ${time} máte již ${bookingCount} potvrzené rezervace!\n\nOpravdu chcete zrušit dostupnost?`
        );
        if (!confirmRemove) return;
    }

    setTempPractitioner(prev => {
      const newAvailability = prev.availability.includes(slotId)
        ? prev.availability.filter(id => id !== slotId)
        : [...prev.availability, slotId];

      return { ...prev, availability: newAvailability };
    });
    setHasUnsavedChanges(true);
  };

  // Profile Handlers
  const handleProfileChange = (field: keyof Practitioner, value: any) => {
      setTempPractitioner(prev => ({ ...prev, [field]: value }));
      setHasUnsavedChanges(true);
  };

  // Service Handlers
  const handleServiceChange = (index: number, field: keyof Service, value: any) => {
      const newServices = [...tempPractitioner.services];
      newServices[index] = { ...newServices[index], [field]: value };

      // Auto-set room based on type logic from sketch
      if (field === 'type') {
          if (value === '1-1') newServices[index].targetRoom = 1;
          if (value === 'group') newServices[index].targetRoom = 2;
          if (value === 'rental') newServices[index].targetRoom = 1; // Default
      }

      setTempPractitioner(prev => ({ ...prev, services: newServices }));
      setHasUnsavedChanges(true);
  };

  const addService = () => {
      const newService: Service = {
          id: Date.now().toString(),
          name: 'Nová Služba',
          durationMinutes: 60,
          price: 1000,
          type: '1-1',
          targetRoom: 1
      };
      setTempPractitioner(prev => ({ ...prev, services: [...prev.services, newService] }));
      setHasUnsavedChanges(true);
  };

  const removeService = (index: number) => {
      if (window.confirm('Opravdu chcete smazat tuto službu?')) {
          const newServices = tempPractitioner.services.filter((_, i) => i !== index);
          setTempPractitioner(prev => ({ ...prev, services: newServices }));
          setHasUnsavedChanges(true);
      }
  };

  return (
    <div className="animate-in fade-in duration-500 pb-12 space-y-8">

      {/* Top Bar / Login Simulator */}
      <div className="bg-white p-4 rounded-xl border border-stone-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4 sticky top-20 z-30">
        <div className="flex items-center gap-3">
          <div className="bg-sage-100 p-2 rounded-full">
            <User className="w-6 h-6 text-sage-700" />
          </div>
          <div>
             <span className="text-xs font-bold text-stone-400 uppercase tracking-wider">Lektorská zóna</span>
             <h2 className="font-heading font-bold text-lg text-stone-900">{tempPractitioner.name}</h2>
          </div>
        </div>

        <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
                <span className="text-xs text-stone-500 hidden md:inline">Přepnout profil (Demo):</span>
                <select 
                    className="bg-stone-50 border border-stone-200 text-stone-700 text-sm rounded-lg focus:ring-sage-500 focus:border-sage-500 block p-2"
                    value={currentPractitionerId}
                    onChange={(e) => setCurrentPractitionerId(e.target.value)}
                >
                    {practitioners.map(p => (
                        <option key={p.id} value={p.id}>{p.name}</option>
                    ))}
                </select>
            </div>

            <Button 
                onClick={handleSave} 
                disabled={!hasUnsavedChanges}
                size="sm"
                className={`flex items-center gap-2 ${hasUnsavedChanges ? 'animate-pulse ring-2 ring-sage-400 ring-offset-2' : ''}`}
            >
                <Save className="w-4 h-4" /> Uložit {hasUnsavedChanges ? 'změny' : ''}
            </Button>
        </div>
      </div>

      {/* Tabs Navigation */}
      <div className="flex gap-2 border-b border-stone-200">
          <button
            onClick={() => setActiveTab('calendar')}
            className={`px-6 py-3 font-medium text-sm transition-colors relative ${
                activeTab === 'calendar' 
                ? 'text-sage-800 border-b-2 border-sage-600' 
                : 'text-stone-500 hover:text-stone-800'
            }`}
          >
              <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4" /> Kalendář
              </div>
          </button>
          <button
            onClick={() => setActiveTab('profile')}
            className={`px-6 py-3 font-medium text-sm transition-colors relative ${
                activeTab === 'profile' 
                ? 'text-sage-800 border-b-2 border-sage-600' 
                : 'text-stone-500 hover:text-stone-800'
            }`}
          >
              <div className="flex items-center gap-2">
                  <Edit2 className="w-4 h-4" /> Profil a Služby
              </div>
          </button>
      </div>

      {/* === CALENDAR TAB === */}
      {activeTab === 'calendar' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in slide-in-from-bottom-2 fade-in">
            {/* Availability Editor */}
            <div className="lg:col-span-2 space-y-6">
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm overflow-hidden">
                    <div className="p-4 bg-stone-50 border-b border-stone-200 text-sm text-stone-500 flex items-center gap-2">
                        <AlertCircle className="w-4 h-4" />
                        Kliknutím na buňku označte čas jako dostupný.
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="text-xs text-stone-500 uppercase bg-stone-50 border-b border-stone-100">
                                <tr>
                                    <th className="px-6 py-4 font-medium">Čas</th>
                                    {DAYS.map(day => (
                                        <th key={day} className="px-6 py-4 font-bold text-center">{day}</th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody>
                                {TIMES.map(time => (
                                    <tr key={time} className="border-b border-stone-50 hover:bg-stone-50/50">
                                        <td className="px-6 py-4 font-medium text-stone-900 whitespace-nowrap bg-stone-50/30">
                                            {time}
                                        </td>
                                        {DAYS.map(day => {
                                            const isAvailable = tempPractitioner.availability.includes(`${day}-${time}`);
                                            const bookingCount = getBookingCountForSlot(day, time);

                                            return (
                                                <td key={`${day}-${time}`} className="p-2 text-center">
                                                    <button
                                                        onClick={() => toggleSlot(day, time)}
                                                        className={`relative w-full h-12 rounded-lg transition-all duration-200 border-2 font-medium flex flex-col items-center justify-center gap-0.5 ${
                                                            isAvailable 
                                                            ? 'bg-sage-500 border-sage-500 text-white shadow-sm hover:bg-sage-600' 
                                                            : 'bg-white border-stone-200 text-stone-300 hover:border-sage-300 hover:text-sage-400'
                                                        }`}
                                                    >
                                                        <div className="flex items-center gap-1">
                                                            {isAvailable ? <Check className="w-3 h-3" /> : <Settings className="w-3 h-3" />}
                                                            <span className="text-xs">{isAvailable ? 'Volno' : '-'}</span>
                                                        </div>

                                                        {bookingCount > 0 && (
                                                            <div className={`absolute -top-2 -right-2 flex items-center justify-center w-5 h-5 text-[10px] font-bold rounded-full shadow-sm border ${
                                                                isAvailable ? 'bg-white text-sage-700 border-sage-200' : 'bg-stone-600 text-white border-stone-700'
                                                            }`}>
                                                                {bookingCount}
                                                            </div>
                                                        )}
                                                    </button>
                                                </td>
                                            );
                                        })}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {/* Bookings Sidebar */}
            <div className="space-y-6">
                <h2 className="text-lg font-bold font-heading text-stone-900">Příchozí rezervace</h2>

                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-4 max-h-[600px] overflow-y-auto">
                    <div className="space-y-4">
                        {myBookings.length === 0 ? (
                            <p className="text-stone-500 text-center py-8">Zatím nemáte žádné rezervace.</p>
                        ) : (
                            myBookings.map(booking => (
                                <div key={booking.id} className="flex flex-col gap-3 p-4 rounded-lg bg-stone-50 border border-stone-100">
                                    <div className="flex items-start gap-3">
                                        <div className="bg-white p-2 rounded-full border border-stone-200 text-sage-600">
                                            <Calendar className="w-4 h-4" />
                                        </div>
                                        <div className="flex-1">
                                            <div className="flex justify-between items-start">
                                                <h4 className="font-bold text-stone-900 text-sm">Rezervace #{booking.id.slice(-4)}</h4>
                                                <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                                                    booking.status === 'confirmed' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'
                                                }`}>
                                                    {booking.status}
                                                </span>
                                            </div>
                                            <div className="mt-1 text-xs text-stone-600 space-y-1">
                                                <div className="font-medium text-sage-700">{booking.serviceName}</div>
                                                <div className="flex items-center gap-2">
                                                    <Clock className="w-3 h-3" />
                                                    {new Date(booking.date).toLocaleDateString('cs-CZ')} v {booking.time}
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    <div className={`flex items-center gap-2 text-[10px] font-bold px-2 py-1.5 rounded border ${
                                        booking.paymentStatus === 'paid' 
                                        ? 'bg-green-50 text-green-700 border-green-200' 
                                        : 'bg-yellow-50 text-yellow-700 border-yellow-200'
                                    }`}>
                                        {booking.paymentStatus === 'paid' ? <CreditCard className="w-3 h-3" /> : <Wallet className="w-3 h-3" />}
                                        {booking.paymentStatus === 'paid' ? 'Zaplaceno online' : `K úhradě: ${booking.price} Kč`}
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>
          </div>
      )}

      {/* === PROFILE & SERVICES TAB === */}
      {activeTab === 'profile' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-2 fade-in">

              {/* Profile Details */}
              <div className="space-y-6">
                  <h3 className="text-lg font-bold font-heading text-stone-900 flex items-center gap-2">
                      <User className="w-5 h-5" /> Osobní údaje
                  </h3>

                  <div className="bg-white p-6 rounded-xl border border-stone-200 shadow-sm space-y-4">
                      <div>
                          <label className="block text-sm font-medium text-stone-700 mb-1">Jméno</label>
                          <input 
                              type="text" 
                              value={tempPractitioner.name} 
                              onChange={(e) => handleProfileChange('name', e.target.value)}
                              className="w-full p-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none"
                          />
                      </div>
                      <div>
                          <label className="block text-sm font-medium text-stone-700 mb-1">Titul / Role</label>
                          <input 
                              type="text" 
                              value={tempPractitioner.title} 
                              onChange={(e) => handleProfileChange('title', e.target.value)}
                              className="w-full p-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none"
                          />
                      </div>
                      <div>
                          <label className="block text-sm font-medium text-stone-700 mb-1">Kategorie</label>
                          <select
                              value={tempPractitioner.category}
                              onChange={(e) => handleProfileChange('category', e.target.value)}
                              className="w-full p-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none bg-white"
                          >
                                <option>Terapie 1-1</option>
                                <option>Semináře</option>
                                <option>Pronájem prostor</option>
                          </select>
                      </div>
                      <div>
                          <label className="block text-sm font-medium text-stone-700 mb-1">Popis</label>
                          <textarea 
                              rows={4}
                              value={tempPractitioner.description} 
                              onChange={(e) => handleProfileChange('description', e.target.value)}
                              className="w-full p-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none resize-none"
                          />
                      </div>
                      <div>
                          <label className="block text-sm font-medium text-stone-700 mb-1">URL Fotografie</label>
                          <div className="flex gap-2">
                              <input 
                                  type="text" 
                                  value={tempPractitioner.imageUrl} 
                                  onChange={(e) => handleProfileChange('imageUrl', e.target.value)}
                                  className="w-full p-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none"
                              />
                              <div className="w-10 h-10 rounded-lg overflow-hidden bg-stone-200 flex-shrink-0">
                                  <img src={tempPractitioner.imageUrl} alt="Preview" className="w-full h-full object-cover" />
                              </div>
                          </div>
                      </div>
                  </div>
              </div>

              {/* Services Editor */}
              <div className="space-y-6">
                  <div className="flex justify-between items-center">
                    <h3 className="text-lg font-bold font-heading text-stone-900 flex items-center gap-2">
                        <LayoutList className="w-5 h-5" /> Nabízené služby
                    </h3>
                    <Button size="sm" onClick={addService} variant="secondary" className="text-xs">
                        <Plus className="w-4 h-4 mr-1" /> Přidat službu
                    </Button>
                  </div>

                  <div className="space-y-4">
                      {tempPractitioner.services.map((service, index) => (
                          <div key={service.id} className="bg-white p-4 rounded-xl border border-stone-200 shadow-sm relative group">
                              <button 
                                onClick={() => removeService(index)}
                                className="absolute top-2 right-2 p-1.5 text-stone-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                              >
                                  <Trash2 className="w-4 h-4" />
                              </button>

                              <div className="grid gap-4">
                                  <div>
                                      <label className="text-xs font-bold text-stone-500 uppercase">Název služby</label>
                                      <input 
                                          type="text" 
                                          value={service.name} 
                                          onChange={(e) => handleServiceChange(index, 'name', e.target.value)}
                                          className="w-full mt-1 p-1.5 border-b border-stone-200 focus:border-sage-500 outline-none font-medium text-stone-900"
                                      />
                                  </div>

                                  <div className="grid grid-cols-2 gap-4">
                                      <div>
                                          <label className="text-xs font-bold text-stone-500 uppercase">Cena (Kč)</label>
                                          <input 
                                              type="number" 
                                              value={service.price} 
                                              onChange={(e) => handleServiceChange(index, 'price', parseInt(e.target.value))}
                                              className="w-full mt-1 p-1.5 border-b border-stone-200 focus:border-sage-500 outline-none"
                                          />
                                      </div>
                                      <div>
                                          <label className="text-xs font-bold text-stone-500 uppercase">Délka (min)</label>
                                          <input 
                                              type="number" 
                                              value={service.durationMinutes} 
                                              onChange={(e) => handleServiceChange(index, 'durationMinutes', parseInt(e.target.value))}
                                              className="w-full mt-1 p-1.5 border-b border-stone-200 focus:border-sage-500 outline-none"
                                          />
                                      </div>
                                  </div>

                                  <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="text-xs font-bold text-stone-500 uppercase">Typ (Místnost)</label>
                                        <select
                                            value={service.type}
                                            onChange={(e) => handleServiceChange(index, 'type', e.target.value)}
                                            className="w-full mt-1 p-1.5 border-b border-stone-200 focus:border-sage-500 outline-none bg-white text-sm"
                                        >
                                            <option value="1-1">Individuální (Místnost 1)</option>
                                            <option value="group">Skupinové (Místnost 2)</option>
                                            <option value="rental">Pronájem</option>
                                        </select>
                                    </div>
                                    {service.type === 'group' && (
                                        <div>
                                            <label className="text-xs font-bold text-stone-500 uppercase">Kapacita</label>
                                            <input 
                                                type="number" 
                                                value={service.maxCapacity || 12} 
                                                onChange={(e) => handleServiceChange(index, 'maxCapacity', parseInt(e.target.value))}
                                                className="w-full mt-1 p-1.5 border-b border-stone-200 focus:border-sage-500 outline-none"
                                            />
                                        </div>
                                    )}
                                  </div>
                              </div>
                          </div>
                      ))}

                      {tempPractitioner.services.length === 0 && (
                          <div className="text-center py-8 bg-stone-50 rounded-xl border border-dashed border-stone-300 text-stone-500 text-sm">
                              Nemáte definované žádné služby.
                              <br/>
                              <button onClick={addService} className="text-sage-600 font-bold hover:underline mt-1">Přidat první službu</button>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

    </div>
  );
};

