// --- API SERVICES ---

/**
 * Creates a Stripe Payment Intent via Firebase Cloud Functions.
 * This is the secure way to handle payments without exposing secrets.
 */
export const createStripePaymentIntent = async (amount: number, currency: string = 'czk') => {
  if (!isFirebaseReady) {
    console.log("Mocking Cloud Function: createStripePaymentIntent");
    return new Promise((resolve) => setTimeout(() => resolve({ clientSecret: 'mock_secret_123' }), 1000));
  }

  const createPayment = httpsCallable(functions, 'createPaymentIntent');
  try {
    const result = await createPayment({ amount, currency });
    return result.data as { clientSecret: string };
  } catch (error) {
    console.error("Error creating payment intent:", error);
    throw error;
  }
};

/**
 * Saves a booking to Firestore.
 */
export const saveBookingToFirestore = async (booking: Booking) => {
    if (!isFirebaseReady) {
        console.log("Mocking Firestore Write:", booking);
        return true;
    }

    try {
        await addDoc(collection(db, 'bookings'), booking);
        return true;
    } catch (error) {
        console.error("Error saving booking:", error);
        return false;
    }
};

/**
 * Loads bookings from Firestore for a specific date range or practitioner.
 */
export const loadBookings = async () => {
    if (!isFirebaseReady) return [];

    try {
        const q = query(collection(db, 'bookings'));
        const querySnapshot = await getDocs(q);
        return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Booking));
    } catch (error) {
        console.error("Error loading bookings:", error);
        return [];
    }
};

