// Helper to generate some default availability
const generateDefaultAvailability = () => {
  const slots = [];
  const days = ['Po', 'Út', 'St', 'Čt', 'Pá'];
  const times = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00', '17:00', '18:00', '19:00'];

  days.forEach(day => {
    times.forEach(time => {
      if (Math.random() > 0.2) { // 80% available for demo
        slots.push(`${day}-${time}`);
      }
    });
  });
  return slots;
};

// Helper to generate rental services
const generateRentalServices = (): Service[] => {
    const durations = [60, 90, 120, 150, 180, 210, 240, 270, 300];
    const baseRatePerHour = 300;

    const services: Service[] = [];

    // Room 1 (Malá)
    durations.forEach(mins => {
        const price = (mins / 60) * baseRatePerHour;
        services.push({
            id: `r1-${mins}`,
            name: `Malá místnost (${mins} min)`,
            durationMinutes: mins,
            price: price,
            type: 'rental',
            targetRoom: 1
        });
    });

    // Room 2 (Velká) - Assuming same price for now based on instructions
    durations.forEach(mins => {
        const price = (mins / 60) * baseRatePerHour;
        services.push({
            id: `r2-${mins}`,
            name: `Velká místnost (${mins} min)`,
            durationMinutes: mins,
            price: price,
            type: 'rental',
            targetRoom: 2
        });
    });

    return services;
};

