};

const App = () => {
  // Global State for Data Persistence in Session
  const [practitioners, setPractitioners] = useState<Practitioner[]>(PRACTITIONERS);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedPractitioner, setSelectedPractitioner] = useState<Practitioner | null>(null);

  // State for pre-filling modal from Calendar click
  const [initialBookingDate, setInitialBookingDate] = useState<string>('');
  const [initialBookingTime, setInitialBookingTime] = useState<string>('');

  const handleBook = (practitioner: Practitioner, date?: string, time?: string) => {
    const upToDatePractitioner = practitioners.find(p => p.id === practitioner.id) || practitioner;

    if (date) setInitialBookingDate(date);
    else setInitialBookingDate('');

    if (time) setInitialBookingTime(time);
    else setInitialBookingTime('');

    setSelectedPractitioner(upToDatePractitioner);
  };

  const confirmBooking = async (date: string, time: string, paymentMethod: 'card' | 'cash' | 'apple_pay', service: Service) => {
    if (selectedPractitioner) {
        const newBooking: Booking = {
            id: Date.now().toString(),
            practitionerId: selectedPractitioner.id,
            practitionerName: selectedPractitioner.name,
            serviceName: service.name,
            date: date,
            time: time,
            durationMinutes: service.durationMinutes,
            status: 'confirmed',
            price: service.price,
            paymentMethod: paymentMethod,
            paymentStatus: paymentMethod === 'cash' ? 'pay_at_venue' : 'paid',
            room: service.targetRoom || 1 // Default to room 1 if not specified
        };

        // Save to Firebase (Simulated if no config)
        await saveBookingToFirestore(newBooking);

        setBookings(prev => [...prev, newBooking]);
        setSelectedPractitioner(null);
        alert(paymentMethod === 'cash' 
            ? "Rezervace potvrzena. Platba proběhne na místě."
            : "Platba úspěšná! Rezervace potvrzena." 
        );
    }
  };

  const handleUpdatePractitioner = (updated: Practitioner) => {
    setPractitioners(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  return (
    <Router>
      <div className="min-h-screen bg-stone-50 font-sans text-stone-800 flex flex-col">
        <Navbar />

        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 flex-grow w-full">
