    : CATEGORIES.filter(c => c !== 'Pronájem prostor');

  const filteredPractitioners = practitioners.filter(p => {
    // 2. If NOT logged in, hide practitioners with category "Pronájem prostor"
    if (!currentUser && (p.category === 'Pronájem prostor' || p.id === 'rental')) {
        return false;
    }

    const matchesCategory = selectedCategory === 'Vše' || p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          p.specialties.some(s => s.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Hero Section */}
      <div className="bg-sage-800 rounded-3xl p-8 md:p-12 text-white shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-sage-700 rounded-full mix-blend-multiply filter blur-3xl opacity-50 transform translate-x-1/2 -translate-y-1/2"></div>
