                        <div className="flex items-center gap-1.5"><div className="w-3 h-3 bg-blue-100 border border-blue-300 rounded-sm"></div><span className="text-blue-700 font-medium">R2 Obsazeno (Jinak)</span></div>
                        <div className="flex items-center gap-1.5"><div className="w-3 h-3 bg-green-500 rounded-sm"></div><span className="text-stone-900 font-bold">Moje Rezervace</span></div>
                        <div className="flex items-center gap-1.5 ml-auto border-l border-stone-200 pl-4">
                            <span className="text-stone-400 mr-1">Moje Dostupnost (Šablona):</span>
                            <div className="w-3 h-3 bg-sage-500 rounded-full"></div> Volno
                            <div className="w-3 h-3 border border-stone-300 bg-white rounded-full ml-2"></div> Nedostupné
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="text-xs text-stone-500 uppercase bg-stone-50 border-b border-stone-100">
                                <tr>
                                    <th className="px-4 py-4 font-medium text-center bg-stone-100/50 w-20">Čas</th>
                                    {weekDays.map(d => (
                                        <th key={d.toString()} className="px-4 py-4 font-bold text-center border-l border-stone-100 min-w-[140px]">
