                            </thead>
                            <tbody>
                                {TIMES.map(time => (
                                    <tr key={time} className="border-b border-stone-50 hover:bg-stone-50/30">
                                        <td className="px-4 py-2 font-bold text-stone-500 text-center bg-stone-50/50 border-r border-stone-100">
                                            {time}
                                        </td>
                                        {weekDays.map((date, dayIdx) => {
                                            const dayName = ['Po', 'Út', 'St', 'Čt', 'Pá'][dayIdx];
                                            const isTemplateSet = isTemplateAvailable(dayIdx, time);
                                            const status = getRoomStatus(date, time);

                                            // Determine dominant room state for styling
                                            const r1Taken = !!status.r1;
                                            const r2Taken = !!status.r2;
                                            const isMyBooking = !!status.myBooking;

                                            return (
                                                <td key={`${date}-${time}`} className="p-1 border-l border-stone-100 relative h-20 align-top">
                                                    <div className="flex flex-col h-full gap-1">
                                                        {/* Room Status Indicators */}
                                                        <div className="flex gap-1 h-full">
                                                            {/* ROOM 1 COLUMN */}
                                                            <div className={`flex-1 rounded-md flex flex-col items-center justify-center text-[10px] p-1 text-center transition-colors border ${
                                                                status.r1 
                                                                    ? (status.r1.practitionerId === currentUser.id ? 'bg-green-100 border-green-300 text-green-800' : 'bg-red-50 border-red-200 text-red-800')
                                                                    : 'bg-stone-50/50 border-dashed border-stone-200 text-stone-300'
