                                                                <span className="font-bold mb-0.5">R1</span>
                                                                {status.r1 ? (
                                                                    <span className="leading-tight truncate w-full" title={status.r1.practitionerName}>
                                                                        {status.r1.practitionerId === currentUser.id ? 'JA' : status.r1.practitionerName}
                                                                    </span>
                                                                ) : <span className="text-stone-200">-</span>}
                                                            </div>

                                                            {/* ROOM 2 COLUMN */}
                                                            <div className={`flex-1 rounded-md flex flex-col items-center justify-center text-[10px] p-1 text-center transition-colors border ${
                                                                status.r2
