                                                                {status.r2 ? (
                                                                    <span className="leading-tight truncate w-full" title={status.r2.practitionerName}>
                                                                        {status.r2.practitionerId === currentUser.id ? 'JA' : status.r2.practitionerName}
                                                                    </span>
                                                                ) : <span className="text-stone-200">-</span>}
                                                            </div>
                                                        </div>

                                                        {/* Availability Toggle Button (Overlay) */}
                                                        {/* Only show toggle if NO booking is present for ME */}
                                                        {!isMyBooking && (
                                                            <button
                                                                onClick={() => toggleSlot(dayName, time, undefined)}
