                                                            <div className="bg-green-600 text-white text-[10px] font-bold py-1 rounded text-center shadow-sm flex items-center justify-center gap-1">
                                                                <Check className="w-3 h-3" /> REZERVOVÁNO
                                                            </div>
                                                        )}
                                                    </div>
                                                </td>
                                            );
                                        })}
