                                        {booking.paymentStatus === 'paid' ? <CreditCard className="w-3 h-3" /> : <Wallet className="w-3 h-3" />}
                                        {booking.paymentStatus === 'paid' ? 'Zaplaceno' : `${booking.price} Kč`}
                                    </div>
