const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];

const BookingModal = ({ 
    practitioner, 
    onClose, 
    onConfirm,
    allBookings,
    initialDate,
    initialTime
}: { 
    practitioner: Practitioner | null, 
    onClose: () => void, 
    onConfirm: (date: string, time: string, paymentMethod: 'card' | 'cash' | 'apple_pay', service: Service) => void,
    allBookings: Booking[],
    initialDate?: string,
    initialTime?: string
}) => {
    // --- STATE ---
    const [step, setStep] = useState<0 | 1 | 2>(0); // 0: Service, 1: Date, 2: Payment
    const [selectedService, setSelectedService] = useState<Service | null>(null);
    const [selectedDate, setSelectedDate] = useState<string>(initialDate || '');
    const [selectedTime, setSelectedTime] = useState<string>(initialTime || '');

    // Payment State
    const [paymentMethod, setPaymentMethod] = useState<'card' | 'cash' | 'apple_pay'>('apple_pay');
    const [isProcessing, setIsProcessing] = useState(false);

    // Direct Apple Pay Availability
    const [isApplePayAvailable, setIsApplePayAvailable] = useState(false);

    useEffect(() => {
        // Check for Apple Pay support on mount
        if (window.ApplePaySession && window.ApplePaySession.canMakePayments()) {
            setIsApplePayAvailable(true);
        }
    }, []);

    useEffect(() => {
        // If coming from calendar with initial data, auto-select first service and go to date
        if (initialDate && initialTime && practitioner?.services.length) {
            setSelectedService(practitioner.services[0]);
            setStep(1);
        }
    }, [initialDate, initialTime, practitioner]);

    if (!practitioner) return null;

    // --- LOGIC ---
    const dates = Array.from({length: 5}, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() + i + 1);
        return d.toISOString().split('T')[0];
    });

    if (initialDate && !dates.includes(initialDate)) {
        dates.unshift(initialDate);
    }

    const ALL_TIMES = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00', '17:00', '18:00', '19:00'];

    const getSlotStatus = (date: string, time: string): 'available' | 'room_full' | 'practitioner_busy' => {
        if (!selectedService) return 'available';

        const d = new Date(date);
        const dayName = DAYS_MAP[d.getDay()];
        const slotKey = `${dayName}-${time}`;

        if (!practitioner.availability.includes(slotKey)) return 'practitioner_busy';

        const candidateStart = timeToMinutes(time);
        const candidateEnd = candidateStart + selectedService.durationMinutes;

        const relevantBookings = allBookings.filter(b => 
            b.date === date && 
            b.status === 'confirmed'
        );

        for (const booking of relevantBookings) {
            const bookingStart = timeToMinutes(booking.time);
            const bookingEnd = bookingStart + booking.durationMinutes;
            const isOverlapping = (candidateStart < bookingEnd) && (candidateEnd > bookingStart);

            if (isOverlapping) {
                if (selectedService.type === 'rental') {
                     if (booking.room === selectedService.targetRoom) return 'room_full';
                }
                else if (selectedService.type === '1-1') {
                    if (booking.practitionerId === practitioner.id) return 'practitioner_busy';
                    if (booking.room === selectedService.targetRoom) return 'room_full';
                }
                else if (selectedService.type === 'group') {
                    if (booking.practitionerId === practitioner.id) return 'practitioner_busy';
                     if (booking.room === selectedService.targetRoom) return 'room_full'; 
                }
            }
        }

        return 'available';
    };

    const processDirectApplePay = () => {
        if (!selectedService) return;
        const request = {
            countryCode: 'CZ',
            currencyCode: 'CZK',
            supportedNetworks: ['visa', 'masterCard', 'amex'],
            merchantCapabilities: ['supports3DS'],
            total: { label: 'Centrum Unity', amount: selectedService.price.toString() }
        };
        try {
            const session = new window.ApplePaySession(3, request);
            session.onvalidatemerchant = (event: any) => {
                console.log("Validating Merchant URL:", event.validationURL);
                alert("Development Mode: Apple Pay Validation Step reached.");
                session.abort();
            };
            session.onpaymentauthorized = (event: any) => {
                session.completePayment(window.ApplePaySession.STATUS_SUCCESS);
                onConfirm(selectedDate, selectedTime, 'apple_pay', selectedService);
            };
            session.begin();
        } catch (e) {
            console.error("Apple Pay Error:", e);
            alert("Direct Apple Pay simulation: Platba proběhla úspěšně (Mock).");
            onConfirm(selectedDate, selectedTime, 'apple_pay', selectedService);
        }
    };

    const handlePayAndBook = async () => {
        if (!selectedService) return;
        setIsProcessing(true);

        if (paymentMethod === 'apple_pay') {
            setTimeout(() => { setIsProcessing(false); processDirectApplePay(); }, 500);
            return;
        } 

        if (paymentMethod === 'card') {
            try {
                const { clientSecret } = await createStripePaymentIntent(selectedService.price * 100);
                setTimeout(() => {
                    setIsProcessing(false);
                    onConfirm(selectedDate, selectedTime, paymentMethod, selectedService);
                }, 1500);
            } catch (error) {
                console.error("Payment failed", error);
                setIsProcessing(false);
                alert("Chyba při komunikaci s platební bránou.");
            }
            return;
        }

        setTimeout(() => {
            setIsProcessing(false);
            onConfirm(selectedDate, selectedTime, paymentMethod, selectedService);
        }, 1000);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl w-full max-w-4xl overflow-hidden shadow-2xl flex flex-col md:flex-row h-[600px] md:h-[600px]">
                {/* Left Side - Info */}
                <div className="bg-sage-600 text-white p-8 md:w-1/3 flex flex-col justify-between relative overflow-hidden">
                    <div className="relative z-10">
                        <div className="flex items-center gap-2 mb-6 cursor-pointer opacity-80 hover:opacity-100" onClick={onClose}>
                             <ChevronLeft className="w-4 h-4" /> Zpět
                        </div>
                        <h2 className="text-2xl font-bold font-heading mb-2">
                            {step === 0 ? 'Výběr služby' : step === 1 ? 'Výběr termínu' : 'Platba'}
                        </h2>
                        <div className="w-12 h-1 bg-white/30 rounded-full mb-6"></div>
                        <div className="space-y-6">
                             <div>
                                <p className="text-sage-200 text-xs uppercase tracking-wider mb-1">Terapeut</p>
                                <p className="font-bold text-lg leading-tight">{practitioner.name}</p>
                                <p className="text-sage-100 text-sm">{practitioner.title}</p>
                            </div>
                            {selectedService && (
                                <div className="bg-white/10 p-3 rounded-lg border border-white/10 animate-in fade-in">
                                    <p className="text-sage-200 text-xs uppercase tracking-wider mb-1">Služba</p>
                                    <p className="font-bold">{selectedService.name}</p>
                                    <p className="text-sm opacity-80">{selectedService.price} Kč • {selectedService.durationMinutes} min</p>
                                </div>
                            )}
                            {selectedDate && selectedTime && (
                                <div className="bg-white/10 p-3 rounded-lg border border-white/10 animate-in fade-in">
                                    <p className="text-sage-200 text-xs uppercase tracking-wider mb-1">Termín</p>
                                    <div className="flex items-center gap-2 font-bold">
                                        <CalendarIcon className="w-4 h-4" />
                                        {new Date(selectedDate).toLocaleDateString('cs-CZ')}
                                    </div>
                                    <div className="flex items-center gap-2 mt-1">
                                        <div className="bg-white/20 px-2 py-0.5 rounded text-sm">{selectedTime}</div>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Right Side - Interactive Steps */}
                <div className="p-8 md:w-2/3 flex flex-col h-full bg-white overflow-y-auto">
                    {step === 0 && (
                        <div className="flex-grow space-y-4 animate-in slide-in-from-right-8 duration-300">
                             {practitioner.id === 'rental' && (
                                <div className="bg-blue-50 border border-blue-100 p-4 rounded-xl mb-4 flex gap-3">
                                    <Info className="w-5 h-5 text-blue-600 flex-shrink-0" />
                                    <div>
                                        <h4 className="font-bold text-blue-800 text-sm">Pronájem pro skupiny</h4>
                                        <p className="text-xs text-blue-700 mt-1">
                                            Chystáte skupinovou akci? Pro rezervaci celého prostoru pro skupiny nás prosím kontaktujte e-mailem na <a href="mailto:info@centrumunity.cz" className="underline font-bold">info@centrumunity.cz</a>.
                                        </p>
                                    </div>
                                </div>
                            )}
                            <h3 className="text-lg font-bold text-stone-900 mb-4 flex items-center gap-2">
                                <span className="bg-stone-900 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs">1</span>
                                Vyberte službu
                            </h3>
                            <div className="grid gap-3">
                                {practitioner.services.map(service => (
                                    <button
                                        key={service.id}
                                        onClick={() => setSelectedService(service)}
                                        className={`p-4 rounded-xl border-2 text-left transition-all hover:shadow-md flex justify-between items-center ${
                                            selectedService?.id === service.id
                                            ? 'border-sage-600 bg-sage-50 ring-1 ring-sage-600'
                                            : 'border-stone-100 hover:border-sage-300'
                                        }`}
                                    >
                                        <div>
                                            <div className="font-bold text-stone-900">{service.name}</div>
                                            <div className="text-sm text-stone-500 mt-1">{service.durationMinutes} minut</div>
                                        </div>
                                        <div className="text-lg font-bold text-sage-700">
                                            {service.price} Kč
                                        </div>
                                    </button>
                                ))}
                            </div>
                            <div className="pt-8 mt-auto flex justify-end">
                                <Button onClick={() => setStep(1)} disabled={!selectedService} className="w-full sm:w-auto">Pokračovat</Button>
                            </div>
                        </div>
                    )}

                    {step === 1 && (
                        <div className="flex-grow space-y-6 animate-in slide-in-from-right-8 duration-300">
                             <div>
                                <h3 className="text-lg font-bold text-stone-900 mb-4 flex items-center gap-2">
                                    <span className="bg-stone-900 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs">2</span>
                                    Vyberte datum
                                </h3>
                                <div className="flex gap-2 overflow-x-auto pb-4 scrollbar-hide">
                                    {dates.map(date => {
                                        const d = new Date(date);
                                        const dayName = DAYS_MAP[d.getDay()];
                                        const dayNum = d.getDate();
                                        const isSelected = selectedDate === date;

                                        return (
                                            <button
                                                key={date}
                                                onClick={() => { setSelectedDate(date); setSelectedTime(''); }}
                                                className={`flex flex-col items-center justify-center min-w-[70px] p-3 rounded-xl border-2 transition-all duration-200 ${
                                                    isSelected 
                                                    ? 'border-sage-600 bg-sage-50 text-sage-800 shadow-sm transform scale-105' 
                                                    : 'border-stone-100 text-stone-500 hover:border-sage-200 hover:bg-stone-50'
                                                }`}
                                            >
                                                <span className="text-xs font-medium uppercase">{dayName}</span>
                                                <span className="text-xl font-bold font-heading">{dayNum}</span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                            <div className={`transition-all duration-300 ${selectedDate ? 'opacity-100' : 'opacity-50 pointer-events-none'}`}>
                                <h3 className="text-lg font-bold text-stone-900 mb-4 flex items-center gap-2">
                                    <span className="bg-stone-900 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs">3</span>
                                    Vyberte čas
                                </h3>
                                <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                    {ALL_TIMES.map(time => {
                                        const status = selectedDate ? getSlotStatus(selectedDate, time) : 'available';
                                        const isSelected = selectedTime === time;
                                        const isAvailable = status === 'available';
                                        let statusText = '';
                                        if (status === 'room_full') statusText = 'Plno';
                                        if (status === 'practitioner_busy') statusText = 'Obsazeno';

                                        return (
                                            <button
                                                key={time}
                                                disabled={!isAvailable}
                                                onClick={() => setSelectedTime(time)}
                                                className={`relative p-3 rounded-xl border text-center transition-all ${
                                                    isSelected 
                                                    ? 'border-sage-600 bg-sage-600 text-white shadow-md' 
                                                    : isAvailable
                                                        ? 'border-stone-200 hover:border-sage-400 hover:bg-sage-50 text-stone-800'
                                                        : 'border-stone-100 bg-stone-50 opacity-40 cursor-not-allowed'
                                                }`}
                                            >
                                                <span className="font-bold text-sm">{time}</span>
                                                {!isAvailable && <span className="block text-[10px] text-red-500">{statusText}</span>}
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                            <div className="pt-8 mt-auto flex justify-between">
                                <Button variant="ghost" onClick={() => setStep(0)}>Zpět na služby</Button>
                                <Button onClick={() => setStep(2)} disabled={!selectedDate || !selectedTime}>Pokračovat k platbě <ChevronRight className="w-4 h-4 ml-2" /></Button>
                            </div>
                        </div>
                    )}

                    {step === 2 && selectedService && (
                        <div className="flex-grow flex flex-col animate-in slide-in-from-right-8 duration-300">
                             <div className="mb-6">
                                <h3 className="text-lg font-bold text-stone-900 mb-4 flex items-center gap-2">
                                    <span className="bg-stone-900 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs">4</span>
                                    Způsob platby
                                </h3>
                                <div className="bg-orange-50 border border-orange-100 p-4 rounded-xl mb-6 flex gap-3">
                                    <AlertCircle className="w-5 h-5 text-orange-600 flex-shrink-0" />
                                    <div>
                                        <h4 className="font-bold text-orange-800 text-sm">Storno podmínky</h4>
                                        <p className="text-xs text-orange-700 mt-1">
                                            Zrušení rezervace je možné do 24 hodin předem s nárokem na vrácení plné částky.
                                        </p>
                                    </div>
                                </div>
                                <div className="space-y-3">
                                    <label className={`flex items-center p-4 border-2 rounded-xl cursor-pointer transition-all ${paymentMethod === 'apple_pay' ? 'border-black bg-stone-50 shadow-md' : 'border-stone-200 hover:border-stone-300'} ${!isApplePayAvailable ? 'opacity-50 grayscale' : ''}`}>
                                        <input type="radio" name="payment" className="hidden" checked={paymentMethod === 'apple_pay'} onChange={() => setPaymentMethod('apple_pay')} disabled={!isApplePayAvailable} />
                                        <div className={`p-2 rounded-full mr-4 ${paymentMethod === 'apple_pay' ? 'bg-black text-white' : 'bg-stone-100 text-stone-400'}`}><Apple className="w-5 h-5" /></div>
                                        <div className="flex-1"><span className="font-bold block text-stone-900">Apple Pay (Direct)</span><span className="text-xs text-stone-500">{isApplePayAvailable ? 'Rychlá a bezpečná platba' : 'Není dostupné na tomto zařízení'}</span></div>
                                        {paymentMethod === 'apple_pay' && <CheckCircle className="w-5 h-5 text-black" />}
                                    </label>
                                    <label className={`flex items-center p-4 border-2 rounded-xl cursor-pointer transition-all ${paymentMethod === 'card' ? 'border-sage-500 bg-sage-50' : 'border-stone-200 hover:border-stone-300'}`}>
                                        <input type="radio" name="payment" className="hidden" checked={paymentMethod === 'card'} onChange={() => setPaymentMethod('card')} />
                                        <div className={`p-2 rounded-full mr-4 ${paymentMethod === 'card' ? 'bg-sage-500 text-white' : 'bg-stone-100 text-stone-400'}`}><CreditCard className="w-5 h-5" /></div>
                                        <div className="flex-1"><span className="font-bold block text-stone-900">Platební karta</span><span className="text-xs text-stone-500">Klasická platba kartou</span></div>
                                        {paymentMethod === 'card' && <CheckCircle className="w-5 h-5 text-sage-600" />}
                                    </label>
                                    <label className={`flex items-center p-4 border-2 rounded-xl cursor-pointer transition-all ${paymentMethod === 'cash' ? 'border-sage-500 bg-sage-50' : 'border-stone-200 hover:border-stone-300'}`}>
                                        <input type="radio" name="payment" className="hidden" checked={paymentMethod === 'cash'} onChange={() => setPaymentMethod('cash')} />
                                        <div className={`p-2 rounded-full mr-4 ${paymentMethod === 'cash' ? 'bg-sage-500 text-white' : 'bg-stone-100 text-stone-400'}`}><Wallet className="w-5 h-5" /></div>
                                        <div className="flex-1"><span className="font-bold block text-stone-900">Hotově na místě</span><span className="text-xs text-stone-500">Rezervace s povinností platby</span></div>
                                        {paymentMethod === 'cash' && <CheckCircle className="w-5 h-5 text-sage-600" />}
                                    </label>
                                </div>
                            </div>
                            {paymentMethod === 'card' && (
                                <div className="bg-stone-50 p-6 rounded-xl border border-stone-200 space-y-4 mb-6 animate-in fade-in relative overflow-hidden">
                                     {/* Credit Card Fields Sim */}
                                    <div className="flex items-center justify-between mb-2">
                                        <div className="text-xs font-bold text-stone-500 uppercase flex items-center gap-1"><Lock className="w-3 h-3" /> Zabezpečená platba</div>
                                        <div className="flex gap-2 opacity-50 grayscale"><div className="h-4 w-6 bg-stone-300 rounded"></div><div className="h-4 w-6 bg-stone-300 rounded"></div></div>
                                    </div>
                                    <div className="space-y-4">
                                        <div><label className="text-xs font-bold text-stone-500 uppercase mb-1 block">Číslo karty</label><div className="relative"><CreditCard className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400 w-5 h-5" /><input type="text" placeholder="0000 0000 0000 0000" className="w-full pl-10 p-3 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none bg-white font-mono text-sm shadow-sm" /></div></div>
                                        <div className="grid grid-cols-2 gap-4"><div><label className="text-xs font-bold text-stone-500 uppercase mb-1 block">Platnost</label><input type="text" placeholder="MM / RR" className="w-full p-3 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none bg-white font-mono text-sm shadow-sm text-center" /></div><div><label className="text-xs font-bold text-stone-500 uppercase mb-1 block">CVC / CVV</label><div className="relative"><input type="text" placeholder="123" className="w-full p-3 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none bg-white font-mono text-sm shadow-sm text-center" /><ShieldCheck className="absolute right-3 top-1/2 -translate-y-1/2 text-stone-300 w-4 h-4" /></div></div></div>
                                    </div>
                                    <div className="mt-4 pt-4 border-t border-stone-200 text-center"><p className="text-[10px] text-stone-400 flex items-center justify-center gap-1"><Lock className="w-3 h-3" /> Platba je šifrována pomocí SSL certifikátu.</p></div>
                                </div>
                            )}
                            <div className="mt-auto pt-4 flex gap-3">
                                <Button variant="ghost" onClick={() => setStep(1)} disabled={isProcessing}>Zpět</Button>
                                <Button onClick={handlePayAndBook} className={`flex-1 relative ${paymentMethod === 'apple_pay' ? 'bg-black hover:bg-gray-800' : ''}`} disabled={isProcessing}>
                                    {isProcessing ? <><Loader2 className="w-4 h-4 animate-spin mr-2" /> Zpracovávám...</> : <>{paymentMethod === 'apple_pay' && <Apple className="w-4 h-4 mr-2" />}{paymentMethod === 'card' && <CreditCard className="w-4 h-4 mr-2" />}{paymentMethod === 'cash' && <Wallet className="w-4 h-4 mr-2" />} Zaplatit {selectedService.price} Kč</>}
                                </Button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

const AppContent = () => {
  // Global State for Data Persistence in Session
  const [practitioners, setPractitioners] = useState<Practitioner[]>(PRACTITIONERS);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedPractitioner, setSelectedPractitioner] = useState<Practitioner | null>(null);

  // Auth State
  const [currentUser, setCurrentUser] = useState<Practitioner | null>(null);

  // State for pre-filling modal from Calendar click
  const [initialBookingDate, setInitialBookingDate] = useState<string>('');
  const [initialBookingTime, setInitialBookingTime] = useState<string>('');

  const navigate = useNavigate();

  const handleBook = (practitioner: Practitioner, date?: string, time?: string) => {
    // AUTH CHECK: Only logged in practitioners can book
    if (!currentUser) {
        navigate('/login');
        return;
    }

    const upToDatePractitioner = practitioners.find(p => p.id === practitioner.id) || practitioner;

    if (date) setInitialBookingDate(date);
    else setInitialBookingDate('');

    if (time) setInitialBookingTime(time);
    else setInitialBookingTime('');

    setSelectedPractitioner(upToDatePractitioner);
  };

  // NEW: Specific handler for internal practitioner bookings (bypassing payment)
  const handleInternalBooking = async (date: string, time: string, service: Service, clientName?: string) => {
      if (!currentUser) return;

      const newBooking: Booking = {
          id: Date.now().toString(),
          practitionerId: currentUser.id,
          practitionerName: currentUser.name,
          serviceName: service.name + (clientName ? ` (${clientName})` : ''),
          date: date,
          time: time,
          durationMinutes: service.durationMinutes,
          status: 'confirmed',
          price: service.price,
          paymentMethod: 'cash', // Default to cash/internal
          paymentStatus: 'pay_at_venue', // Internal tracking
          room: service.targetRoom || 1
      };

      await saveBookingToFirestore(newBooking);
      setBookings(prev => [...prev, newBooking]);
      alert("Rezervace byla úspěšně vytvořena.");
  };

  const confirmBooking = async (date: string, time: string, paymentMethod: 'card' | 'cash' | 'apple_pay', service: Service) => {
    if (selectedPractitioner) {
        const newBooking: Booking = {
            id: Date.now().toString(),
            practitionerId: selectedPractitioner.id,
            practitionerName: selectedPractitioner.name,
            serviceName: service.name,
            date: date,
            time: time,
            durationMinutes: service.durationMinutes,
            status: 'confirmed',
            price: service.price,
            paymentMethod: paymentMethod,
            paymentStatus: paymentMethod === 'cash' ? 'pay_at_venue' : 'paid',
            room: service.targetRoom || 1 // Default to room 1 if not specified
        };

        await saveBookingToFirestore(newBooking);

        setBookings(prev => [...prev, newBooking]);
        setSelectedPractitioner(null);
        alert(paymentMethod === 'cash' 
            ? "Rezervace potvrzena. Platba proběhne na místě."
            : "Platba úspěšná! Rezervace potvrzena." 
        );
    }
  };

  const handleCancelBooking = (bookingId: string) => {
      if (window.confirm("Opravdu chcete zrušit tuto rezervaci?")) {
          setBookings(prev => prev.map(b => 
              b.id === bookingId ? { ...b, status: 'pending' } : b // In real app, we might delete or set to 'cancelled'
          ).filter(b => b.id !== bookingId)); // Removing for demo purposes to clear the slot
          alert("Rezervace byla zrušena.");
      }
  };

  const handleUpdatePractitioner = (updated: Practitioner) => {
    setPractitioners(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  const handleLogin = (user: Practitioner) => {
      setCurrentUser(user);
  };

  const handleLogout = () => {
      setCurrentUser(null);
      navigate('/');
  };

  return (
      <div className="min-h-screen bg-stone-50 font-sans text-stone-800 flex flex-col">
        <Navbar currentUser={currentUser} onLogout={handleLogout} />

        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 flex-grow w-full">
          <Routes>
            <Route path="/" element={<Directory practitioners={practitioners} onBook={handleBook} currentUser={currentUser} />} />
            <Route path="/login" element={<Login onLogin={handleLogin} />} />
            <Route 
                path="/calendar" 
                element={
                    <CalendarView 
                        practitioners={practitioners} 
                        bookings={bookings} 
                        onBook={handleBook}
                    />
                } 
            />
            <Route path="/services" element={<Services />} />
            <Route path="/about" element={<About />} />
            <Route path="/team" element={<Team onBook={handleBook} />} />
            <Route path="/dashboard" element={<Dashboard bookings={bookings} />} />
            <Route 
                path="/practitioner" 
                element={
                    <PractitionerDashboard 
                        practitioners={practitioners} 
                        updatePractitioner={handleUpdatePractitioner} 
                        allBookings={bookings}
                        currentUser={currentUser}
                        onCancelBooking={handleCancelBooking}
                        onInternalBook={handleInternalBooking}
                    />
                } 
            />
          </Routes>
        </main>

        <footer className="bg-white border-t border-stone-200 mt-12 py-12">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-8">
                    <div className="flex flex-col items-center md:items-start text-center md:text-left">
                        <div className="flex items-center gap-3 mb-4">
                            <img src="logo.png" alt="Centrum Unity Logo" className="h-12 w-12 rounded-full object-cover" />
                            <div>
                                <h3 className="font-bold text-lg text-stone-900 leading-tight font-heading">Centrum Unity</h3>
                                <p className="text-xs text-sage-600 font-medium">Prostor péče a duchovního rozvoje</p>
                            </div>
                        </div>
                    </div>
                    <div className="md:col-span-2 flex flex-col items-center md:items-end justify-center text-center md:text-right">
                        <div className="space-y-3">
                            <div className="flex items-center gap-3 justify-center md:justify-end group">
                                <Phone className="w-5 h-5 text-sage-600 group-hover:text-sage-700" />
                                <a href="tel:+420704003433" className="text-stone-600 hover:text-sage-700 font-medium transition-colors">+420 704 003 433</a>
                            </div>
                            <div className="flex items-center gap-3 justify-center md:justify-end group">
                                <Mail className="w-5 h-5 text-sage-600 group-hover:text-sage-700" />
                                <a href="mailto:info@centrumunity.cz" className="text-stone-600 hover:text-sage-700 font-medium transition-colors">info@centrumunity.cz</a>
                            </div>
                            <div className="flex items-center gap-3 justify-center md:justify-end group">
                                <MapPin className="w-5 h-5 text-sage-600 group-hover:text-sage-700" />
                                <span className="text-stone-600 font-medium">Šmilovského 10, Praha 2, 12000</span>
                            </div>
                        </div>
                    </div>
                </div>
                <div className="border-t border-stone-100 pt-8 flex flex-col md:flex-row justify-between items-center gap-4 text-sm text-stone-400">
                    <p>&copy; 2026 Centrum Unity. Všechna práva vyhrazena.</p>
                </div>
            </div>
        </footer>

        {selectedPractitioner && (
            <BookingModal 
                practitioner={selectedPractitioner} 
                onClose={() => setSelectedPractitioner(null)} 
                onConfirm={confirmBooking}
                allBookings={bookings}
                initialDate={initialBookingDate}
                initialTime={initialBookingTime}
            />
        )}

        <AIChatBot />
      </div>
  );
};

const App = () => {
    return (
        <HashRouter>
            <AppContent />
        </HashRouter>
    );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Practitioner, Booking, Service } from '../types';
import Button from '../components/Button';
import { Calendar, Check, Clock, Save, User, Settings, AlertCircle, Users, CreditCard, Wallet, Edit2, Plus, Trash2, LayoutList, Image as ImageIcon, Lock, Download, BoxSelect, ChevronLeft, ChevronRight, MapPin, X } from 'lucide-react';
import { Link } from 'react-router-dom';

interface PractitionerDashboardProps {
  practitioners: Practitioner[];
  updatePractitioner: (updated: Practitioner) => void;
  allBookings: Booking[];
  currentUser: Practitioner | null;
  onCancelBooking: (id: string) => void;
  onInternalBook: (date: string, time: string, service: Service, clientName?: string) => void;
}

const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So']; 
const TIMES = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00', '17:00', '18:00', '19:00'];

const PractitionerDashboard: React.FC<PractitionerDashboardProps> = ({ 
  practitioners, 
  updatePractitioner,
  allBookings,
  currentUser,
  onCancelBooking,
  onInternalBook
}) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'profile'>('calendar');
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [currentWeekStart, setCurrentWeekStart] = useState(new Date());

  // Temporary state for editing entire practitioner object
  const [tempPractitioner, setTempPractitioner] = useState<Practitioner | null>(currentUser);

  // Internal Booking Modal State
  const [showBookingModal, setShowBookingModal] = useState(false);
  const [bookingSlot, setBookingSlot] = useState<{date: string, time: string, room: 1 | 2} | null>(null);
  const [selectedInternalService, setSelectedInternalService] = useState<Service | null>(null);
  const [internalClientName, setInternalClientName] = useState('');

  useEffect(() => {
    if (currentUser) {
        setTempPractitioner(JSON.parse(JSON.stringify(currentUser)));
    } else {
        setTempPractitioner(null);
    }
    setHasUnsavedChanges(false);
  }, [currentUser]);

  if (!currentUser || !tempPractitioner) {
      return (
          <div className="flex flex-col items-center justify-center py-20 animate-in fade-in">
              <div className="w-16 h-16 bg-stone-200 rounded-full flex items-center justify-center mb-6">
                  <Lock className="w-8 h-8 text-stone-500" />
              </div>
              <h2 className="text-2xl font-bold text-stone-900 mb-2">Přístup odepřen</h2>
              <p className="text-stone-600 mb-8 text-center max-w-md">
                  Pro přístup do lektorské zóny a správu vašeho profilu se musíte přihlásit.
              </p>
              <Link to="/login">
                  <Button>Přejít na přihlášení</Button>
              </Link>
          </div>
      );
  }

  const myBookings = allBookings.filter(b => b.practitionerId === currentUser.id);

  // --- CALENDAR HELPERS ---
  const changeWeek = (offset: number) => {
    const newDate = new Date(currentWeekStart);
    newDate.setDate(newDate.getDate() + (offset * 7));
    setCurrentWeekStart(newDate);
  };

  const weekDays = Array.from({ length: 5 }, (_, i) => {
    const d = new Date(currentWeekStart);
    // Adjust to Monday of current week if today isn't Monday
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    d.setDate(diff + i);
    return d;
  });

  const formatDate = (date: Date) => date.toISOString().split('T')[0];

  // Check generic availability (template)
  const isTemplateAvailable = (dayIndex: number, time: string) => {
      // dayIndex 0 = Monday, etc.
      const dayName = ['Po', 'Út', 'St', 'Čt', 'Pá'][dayIndex];
      return tempPractitioner.availability.includes(`${dayName}-${time}`);
  };

  // Get Room Status for a specific real date & time
  const getRoomStatus = (date: Date, time: string) => {
      const dateStr = formatDate(date);
      // Find ALL bookings for this slot (anyone)
      const slotBookings = allBookings.filter(b => 
          b.date === dateStr && 
          b.time === time && 
          b.status === 'confirmed'
      );

      const r1Booking = slotBookings.find(b => b.room === 1);
      const r2Booking = slotBookings.find(b => b.room === 2);

      return {
          r1: r1Booking,
          r2: r2Booking,
          myBooking: slotBookings.find(b => b.practitionerId === currentUser.id)
      };
  };

  // --- HANDLERS ---
  const handleSave = () => {
    if (tempPractitioner) {
        updatePractitioner(tempPractitioner);
        setHasUnsavedChanges(false);
        alert('Změny byly úspěšně uloženy.');
    }
  };

  const toggleSlot = (dayName: string, time: string) => {
    // This toggles the generic availability template
    const slotId = `${dayName}-${time}`;
    setTempPractitioner(prev => {
      if (!prev) return null;
      const newAvailability = prev.availability.includes(slotId)
        ? prev.availability.filter(id => id !== slotId)
        : [...prev.availability, slotId];
      return { ...prev, availability: newAvailability };
    });
    setHasUnsavedChanges(true);
  };

  // Internal Booking Logic
  const openInternalBooking = (date: string, time: string, room: 1 | 2) => {
      setBookingSlot({ date, time, room });
      // Pre-select first service that matches the room if possible
      const matchingService = tempPractitioner.services.find(s => {
          if (room === 1 && (s.type === '1-1' || s.targetRoom === 1)) return true;
          if (room === 2 && (s.type === 'group' || s.targetRoom === 2)) return true;
          return false;
      });
      setSelectedInternalService(matchingService || tempPractitioner.services[0] || null);
      setInternalClientName('');
      setShowBookingModal(true);
  };

  const submitInternalBooking = () => {
      if (bookingSlot && selectedInternalService) {
          // Force the room selection to match the slot clicked, even if service defaults elsewhere
          const serviceWithCorrectRoom = { ...selectedInternalService, targetRoom: bookingSlot.room };

          onInternalBook(bookingSlot.date, bookingSlot.time, serviceWithCorrectRoom, internalClientName);
          setShowBookingModal(false);
      }
  };


  // .ICS Export Logic
  const downloadCalendar = () => {
    if (myBookings.length === 0) {
        alert("Nemáte žádné rezervace k exportu.");
        return;
    }
    let icsContent = "BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//Centrum Unity//Wellness App//CZ\nCALSCALE:GREGORIAN\nMETHOD:PUBLISH\n";
    myBookings.forEach(booking => {
        if (booking.status !== 'confirmed') return;
        const [year, month, day] = booking.date.split('-').map(Number);
        const [hour, minute] = booking.time.split(':').map(Number);
        const startDate = new Date(year, month - 1, day, hour, minute);
        const endDate = new Date(startDate.getTime() + booking.durationMinutes * 60000);
        const formatICSDate = (date: Date) => date.toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';
        icsContent += "BEGIN:VEVENT\n";
        icsContent += `UID:${booking.id}@centrumunity.cz\n`;
        icsContent += `DTSTAMP:${formatICSDate(new Date())}\n`;
        icsContent += `DTSTART:${formatICSDate(startDate)}\n`;
        icsContent += `DTEND:${formatICSDate(endDate)}\n`;
        icsContent += `SUMMARY:${booking.serviceName}\n`;
        icsContent += "END:VEVENT\n";
    });
    icsContent += "END:VCALENDAR";
    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const link = document.createElement('a');
    link.href = window.URL.createObjectURL(blob);
    link.setAttribute('download', 'rezervace.ics');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleServiceChange = (index: number, field: keyof Service, value: any) => {
    if (!tempPractitioner) return;
    const newServices = [...tempPractitioner.services];
    newServices[index] = { ...newServices[index], [field]: value };
    if (field === 'type') {
        if (value === '1-1') newServices[index].targetRoom = 1;
        if (value === 'group') newServices[index].targetRoom = 2;
        if (value === 'rental') newServices[index].targetRoom = 1;
    }
    setTempPractitioner(prev => (prev ? { ...prev, services: newServices } : null));
    setHasUnsavedChanges(true);
  };
  const addService = () => {
    const newService: Service = { id: Date.now().toString(), name: 'Nová Služba', durationMinutes: 60, price: 1000, type: '1-1', targetRoom: 1 };
    setTempPractitioner(prev => (prev ? { ...prev, services: [...prev.services, newService] } : null));
    setHasUnsavedChanges(true);
  };
  const removeService = (index: number) => {
    if (window.confirm('Opravdu chcete smazat tuto službu?') && tempPractitioner) {
        const newServices = tempPractitioner.services.filter((_, i) => i !== index);
        setTempPractitioner(prev => (prev ? { ...prev, services: newServices } : null));
        setHasUnsavedChanges(true);
    }
  };
  const handleProfileChange = (field: keyof Practitioner, value: any) => {
    setTempPractitioner(prev => (prev ? { ...prev, [field]: value } : null));
    setHasUnsavedChanges(true);
  };

  return (
    <div className="animate-in fade-in duration-500 pb-12 space-y-8 relative">

      {/* Top Bar */}
      <div className="bg-white p-4 rounded-xl border border-stone-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4 sticky top-20 z-30">
        <div className="flex items-center gap-3">
          <div className="bg-sage-100 p-2 rounded-full">
            <User className="w-6 h-6 text-sage-700" />
          </div>
          <div>
             <span className="text-xs font-bold text-stone-400 uppercase tracking-wider">Lektorská zóna</span>
             <h2 className="font-heading font-bold text-lg text-stone-900">{tempPractitioner.name}</h2>
          </div>
        </div>

        <div className="flex items-center gap-4">
            <Button 
                onClick={handleSave} 
                disabled={!hasUnsavedChanges}
                size="sm"
                className={`flex items-center gap-2 ${hasUnsavedChanges ? 'animate-pulse ring-2 ring-sage-400 ring-offset-2' : ''}`}
            >
                <Save className="w-4 h-4" /> Uložit {hasUnsavedChanges ? 'změny' : ''}
            </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 border-b border-stone-200">
          <button
            onClick={() => setActiveTab('calendar')}
            className={`px-6 py-3 font-medium text-sm transition-colors relative ${
                activeTab === 'calendar' 
                ? 'text-sage-800 border-b-2 border-sage-600' 
                : 'text-stone-500 hover:text-stone-800'
            }`}
          >
              <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4" /> Kalendář Místností
              </div>
          </button>
          <button
            onClick={() => setActiveTab('profile')}
            className={`px-6 py-3 font-medium text-sm transition-colors relative ${
                activeTab === 'profile' 
                ? 'text-sage-800 border-b-2 border-sage-600' 
                : 'text-stone-500 hover:text-stone-800'
            }`}
          >
              <div className="flex items-center gap-2">
                  <Edit2 className="w-4 h-4" /> Profil a Služby
              </div>
          </button>
      </div>

      {/* === CALENDAR TAB === */}
      {activeTab === 'calendar' && (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 animate-in slide-in-from-bottom-2 fade-in">
            {/* Availability Editor / Room Schedule */}
            <div className="lg:col-span-3 space-y-6">

                {/* Week Navigation */}
                <div className="flex items-center justify-between bg-white p-3 rounded-xl border border-stone-200 shadow-sm">
                    <button onClick={() => changeWeek(-1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600">
                        <ChevronLeft className="w-5 h-5" />
                    </button>
                    <div className="font-bold text-lg text-stone-900 flex items-center gap-2">
                        <Calendar className="w-5 h-5 text-sage-600" />
                        {weekDays[0].getDate()}. {weekDays[0].getMonth() + 1}. – {weekDays[4].getDate()}. {weekDays[4].getMonth() + 1}. {weekDays[0].getFullYear()}
                    </div>
                    <button onClick={() => changeWeek(1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600">
                        <ChevronRight className="w-5 h-5" />
                    </button>
                </div>

                <div className="bg-white rounded-xl border border-stone-200 shadow-sm overflow-hidden">
                    {/* Legend */}
                    <div className="p-4 bg-stone-50 border-b border-stone-200 text-xs text-stone-600 flex flex-wrap gap-4 items-center">
                        <span className="font-bold uppercase text-stone-400 mr-2">Legenda:</span>
                        <div className="flex items-center gap-1.5"><div className="w-3 h-3 bg-red-100 border border-red-300 rounded-sm"></div><span className="text-red-700 font-medium">Obsazeno (Kolegou)</span></div>
                        <div className="flex items-center gap-1.5"><div className="w-3 h-3 bg-green-500 rounded-sm"></div><span className="text-stone-900 font-bold">Moje Rezervace</span></div>
                        <div className="flex items-center gap-1.5"><div className="w-3 h-3 bg-white border border-stone-300 rounded-sm"></div><span className="text-stone-400 font-medium">Volno (Klikni pro rezervaci)</span></div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="text-xs text-stone-500 uppercase bg-stone-50 border-b border-stone-100">
                                <tr>
                                    <th className="px-4 py-4 font-medium text-center bg-stone-100/50 w-20">Čas</th>
                                    {weekDays.map(d => (
                                        <th key={d.toString()} className="px-4 py-4 font-bold text-center border-l border-stone-100 min-w-[140px]">
                                            <div className="text-stone-900">{DAYS_MAP[d.getDay()]}</div>
                                            <div className="text-stone-400 font-normal">{d.getDate()}.{d.getMonth()+1}.</div>
                                        </th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody>
                                {TIMES.map(time => (
                                    <tr key={time} className="border-b border-stone-50 hover:bg-stone-50/30">
                                        <td className="px-4 py-2 font-bold text-stone-500 text-center bg-stone-50/50 border-r border-stone-100">
                                            {time}
                                        </td>
                                        {weekDays.map((date, dayIdx) => {
                                            const dayName = ['Po', 'Út', 'St', 'Čt', 'Pá'][dayIdx];
                                            const isTemplateSet = isTemplateAvailable(dayIdx, time);
                                            const status = getRoomStatus(date, time);

                                            // Render helper for a room slot
                                            const renderRoomSlot = (label: string, roomNum: 1 | 2, booking: Booking | undefined) => {
                                                const isMine = booking?.practitionerId === currentUser.id;
                                                const isFree = !booking;

                                                return (
                                                    <div className={`flex-1 rounded-md flex flex-col items-center justify-center text-[10px] p-1 text-center transition-colors border relative group h-full ${
                                                        booking 
                                                            ? (isMine ? 'bg-green-100 border-green-300 text-green-800' : 'bg-red-50 border-red-200 text-red-800')
                                                            : 'bg-white border-stone-200 text-stone-400 hover:border-sage-400 hover:shadow-sm cursor-pointer'
                                                    }`}
                                                    onClick={() => {
                                                        if (isFree) {
                                                           openInternalBooking(formatDate(date), time, roomNum);
                                                        }
                                                    }}
                                                    >
                                                        <span className="font-bold mb-0.5 opacity-70">{label}</span>
                                                        {booking ? (
                                                            <span className="leading-tight truncate w-full font-medium" title={booking.practitionerName}>
                                                                {isMine ? 'JA' : booking.practitionerName}
                                                            </span>
                                                        ) : (
                                                            <Plus className="w-4 h-4 text-sage-300 group-hover:text-sage-600 transition-colors" />
                                                        )}
                                                    </div>
                                                );
                                            };

                                            return (
                                                <td key={`${date}-${time}`} className="p-1 border-l border-stone-100 relative min-h-[120px] align-top">
                                                    <div className="flex flex-col h-28 gap-1.5">
                                                        {/* Rooms Container */}
                                                        <div className="flex gap-1.5 flex-1">
                                                            {renderRoomSlot("MALÁ", 1, status.r1)}
                                                            {renderRoomSlot("VELKÁ", 2, status.r2)}
                                                        </div>

                                                        {/* Availability Toggle */}
                                                        <div className="flex justify-center">
                                                            <button
                                                                onClick={() => toggleSlot(dayName, time)}
                                                                className={`w-full py-0.5 rounded text-[9px] font-bold border transition-all ${
                                                                    isTemplateSet 
                                                                    ? 'bg-sage-600 text-white border-sage-700 opacity-90' 
                                                                    : 'bg-stone-50 text-stone-300 border-stone-100 hover:bg-stone-100'
                                                                }`}
                                                            >
                                                                {isTemplateSet ? 'NABÍZÍM' : 'NENABÍZÍM'}
                                                            </button>
                                                        </div>
                                                    </div>
                                                </td>
                                            );
                                        })}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {/* Sidebar with My Bookings */}
            <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h2 className="text-lg font-bold font-heading text-stone-900">Moje rezervace</h2>
                    <button 
                        onClick={downloadCalendar}
                        className="text-sage-700 hover:text-sage-900 hover:bg-sage-50 p-2 rounded-lg transition-colors flex items-center gap-2 text-xs font-bold"
                    >
                        <Download className="w-4 h-4" /> Export
                    </button>
                </div>

                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-4 max-h-[600px] overflow-y-auto">
                    <div className="space-y-4">
                        {myBookings.length === 0 ? (
                            <p className="text-stone-500 text-center py-8">Zatím nemáte žádné rezervace.</p>
                        ) : (
                            myBookings.map(booking => (
                                <div key={booking.id} className="flex flex-col gap-3 p-4 rounded-lg bg-stone-50 border border-stone-100 relative group">
                                    <button 
                                        onClick={() => onCancelBooking(booking.id)}
                                        className="absolute top-2 right-2 p-1.5 text-stone-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                        title="Zrušit rezervaci"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>

                                    <div className="flex items-start gap-3">
                                        <div className="bg-white p-2 rounded-full border border-stone-200 text-sage-600">
                                            <Calendar className="w-4 h-4" />
                                        </div>
                                        <div className="flex-1 pr-6">
                                            <div className="flex justify-between items-start">
                                                <h4 className="font-bold text-stone-900 text-sm">#{booking.id.slice(-4)}</h4>
                                            </div>
                                            <div className="mt-1 text-xs text-stone-600 space-y-1">
                                                <div className="font-medium text-sage-700">{booking.serviceName}</div>
                                                <div className="flex items-center gap-2">
                                                    <Clock className="w-3 h-3" />
                                                    {new Date(booking.date).toLocaleDateString('cs-CZ')} v {booking.time}
                                                </div>
                                                <div className="flex items-center gap-2 font-bold text-stone-500">
                                                    <BoxSelect className="w-3 h-3" />
                                                    {booking.room === 1 ? 'Malá (R1)' : 'Velká (R2)'}
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    <div className={`flex items-center gap-2 text-[10px] font-bold px-2 py-1.5 rounded border w-fit ${
                                        booking.paymentStatus === 'paid' 
                                        ? 'bg-green-50 text-green-700 border-green-200' 
                                        : 'bg-yellow-50 text-yellow-700 border-yellow-200'
                                    }`}>
                                        {booking.paymentStatus === 'paid' ? <CreditCard className="w-3 h-3" /> : <Wallet className="w-3 h-3" />}
                                        {booking.paymentStatus === 'paid' ? 'Zaplaceno' : `${booking.price} Kč`}
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>
          </div>
      )}

      {/* === PROFILE TAB === */}
      {activeTab === 'profile' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-2 fade-in">
              {/* Profile Details */}
              <div className="space-y-6">
                  <h3 className="text-lg font-bold font-heading text-stone-900 flex items-center gap-2">
                      <User className="w-5 h-5" /> Osobní údaje
                  </h3>
                  <div className="bg-white p-6 rounded-xl border border-stone-200 shadow-sm space-y-4">
                      <div>
                          <label className="block text-sm font-medium text-stone-700 mb-1">Jméno</label>
                          <input type="text" value={tempPractitioner.name} onChange={(e) => handleProfileChange('name', e.target.value)} className="w-full p-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none" />
                      </div>
                      <div>
                          <label className="block text-sm font-medium text-stone-700 mb-1">Titul / Role</label>
                          <input type="text" value={tempPractitioner.title} onChange={(e) => handleProfileChange('title', e.target.value)} className="w-full p-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none" />
                      </div>
                      <div>
                          <label className="block text-sm font-medium text-stone-700 mb-1">Kategorie</label>
                          <select value={tempPractitioner.category} onChange={(e) => handleProfileChange('category', e.target.value)} className="w-full p-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-sage-500 outline-none bg-white">
                                <option>Terapie 1-1</option>
                                <option>Semináře</option>
                                <option>Pronájem prostor</option>
                          </select>
                      </div>
                      <div>
                          <label className="block text-sm font-medium text-stone-700 mb-1">Popis</label>
