    if (date) setInitialBookingDate(date); else setInitialBookingDate('');
    if (time) setInitialBookingTime(time); else setInitialBookingTime('');
    setSelectedPractitioner(upToDatePractitioner);
  };

  // NEW: Specific handler for internal practitioner bookings (bypassing payment)
  const handleInternalBooking = async (date: string, time: string, service: Service, clientName?: string, paymentMethod: 'invoice' | 'qr' | 'apple_pay' = 'apple_pay') => {
      if (!currentUser) return;

      const newBooking: Booking = {
          id: Date.now().toString(),
          practitionerId: currentUser.id,
          practitionerName: currentUser.name,
          serviceName: service.name + (clientName ? ` (${clientName})` : ''),
          date: date,
          time: time,
          durationMinutes: service.durationMinutes,
          status: 'confirmed',
          price: service.price,
          paymentMethod: paymentMethod === 'apple_pay' ? 'apple_pay' : 'invoice', // Map inputs to allowed types in Booking if needed, but 'apple_pay' is valid
          paymentStatus: paymentMethod === 'apple_pay' ? 'paid' : (paymentMethod === 'qr' ? 'pay_at_venue' : 'invoice_pending'),
          room: service.targetRoom || 1
      };

      await saveBookingToFirestore(newBooking);
      setBookings(prev => [...prev, newBooking]);

      if (paymentMethod === 'apple_pay') {
         alert("Platba Apple Pay proběhla úspěšně. Rezervace byla potvrzena.");
