class ErrorBoundary extends React.Component<{ children: React.ReactNode }, { hasError: boolean, error: Error | null }> {
  constructor(props: { children: React.ReactNode }) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '40px', fontFamily: 'sans-serif', textAlign: 'center', backgroundColor: '#fdf9f2', minHeight: '100vh', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
          <h1 style={{ color: '#7a573d', marginBottom: '20px' }}>Něco se pokazilo 😔</h1>
          <p style={{ color: '#5a5550', maxWidth: '600px', marginBottom: '20px' }}>
            Aplikace narazila na neočekávanou chybu. Zkuste stránku obnovit.
          </p>
          <div style={{ padding: '20px', backgroundColor: '#fff', border: '1px solid #e0a86d', borderRadius: '8px', color: '#d32f2f', fontFamily: 'monospace', textAlign: 'left', maxWidth: '800px', overflow: 'auto' }}>
            {this.state.error?.toString()}
          </div>
          <button 
            onClick={() => window.location.reload()} 
            style={{ marginTop: '30px', padding: '10px 20px', backgroundColor: '#d4a574', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '16px' }}
          >
            Obnovit stránku
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

