// Absolutně bezpečné získání API klíče, které neshodí aplikaci
const getApiKey = () => {
  try {
    // @ts-ignore - process může být definován v index.html
    if (typeof process !== 'undefined' && process.env) {
      return process.env.API_KEY || '';
    }
    // @ts-ignore - window.process definován v index.html
    if (typeof window !== 'undefined' && window.process && window.process.env) {
      return window.process.env.API_KEY || '';
    }
    return '';
  } catch (e) {
    return '';
  }
};

const API_KEY = getApiKey();

