// Jednoduchá komponenta pro zachycení chyb (Error Boundary)
class ErrorBoundary extends React.Component<{ children: React.ReactNode }, { hasError: boolean, error: Error | null }> {
  constructor(props: { children: React.ReactNode }) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("Critical Application Error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '40px', fontFamily: 'sans-serif', textAlign: 'center', backgroundColor: '#fff0f0' }}>
          <h1 style={{ color: '#d32f2f' }}>Něco se pokazilo</h1>
          <p>Aplikace nemohla být načtena. Zde je technický detail chyby:</p>
          <pre style={{ 
            textAlign: 'left', 
            background: '#333', 
            color: '#fff', 
            padding: '20px', 
            borderRadius: '8px', 
            overflow: 'auto',
            marginTop: '20px' 
          }}>
            {this.state.error?.message}
            <br />
            {this.state.error?.stack}
          </pre>
          <button 
            onClick={() => window.location.reload()}
            style={{ marginTop: '20px', padding: '10px 20px', cursor: 'pointer' }}
          >
            Zkusit načíst znovu
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

