span></div>{paymentMethod === 'card' && <CheckCircle className="w-5 h-5 text-sage-600" />}</label><label className={`flex items-center p-4 border-2 rounded-xl cursor-pointer transition-all ${paymentMethod === 'cash' ? 'border-sage-500 bg-sage-50' : 'border-stone-200 hover:border-stone-300'}`}><input type="radio" name="payment" className="hidden" checked={paymentMethod === 'cash'} onChange={() => setPaymentMethod('cash')} /><div className={`p-2 rounded-full mr-4 ${paymentMethod === 'cash' ? 'bg-sage-500 text-white' : 'bg-stone-100 text-stone-400'}`}><Wallet className="w-5 h-5" /></div><div className="flex-1"><span className="font-bold block text-stone-900">Hotově na místě</span></div>{paymentMethod === 'cash' && <CheckCircle className="w-5 h-5 text-sage-600" />}</label></div></div>
                            <div className="mt-auto pt-4 flex gap-3"><Button variant="ghost" onClick={() => setStep(1)} disabled={isProcessing}>Zpět</Button><Button onClick={handlePayAndBook} className={`flex-1 relative ${paymentMethod === 'apple_pay' ? 'bg-black hover:bg-gray-800' : ''}`} disabled={isProcessing}>{isProcessing ? <><Loader2 className="w-4 h-4 animate-spin mr-2" /> Zpracovávám...</> : <>{paymentMethod === 'apple_pay' && <Apple className="w-4 h-4 mr-2" />}{paymentMethod === 'card' && <CreditCard className="w-4 h-4 mr-2" />}{paymentMethod === 'cash' && <Wallet className="w-4 h-4 mr-2" />} Zaplatit {selectedService.price} Kč</>}</Button></div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

const AppContent = () => {
