  // Randomly make slots available (using the new granular times)
  days.forEach(day => {
    GENERATED_TIMES.forEach(time => {
      // Slightly higher chance for full hours to simulate typical patterns
      const chance = time.endsWith(':00') ? 0.3 : 0.1; 
      if (Math.random() > (1 - chance)) { 
        slots.push(`${day}-${time}`);
      }
    });
  });
  return slots;
};

