          </div>
      )}

      {/* === PROFILE TAB === */}
      {activeTab === 'profile' && (
          <div className="bg-white rounded-xl shadow-sm border border-stone-200 overflow-hidden animate-in slide-in-from-bottom-2 fade-in">
              <div className="p-6 md:p-8 space-y-8">
                  {/* Personal Info */}
                  <div className="space-y-4">
                      <h3 className="text-lg font-bold text-stone-900 border-b border-stone-100 pb-2">Osobní údaje</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div>
                              <label className="block text-sm font-medium text-stone-700 mb-1">Jméno</label>
                              <input 
                                type="text" 
                                value={tempPractitioner.name} 
                                onChange={(e) => handleProfileChange('name', e.target.value)}
                                className="w-full p-2 border border-stone-300 rounded-lg"
                              />
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-stone-700 mb-1">Titul / Profese</label>
                              <input 
                                type="text" 
                                value={tempPractitioner.title} 
                                onChange={(e) => handleProfileChange('title', e.target.value)}
                                className="w-full p-2 border border-stone-300 rounded-lg"
                              />
                          </div>
                          <div className="md:col-span-2">
                              <label className="block text-sm font-medium text-stone-700 mb-1">Popis (Bio)</label>
                              <textarea 
                                value={tempPractitioner.description} 
