// --- Type Definitions for Apple Pay JS ---
declare global {
  interface Window {
    ApplePaySession: any;
  }
}

// --- Helpers ---
const timeToMinutes = (time: string): number => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

// --- Router Helper for Cloud Environments ---
const getBasename = () => {
  // Detekce prostředí pro náhledy (Cloud Run / IDX / CodeSandbox), kde aplikace běží v podadresáři
  // URL v chybě končí na .goog, což indikuje Google Cloud prostředí
  if (window.location.hostname.includes('usercontent.goog') || window.location.hostname.includes('webcontainer.io')) {
     const path = window.location.pathname;
     // Pokud cesta není root, použijeme ji jako base (odstraníme koncové lomítko)
     if (path.length > 1) {
         return path.endsWith('/') ? path.slice(0, -1) : path;
     }
  }
  return '/';
};

// --- Analytics & UX Helpers ---
const PageTracker = () => {
  const location = useLocation();
  useEffect(() => {
    Monitoring.trackPageView(location.pathname);
    window.scrollTo(0, 0); // Scroll to top on route change
  }, [location]);
  return null;
};

