const AppContent = () => {
  const [practitioners, setPractitioners] = useState<Practitioner[]>(PRACTITIONERS);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedPractitioner, setSelectedPractitioner] = useState<Practitioner | null>(null);
  const [currentUser, setCurrentUser] = useState<Practitioner | null>(null);
  const [initialBookingDate, setInitialBookingDate] = useState<string>('');
  const [initialBookingTime, setInitialBookingTime] = useState<string>('');
  const navigate = useNavigate();

  const handleBook = (practitioner: Practitioner, date?: string, time?: string) => {
    if (!currentUser) { navigate('/login'); return; }
    const upToDatePractitioner = practitioners.find(p => p.id === practitioner.id) || practitioner;
    if (date) setInitialBookingDate(date); else setInitialBookingDate('');
    if (time) setInitialBookingTime(time); else setInitialBookingTime('');
    setSelectedPractitioner(upToDatePractitioner);
  };

  // NEW: Specific handler for internal practitioner bookings (bypassing payment)
  const handleInternalBooking = async (
      date: string, 
      time: string, 
      service: Service, 
      clientName?: string, 
      paymentMethod: 'invoice' | 'qr' | 'apple_pay' = 'apple_pay',
      equipment: 'futon' | 'table' = 'table' // New parameter
  ) => {
      if (!currentUser) return;

      const newBooking: Booking = {
          id: Date.now().toString(),
          practitionerId: currentUser.id,
          practitionerName: currentUser.name,
          serviceName: service.name + (clientName ? ` (${clientName})` : ''),
          date: date,
          time: time,
          durationMinutes: service.durationMinutes,
          status: 'confirmed',
          price: service.price,
          paymentMethod: paymentMethod === 'apple_pay' ? 'apple_pay' : 'invoice', 
          paymentStatus: paymentMethod === 'apple_pay' ? 'paid' : (paymentMethod === 'qr' ? 'pay_at_venue' : 'invoice_pending'),
          room: service.targetRoom || 1,
          equipment: equipment // Save equipment
      };

      await saveBookingToFirestore(newBooking);
      setBookings(prev => [...prev, newBooking]);

      // TRIGGER NOTIFICATIONS
      NotificationService.sendBookingConfirmation(newBooking, service, 'lektor@centrumunity.cz');
      NotificationService.notifyPractitioner(newBooking, currentUser);

      Monitoring.trackEvent({ 
          name: 'purchase', 
          params: { 
              price: service.price, 
              service: 'Internal Booking', 
              method: paymentMethod 
          } 
      });

      if (paymentMethod === 'apple_pay') {
         alert("Platba Apple Pay proběhla úspěšně. Rezervace byla potvrzena a email odeslán.");
      } else if (paymentMethod === 'qr') {
          alert("Rezervace vytvořena. QR kód a potvrzení byly odeslány na email.");
      } else {
          alert("Rezervace vytvořena. Potvrzení odesláno na email.");
      }
  };

  const confirmBooking = async (date: string, time: string, paymentMethod: 'card' | 'cash' | 'apple_pay', service: Service) => {
    if (selectedPractitioner) {
        const newBooking: Booking = {
            id: Date.now().toString(),
            practitionerId: selectedPractitioner.id,
            practitionerName: selectedPractitioner.name,
            serviceName: service.name,
            date: date,
            time: time,
            durationMinutes: service.durationMinutes,
            status: 'confirmed',
            price: service.price,
            paymentMethod: paymentMethod,
            paymentStatus: paymentMethod === 'cash' ? 'pay_at_venue' : 'paid',
            room: service.targetRoom || 1
        };
        await saveBookingToFirestore(newBooking);
        setBookings(prev => [...prev, newBooking]);

        // TRIGGER NOTIFICATIONS
        NotificationService.sendBookingConfirmation(newBooking, service);
        NotificationService.notifyPractitioner(newBooking, selectedPractitioner);

        setSelectedPractitioner(null);
        alert(paymentMethod === 'cash' ? "Rezervace potvrzena. Potvrzení odesláno na email." : "Platba úspěšná! Potvrzení odesláno na email.");
    }
  };

  const handleCancelBooking = (bookingId: string) => {
      // Find the booking first to get details for notification
      const booking = bookings.find(b => b.id === bookingId);

      if (window.confirm("Opravdu chcete zrušit tuto rezervaci?")) {
          setBookings(prev => prev.filter(b => b.id !== bookingId));

          if (booking) {
             NotificationService.sendCancellationNotice(booking, 'Zrušeno uživatelem / lektorem');
          } else {
             alert("Rezervace byla zrušena.");
          }
      }
  };

  const handleUpdatePractitioner = (updated: Practitioner) => {
    setPractitioners(prev => prev.map(p => p.id === updated.id ? updated : p));
  };
  const handleLogin = (user: Practitioner) => { 
      setCurrentUser(user); 
      Monitoring.trackEvent({ name: 'login', params: { method: 'demo_select' } });
  };
  const handleLogout = () => { setCurrentUser(null); navigate('/'); };

  return (
      <div className="min-h-screen bg-stone-50 font-sans text-stone-800 flex flex-col">
        <Navbar currentUser={currentUser} onLogout={handleLogout} />
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 flex-grow w-full">
          <Routes>
            <Route path="/" element={<Directory practitioners={practitioners} onBook={handleBook} currentUser={currentUser} />} />
            <Route path="/login" element={<Login onLogin={handleLogin} />} />
            <Route path="/calendar" element={<CalendarView practitioners={practitioners} bookings={bookings} onBook={handleBook} />} />
            <Route path="/services" element={<Services />} />
            <Route path="/about" element={<About />} />
            <Route path="/team" element={<Team onBook={handleBook} />} />
            <Route path="/dashboard" element={<Dashboard bookings={bookings} />} />
            <Route path="/practitioner" element={<PractitionerDashboard practitioners={practitioners} updatePractitioner={handleUpdatePractitioner} allBookings={bookings} currentUser={currentUser} onCancelBooking={handleCancelBooking} onInternalBook={handleInternalBooking} />} />
            {/* Catch-all route to handle 404s and subdirectory mismatches caused by preview environments */}
            <Route path="*" element={<Directory practitioners={practitioners} onBook={handleBook} currentUser={currentUser} />} />
          </Routes>
        </main>
        <footer className="bg-white border-t border-stone-200 mt-12 py-12">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-8">
                    <div className="flex flex-col items-center md:items-start text-center md:text-left"><div className="flex items-center gap-3 mb-4"><img src="logo.png" alt="Centrum Unity Logo" className="h-12 w-12 rounded-full object-cover" /><div><h3 className="font-bold text-lg text-stone-900 leading-tight font-heading">Centrum Unity</h3><p className="text-xs text-sage-600 font-medium">Prostor péče a duchovního rozvoje</p></div></div></div>
                    <div className="md:col-span-2 flex flex-col items-center md:items-end justify-center text-center md:text-right">
                        <div className="space-y-3">
                            <div className="flex items-center gap-3 justify-center md:justify-end group"><Phone className="w-5 h-5 text-sage-600 group-hover:text-sage-700" /><a href="tel:+420704003433" className="text-stone-600 hover:text-sage-700 font-medium transition-colors">+420 704 003 433</a></div>
                            <div className="flex items-center gap-3 justify-center md:justify-end group"><Mail className="w-5 h-5 text-sage-600 group-hover:text-sage-700" /><a href="mailto:info@centrumunity.cz" className="text-stone-600 hover:text-sage-700 font-medium transition-colors">info@centrumunity.cz</a></div>
                            <div className="flex items-center gap-3 justify-center md:justify-end group"><MapPin className="w-5 h-5 text-sage-600 group-hover:text-sage-700" /><span className="text-stone-600 font-medium">Šmilovského 10, Praha 2, 12000</span></div>
                        </div>
                    </div>
                </div>
                <div className="border-t border-stone-100 pt-8 flex flex-col md:flex-row justify-between items-center gap-4 text-sm text-stone-400"><p>&copy; 2026 Centrum Unity. Všechna práva vyhrazena.</p></div>
            </div>
        </footer>
        {selectedPractitioner && (<BookingModal practitioner={selectedPractitioner} onClose={() => setSelectedPractitioner(null)} onConfirm={confirmBooking} allBookings={bookings} initialDate={initialBookingDate} initialTime={initialBookingTime} />)}
        <AIChatBot />
      </div>
  );
};

const App = () => { 
    // Cloud preview prostředí (jako Google Cloud Shell nebo IDX) servírují aplikaci ze subadresáře.
    // React Router DOM (v6) může mít problém s detekcí správného basename v těchto dynamických prostředích.
    // Nejrobustnější řešení pro vývoj je použít HashRouter, který ignoruje serverovou cestu.
    const isPreview = window.location.hostname.includes('usercontent.goog') || 
                      window.location.hostname.includes('webcontainer.io') ||
                      window.location.hostname.includes('idx.google.com');

    if (isPreview) {
        return (
            <HashRouter>
                <PageTracker />
                <AppContent />
            </HashRouter>
        );
    }

    return (
        <BrowserRouter>
            <PageTracker />
            <AppContent />
        </BrowserRouter>
    ); 
};
