// --- API SERVICES ---

/**
 * Creates a Stripe Payment Intent via Firebase Cloud Functions.
 * This is the secure way to handle payments without exposing secrets.
 */
export const createStripePaymentIntent = async (amount: number, currency: string = 'czk'): Promise<{ clientSecret: string }> => {
  if (!isFirebaseReady) {
    console.log("Mocking Cloud Function: createStripePaymentIntent");
    return new Promise<{ clientSecret: string }>((resolve) => setTimeout(() => resolve({ clientSecret: 'mock_secret_123' }), 1000));
  }

  const createPayment = httpsCallable(functions, 'createPaymentIntent');
  try {
    const result = await createPayment({ amount, currency });
    return result.data as { clientSecret: string };
  } catch (error) {
    console.error("Error creating payment intent:", error);
    throw error;
  }
};

/**
 * Sends a transactional email securely via Firebase Cloud Functions -> SendGrid.
 */
export const sendTransactionalEmail = async (payload: { to: string, subject: string, text: string, html?: string }) => {
    if (!isFirebaseReady) {
        console.log("☁️ [MOCK CLOUD FUNCTION]: 'sendEmail' called", payload);
        // Return a mock success response immediately in demo mode
        return { success: true, message: 'Email queued (Demo Mode)' };
    }

    // This calls the backend function 'sendEmail' deployed on Firebase
    const sendEmail = httpsCallable(functions, 'sendEmail');
    try {
        const result = await sendEmail(payload);
        return result.data;
    } catch (error) {
        console.error("Failed to send transactional email:", error);
        // Fallback or re-throw depending on criticality
        throw error;
    }
};

/**
 * Saves a booking to Firestore.
 */
export const saveBookingToFirestore = async (booking: Booking) => {
    if (!isFirebaseReady) {
        console.log("Mocking Firestore Write:", booking);
        return true;
    }

    try {
        await addDoc(collection(db, 'bookings'), booking);
        return true;
    } catch (error) {
        console.error("Error saving booking:", error);
        return false;
    }
};

/**
 * Loads bookings from Firestore for a specific date range or practitioner.
 */
export const loadBookings = async () => {
    if (!isFirebaseReady) return [];

    try {
        const q = query(collection(db, 'bookings'));
        const querySnapshot = await getDocs(q);
        return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Booking));
    } catch (error) {
        console.error("Error loading bookings:", error);
        return [];
    }
};

