// --- SEED DATA GENERATOR ---
// Generuje falešná data pro dashboard, aby po spuštění nebyl prázdný
export const generateMockBookings = (): Booking[] => {
    const bookings: Booking[] = [];
    const activePractitioners = PRACTITIONERS.filter(p => p.id !== 'rental');

    // Projdeme lektory a vygenerujeme jim historii za tento měsíc
    activePractitioners.forEach(p => {
        // Každý má 3-8 náhodných rezervací
        const count = Math.floor(Math.random() * 6) + 3; 

        for (let i = 0; i < count; i++) {
            const service = p.services[0];
            const date = new Date();
            // Náhodný den v aktuálním měsíci (minulost i budoucnost)
            const randomDay = Math.floor(Math.random() * 25) + 1; 
            date.setDate(randomDay);

            // Vybereme náhodný čas z GENERATED_TIMES (pouze celé hodiny pro jednoduchost)
            const time = GENERATED_TIMES[Math.floor(Math.random() * GENERATED_TIMES.length)];

            bookings.push({
                id: `seed-${p.id}-${i}`,
                practitionerId: p.id,
                practitionerName: p.name,
                serviceName: service.name,
                date: date.toISOString().split('T')[0],
                time: time,
                durationMinutes: service.durationMinutes,
                status: 'confirmed',
                price: service.price,
                paymentStatus: 'paid', // Většina zaplacena pro hezké grafy
                paymentMethod: Math.random() > 0.3 ? 'card' : 'cash',
                room: service.targetRoom || 1,
                equipment: Math.random() > 0.5 ? 'table' : 'futon'
            });
        }
    });

    return bookings;
};

