};

/**
 * Sends a transactional email securely via Resend API.
 * NOTE: In production, this call should happen on the BACKEND (Node.js) to protect the API Key.
 */
export const sendTransactionalEmail = async (payload: { to: string, subject: string, text: string, html?: string }) => {
    // @ts-ignore
    const resendKey = typeof window !== 'undefined' ? window.process?.env?.RESEND_API_KEY : '';

    if (!resendKey) {
        console.warn("⚠️ Chybí RESEND_API_KEY. Používám mock simulaci.");
        return { success: true, message: 'Email queued (Demo Mode)' };
    }

    console.log("🚀 Odesílám email přes Resend API...");

    try {
        const response = await fetch('https://api.resend.com/emails', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${resendKey}`
            },
            body: JSON.stringify({
                // Pokud nemáte ověřenou doménu, musíte použít tuto adresu:
                from: 'Centrum Unity <onboarding@resend.dev>', 
                to: [payload.to],
                subject: payload.subject,
                html: payload.html || `<p>${payload.text}</p>`
            })
        });

        if (!response.ok) {
            const errorData = await response.json();
            console.error("Resend API Error:", errorData);
            throw new Error(`Resend API Error: ${errorData.message || response.statusText}`);
        }

        const data = await response.json();
        console.log("✅ Email úspěšně odeslán přes Resend:", data);
        return { success: true, id: data.id };

    } catch (error) {
        console.error("Failed to send transactional email via API:", error);
        // Pokud selže API (např. CORS nebo neplatný klíč), vyhodíme chybu, 
        // kterou NotificationService zachytí a zobrazí Alert jako fallback.
        throw error;
    }
};

