export default App;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { PRACTITIONERS } from '../constants';
import { Practitioner, Role } from '../types';
import Button from '../components/Button';
import { User, Lock, ArrowRight, ShieldCheck } from 'lucide-react';

interface LoginProps {
  onLogin: (user: Practitioner) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const navigate = useNavigate();
  // Default to first user, unless it's the admin, then sort to show standard first? No, just pick first.
  const [selectedId, setSelectedId] = useState<string>(PRACTITIONERS[0].id);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = PRACTITIONERS.find(p => p.id === selectedId);
    if (user) {
      onLogin(user);
      if (user.role === Role.ADMIN) {
          navigate('/admin');
      } else {
          navigate('/practitioner');
      }
    }
  };

  // Find currently selected user to show specific UI hints
  const selectedUser = PRACTITIONERS.find(p => p.id === selectedId);
  const isAdmin = selectedUser?.role === Role.ADMIN;

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-4 animate-in fade-in">
      <div className={`max-w-md w-full bg-white rounded-2xl shadow-xl border overflow-hidden transition-colors duration-500 ${isAdmin ? 'border-indigo-200' : 'border-stone-200'}`}>
        <div className={`p-8 text-center transition-colors duration-500 ${isAdmin ? 'bg-indigo-900' : 'bg-sage-600'}`}>
          <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center mx-auto mb-4 backdrop-blur-sm">
            {isAdmin ? <ShieldCheck className="w-8 h-8 text-white" /> : <Lock className="w-8 h-8 text-white" />}
          </div>
          <h1 className="text-2xl font-bold text-white font-heading">{isAdmin ? 'Manažerský přístup' : 'Lektorský přístup'}</h1>
          <p className="mt-2 text-sm text-white/80">Pro vytvoření rezervace nebo správu se přihlaste.</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-stone-700 mb-2">Vyberte účet (Demo)</label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400 w-5 h-5" />
                <select
                  value={selectedId}
                  onChange={(e) => setSelectedId(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-stone-300 rounded-xl focus:ring-2 focus:ring-sage-500 focus:border-sage-500 outline-none bg-white appearance-none"
                >
                  <optgroup label="Management">
                      {PRACTITIONERS.filter(p => p.role === Role.ADMIN).map(p => (
                        <option key={p.id} value={p.id}>
                          {p.name} (Admin)
                        </option>
                      ))}
                  </optgroup>
                  <optgroup label="Lektoři">
                      {PRACTITIONERS.filter(p => p.role !== Role.ADMIN).map(p => (
                        <option key={p.id} value={p.id}>
                          {p.name} ({p.title})
                        </option>
                      ))}
                  </optgroup>
                </select>
              </div>
            </div>

            <div className={`p-4 rounded-lg border flex gap-3 ${isAdmin ? 'bg-indigo-50 border-indigo-100' : 'bg-orange-50 border-orange-100'}`}>
                <div className="flex-shrink-0 mt-0.5">
                    {isAdmin ? <ShieldCheck className="w-4 h-4 text-indigo-600" /> : <User className="w-4 h-4 text-orange-600" />}
                </div>
                <p className={`text-xs ${isAdmin ? 'text-indigo-800' : 'text-orange-800'}`}>
                    {isAdmin 
                     ? 'Přihlašujete se do administrace s plnými právy ke všem rezervacím a nastavení studia.' 
                     : 'Toto je demo verze. Heslo není vyžadováno. V ostré verzi zde bude standardní přihlašovací formulář.'}
                </p>
            </div>

            <Button 
                type="submit" 
                className={`w-full py-3 text-lg group ${isAdmin ? 'bg-indigo-600 hover:bg-indigo-700' : ''}`}
            >
              Přihlásit se <ArrowRight className="w-5 h-5 ml-2 group-hover:translate-x-1 transition-transform" />
            </Button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useMemo } from 'react';
import { Booking, Practitioner, Service, Role } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line, AreaChart, Area, PieChart, Pie, Cell, Legend } from 'recharts';
import { Users, Calendar, DollarSign, TrendingUp, Search, MoreHorizontal, Settings, ShieldAlert, Edit, Trash2, CheckCircle, XCircle, Clock, Filter, Eye, EyeOff, Activity, Layers, BoxSelect } from 'lucide-react';
import Button from '../components/Button';
import RescheduleModal from '../components/RescheduleModal';

interface AdminDashboardProps {
  allBookings: Booking[];
  practitioners: Practitioner[];
  updatePractitioner: (p: Practitioner) => void;
  onAdminReschedule: (bookingId: string, newDate: string, newTime: string, reason?: string) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
    allBookings, 
    practitioners, 
    updatePractitioner,
    onAdminReschedule 
}) => {
    const [activeTab, setActiveTab] = useState<'analytics' | 'schedule' | 'team'>('analytics');
    const [searchQuery, setSearchQuery] = useState('');
    const [scheduleFilter, setScheduleFilter] = useState<'all' | 'today' | 'upcoming'>('all');

    // Reschedule Modal State
    const [reschedulingBooking, setReschedulingBooking] = useState<Booking | null>(null);

    // --- ANALYTICS DATA ---
    const stats = useMemo(() => {
        const confirmedBookings = allBookings.filter(b => b.status === 'confirmed');
        const totalRevenue = confirmedBookings.reduce((sum, b) => sum + b.price, 0);
        const totalBookings = confirmedBookings.length;

        // 1. Revenue by Day (Basic)
        const revenueByDay = confirmedBookings.reduce((acc, curr) => {
            const day = new Date(curr.date).toLocaleDateString('cs-CZ', { weekday: 'short' });
            acc[day] = (acc[day] || 0) + curr.price;
            return acc;
        }, {} as Record<string, number>);
        const chartData = Object.keys(revenueByDay).map(day => ({ name: day, value: revenueByDay[day] }));

        // 2. Peak Hours Heatmap Logic
        const hoursMap: Record<string, number> = {};
        confirmedBookings.forEach(b => {
            const hour = b.time.split(':')[0]; // "09", "10"...
            hoursMap[hour] = (hoursMap[hour] || 0) + 1;
        });
        const peakHoursData = Object.keys(hoursMap).sort().map(h => ({ name: `${h}:00`, count: hoursMap[h] }));

        // 3. Equipment Utilization
        const tableCount = confirmedBookings.filter(b => b.equipment === 'table').length;
        const futonCount = confirmedBookings.filter(b => b.equipment === 'futon').length;
        // Fallback: if equipment is undefined, assume based on service type or practitioner default
        // For accurate data, we assume the data structure has 'equipment'. 
        // If 0, we add some defaults for visualization if 'equipment' field is missing in old data.
        const equipmentData = [
            { name: 'Lehátko', value: tableCount || 15, color: '#4f46e5' }, // Indigo
            { name: 'Futon', value: futonCount || 8, color: '#9ca3af' },   // Gray
        ];

        // 4. Room Utilization
        const room1Count = confirmedBookings.filter(b => b.room === 1).length;
        const room2Count = confirmedBookings.filter(b => b.room === 2).length;
        const roomData = [
            { name: 'Malá (R1)', value: room1Count, color: '#ba8a5b' }, // Gold/Sage
            { name: 'Velká (R2)', value: room2Count, color: '#7a573d' }, // Brown
        ];

        // 5. Mock Revenue Trend (Last 6 months)
        const revenueTrendData = [
            { name: 'Září', revenue: 45000 },
            { name: 'Říjen', revenue: 52000 },
            { name: 'Listopad', revenue: 48000 },
            { name: 'Prosinec', revenue: 65000 },
            { name: 'Leden', revenue: 58000 },
            { name: 'Únor', revenue: totalRevenue }, // Current
        ];

        return { 
            totalRevenue, 
            totalBookings, 
            chartData, 
            peakHoursData,
            equipmentData,
            roomData,
            revenueTrendData
        };
    }, [allBookings]);

    // --- TEAM MANAGEMENT ---
    const handleToggleActive = (practitioner: Practitioner) => {
        if (window.confirm(`Opravdu chcete ${practitioner.isActive ? 'deaktivovat' : 'aktivovat'} profil lektora ${practitioner.name}?`)) {
            updatePractitioner({
                ...practitioner,
                isActive: !practitioner.isActive
            });
        }
    };

    // --- SCHEDULE FILTERING ---
    const filteredBookings = allBookings.filter(b => {
        const matchesSearch = b.practitionerName.toLowerCase().includes(searchQuery.toLowerCase()) || 
                              b.serviceName.toLowerCase().includes(searchQuery.toLowerCase());

        if (!matchesSearch) return false;

        const bookingDate = new Date(b.date);
        const today = new Date();
        today.setHours(0,0,0,0);

        if (scheduleFilter === 'today') {
            return bookingDate.getTime() === today.getTime();
        }
        if (scheduleFilter === 'upcoming') {
            return bookingDate >= today;
        }
        return true;
    }).sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());


    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-12">

            {/* Admin Header */}
            <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                <div>
                    <div className="flex items-center gap-2 mb-2">
                        <div className="bg-indigo-700 p-1.5 rounded text-xs font-bold uppercase tracking-wider">Admin Zóna</div>
                        <span className="text-indigo-200 text-sm">v2.0 Analytics</span>
                    </div>
                    <h1 className="text-3xl font-bold font-heading">Manažerský Panel</h1>
                    <p className="text-indigo-200 mt-1">Správa studia, týmu a business intelligence.</p>
                </div>
                <div className="flex gap-4">
                    <div className="text-right hidden md:block">
                        <div className="text-2xl font-bold">{stats.totalRevenue.toLocaleString()} Kč</div>
                        <div className="text-indigo-300 text-sm">Celkové tržby</div>
                    </div>
                    <div className="h-12 w-px bg-indigo-700 hidden md:block"></div>
                    <div className="text-right hidden md:block">
                        <div className="text-2xl font-bold">{stats.totalBookings}</div>
                        <div className="text-indigo-300 text-sm">Rezervací</div>
                    </div>
                </div>
            </div>

            {/* Navigation Tabs */}
            <div className="flex overflow-x-auto gap-2 border-b border-stone-200 pb-1">
                <button 
                    onClick={() => setActiveTab('analytics')}
                    className={`px-6 py-3 font-medium text-sm flex items-center gap-2 rounded-t-lg transition-colors ${activeTab === 'analytics' ? 'bg-white text-indigo-700 border-b-2 border-indigo-600 shadow-sm' : 'text-stone-500 hover:text-stone-800'}`}
                >
                    <TrendingUp className="w-4 h-4" /> BI & Statistiky
                </button>
                <button 
                    onClick={() => setActiveTab('schedule')}
                    className={`px-6 py-3 font-medium text-sm flex items-center gap-2 rounded-t-lg transition-colors ${activeTab === 'schedule' ? 'bg-white text-indigo-700 border-b-2 border-indigo-600 shadow-sm' : 'text-stone-500 hover:text-stone-800'}`}
                >
                    <Calendar className="w-4 h-4" /> Master Schedule
                </button>
                <button 
                    onClick={() => setActiveTab('team')}
                    className={`px-6 py-3 font-medium text-sm flex items-center gap-2 rounded-t-lg transition-colors ${activeTab === 'team' ? 'bg-white text-indigo-700 border-b-2 border-indigo-600 shadow-sm' : 'text-stone-500 hover:text-stone-800'}`}
                >
                    <Users className="w-4 h-4" /> Správa Týmu
                </button>
            </div>

            {/* === ANALYTICS TAB === */}
            {activeTab === 'analytics' && (
                <div className="space-y-6 animate-in slide-in-from-bottom-2 fade-in">

                    {/* Row 1: Revenue & Heatmap */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        <div className="bg-white p-6 rounded-xl border border-stone-200 shadow-sm">
                            <h3 className="text-lg font-bold text-stone-900 mb-6 flex items-center gap-2">
                                <TrendingUp className="w-5 h-5 text-indigo-600" /> Vývoj tržeb (6 měsíců)
                            </h3>
                            <div className="h-64">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={stats.revenueTrendData}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 12}} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 12}} />
                                        <Tooltip cursor={{fill: '#f1f5f9'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                                        <Bar dataKey="revenue" fill="#4f46e5" radius={[4, 4, 0, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        <div className="bg-white p-6 rounded-xl border border-stone-200 shadow-sm">
                            <h3 className="text-lg font-bold text-stone-900 mb-6 flex items-center gap-2">
                                <Clock className="w-5 h-5 text-indigo-600" /> Vytíženost v čase (Peak Hours)
                            </h3>
                            <div className="h-64">
                                <ResponsiveContainer width="100%" height="100%">
                                    <AreaChart data={stats.peakHoursData}>
                                        <defs>
                                            <linearGradient id="colorCount" x1="0" y1="0" x2="0" y2="1">
                                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.8}/>
                                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                                            </linearGradient>
                                        </defs>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 12}} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 12}} />
                                        <Tooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                                        <Area type="monotone" dataKey="count" stroke="#6366f1" fillOpacity={1} fill="url(#colorCount)" />
                                    </AreaChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>

                    {/* Row 2: Stats & Pie Charts */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        {/* Summary Cards */}
                        <div className="space-y-4">
                            <div className="bg-white p-5 rounded-xl border border-stone-200 shadow-sm flex items-center justify-between">
                                <div>
                                    <p className="text-xs text-stone-500 font-bold uppercase">Obsazenost (Overall)</p>
                                    <h4 className="text-2xl font-bold text-stone-900 mt-1">72%</h4>
                                </div>
                                <div className="p-3 bg-green-50 rounded-full text-green-600"><Activity className="w-5 h-5" /></div>
                            </div>
                            <div className="bg-white p-5 rounded-xl border border-stone-200 shadow-sm flex items-center justify-between">
                                <div>
                                    <p className="text-xs text-stone-500 font-bold uppercase">Nejlepší den</p>
                                    <h4 className="text-2xl font-bold text-stone-900 mt-1">Čtvrtek</h4>
                                </div>
                                <div className="p-3 bg-indigo-50 rounded-full text-indigo-600"><Calendar className="w-5 h-5" /></div>
                            </div>
                            <div className="bg-white p-5 rounded-xl border border-stone-200 shadow-sm flex items-center justify-between">
                                <div>
                                    <p className="text-xs text-stone-500 font-bold uppercase">Průměr na rezervaci</p>
                                    <h4 className="text-2xl font-bold text-stone-900 mt-1">1 250 Kč</h4>
                                </div>
                                <div className="p-3 bg-amber-50 rounded-full text-amber-600"><DollarSign className="w-5 h-5" /></div>
                            </div>
                        </div>

                        {/* Equipment Preference */}
                        <div className="bg-white p-6 rounded-xl border border-stone-200 shadow-sm flex flex-col items-center">
                            <h3 className="text-sm font-bold text-stone-500 uppercase mb-4 w-full flex items-center gap-2">
                                <Layers className="w-4 h-4" /> Preference Vybavení
                            </h3>
                            <div className="h-48 w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie data={stats.equipmentData} cx="50%" cy="50%" innerRadius={40} outerRadius={60} paddingAngle={5} dataKey="value">
                                            {stats.equipmentData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={entry.color} />
                                            ))}
                                        </Pie>
                                        <Tooltip />
                                        <Legend verticalAlign="bottom" height={36}/>
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                         {/* Room Utilization */}
                         <div className="bg-white p-6 rounded-xl border border-stone-200 shadow-sm flex flex-col items-center">
                            <h3 className="text-sm font-bold text-stone-500 uppercase mb-4 w-full flex items-center gap-2">
                                <BoxSelect className="w-4 h-4" /> Využití Místností
                            </h3>
                            <div className="h-48 w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie data={stats.roomData} cx="50%" cy="50%" innerRadius={40} outerRadius={60} paddingAngle={5} dataKey="value">
                                            {stats.roomData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={entry.color} />
                                            ))}
                                        </Pie>
                                        <Tooltip />
                                        <Legend verticalAlign="bottom" height={36}/>
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* === SCHEDULE TAB === */}
            {activeTab === 'schedule' && (
                <div className="bg-white rounded-xl shadow-sm border border-stone-200 overflow-hidden animate-in slide-in-from-bottom-2 fade-in">
                    <div className="p-4 border-b border-stone-200 flex flex-col md:flex-row gap-4 justify-between items-center bg-stone-50">
                        <div className="flex items-center gap-2">
                            <div className="relative">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-stone-400" />
                                <input 
                                    type="text" 
                                    placeholder="Hledat lektora nebo službu..." 
                                    className="pl-9 pr-4 py-2 border border-stone-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none w-64"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                />
                            </div>
                            <div className="flex bg-white rounded-lg border border-stone-300 p-1">
                                <button onClick={() => setScheduleFilter('all')} className={`px-3 py-1 rounded text-xs font-bold ${scheduleFilter === 'all' ? 'bg-indigo-100 text-indigo-700' : 'text-stone-500 hover:bg-stone-50'}`}>Vše</button>
                                <button onClick={() => setScheduleFilter('today')} className={`px-3 py-1 rounded text-xs font-bold ${scheduleFilter === 'today' ? 'bg-indigo-100 text-indigo-700' : 'text-stone-500 hover:bg-stone-50'}`}>Dnes</button>
                                <button onClick={() => setScheduleFilter('upcoming')} className={`px-3 py-1 rounded text-xs font-bold ${scheduleFilter === 'upcoming' ? 'bg-indigo-100 text-indigo-700' : 'text-stone-500 hover:bg-stone-50'}`}>Budoucí</button>
                            </div>
                        </div>
                        <div className="text-xs font-medium text-stone-500">
                            Zobrazeno {filteredBookings.length} rezervací
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-stone-100 text-stone-500 uppercase text-xs font-bold">
                                <tr>
                                    <th className="px-6 py-4">ID</th>
                                    <th className="px-6 py-4">Termín</th>
                                    <th className="px-6 py-4">Lektor & Služba</th>
                                    <th className="px-6 py-4">Místnost</th>
                                    <th className="px-6 py-4">Status</th>
                                    <th className="px-6 py-4 text-right">Akce</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-stone-100">
                                {filteredBookings.map(booking => {
                                    const isPast = new Date(booking.date) < new Date(new Date().setHours(0,0,0,0));
                                    return (
                                        <tr key={booking.id} className={`hover:bg-stone-50 transition-colors ${isPast ? 'opacity-60 bg-stone-50' : ''}`}>
                                            <td className="px-6 py-4 font-mono text-xs text-stone-400">#{booking.id.slice(-4)}</td>
                                            <td className="px-6 py-4">
                                                <div className="font-bold text-stone-900">{new Date(booking.date).toLocaleDateString('cs-CZ')}</div>
                                                <div className="text-stone-500">{booking.time} ({booking.durationMinutes} min)</div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="font-bold text-stone-900">{booking.practitionerName}</div>
                                                <div className="text-xs text-indigo-600 font-medium">{booking.serviceName}</div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className={`inline-flex items-center px-2 py-1 rounded text-xs font-bold ${booking.room === 1 ? 'bg-purple-50 text-purple-700' : 'bg-blue-50 text-blue-700'}`}>
                                                    {booking.room === 1 ? 'Malá (R1)' : 'Velká (R2)'}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4">
                                                {booking.status === 'confirmed' ? (
                                                    <span className="text-green-600 flex items-center gap-1 text-xs font-bold"><CheckCircle className="w-3 h-3" /> Potvrzeno</span>
                                                ) : (
                                                    <span className="text-stone-400">Zrušeno</span>
                                                )}
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                {!isPast && (
                                                    <Button 
                                                        size="sm" 
                                                        variant="outline" 
                                                        className="text-xs border-indigo-200 text-indigo-700 hover:bg-indigo-50"
                                                        onClick={() => setReschedulingBooking(booking)}
                                                    >
                                                        <Clock className="w-3 h-3 mr-1" /> Přeplánovat
                                                    </Button>
                                                )}
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {/* === TEAM TAB === */}
            {activeTab === 'team' && (
                <div className="bg-white rounded-xl shadow-sm border border-stone-200 overflow-hidden animate-in slide-in-from-bottom-2 fade-in">
                    <div className="p-6 border-b border-stone-200">
                        <h2 className="text-lg font-bold text-stone-900">Správa Lektorů</h2>
                        <p className="text-stone-500 text-sm">Aktivace/deaktivace profilů a správa údajů.</p>
                    </div>
                    <div className="divide-y divide-stone-100">
                        {practitioners.filter(p => p.role !== Role.ADMIN).map(p => (
                            <div key={p.id} className={`p-6 flex items-center justify-between ${!p.isActive ? 'bg-stone-50 opacity-75' : ''}`}>
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 rounded-full overflow-hidden border border-stone-200">
                                        <img src={p.imageUrl} alt={p.name} className={`w-full h-full object-cover ${!p.isActive ? 'grayscale' : ''}`} />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-stone-900 flex items-center gap-2">
                                            {p.name}
                                            {!p.isActive && <span className="text-[10px] bg-stone-200 text-stone-600 px-1.5 py-0.5 rounded uppercase tracking-wide">Neaktivní</span>}
                                        </h3>
                                        <p className="text-sm text-stone-500">{p.title}</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3">
                                    <div className="text-right text-xs text-stone-400 mr-4 hidden md:block">
                                        <div>{p.role}</div>
                                        <div>ID: {p.id}</div>
                                    </div>
                                    <Button 
                                        variant="outline" 
                                        size="sm"
                                        onClick={() => handleToggleActive(p)}
                                        className={p.isActive ? "hover:bg-red-50 hover:text-red-600 hover:border-red-200" : "hover:bg-green-50 hover:text-green-600 hover:border-green-200"}
                                    >
                                        {p.isActive ? <EyeOff className="w-4 h-4 mr-1" /> : <Eye className="w-4 h-4 mr-1" />}
                                        {p.isActive ? 'Skrýt profil' : 'Aktivovat'}
                                    </Button>
                                    <Button size="sm" variant="secondary">
                                        <Edit className="w-4 h-4 mr-1" /> Upravit
                                    </Button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Reschedule Modal */}
            {reschedulingBooking && (
                <RescheduleModal 
                    booking={reschedulingBooking} 
                    onClose={() => setReschedulingBooking(null)} 
                    onConfirm={(date, time, reason) => {
                        onAdminReschedule(reschedulingBooking.id, date, time, reason);
                        setReschedulingBooking(null);
                    }} 
                />
            )}
        </div>
    );
};

export default AdminDashboard;

import React, { useState, useMemo } from 'react';
import { Booking, Practitioner, Service, Role } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line, AreaChart, Area, PieChart, Pie, Cell, Legend } from 'recharts';
import { Users, Calendar, DollarSign, TrendingUp, Search, MoreHorizontal, Settings, ShieldAlert, Edit, Trash2, CheckCircle, XCircle, Clock, Filter, Eye, EyeOff, Activity, Layers, BoxSelect, AlertTriangle, Trophy } from 'lucide-react';
import Button from '../components/Button';
import RescheduleModal from '../components/RescheduleModal';

interface AdminDashboardProps {
  allBookings: Booking[];
  practitioners: Practitioner[];
  updatePractitioner: (p: Practitioner) => void;
  onAdminReschedule: (bookingId: string, newDate: string, newTime: string, reason?: string) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
    allBookings, 
    practitioners, 
    updatePractitioner,
    onAdminReschedule 
}) => {
    const [activeTab, setActiveTab] = useState<'analytics' | 'schedule' | 'team'>('analytics');
    const [searchQuery, setSearchQuery] = useState('');
    const [scheduleFilter, setScheduleFilter] = useState<'all' | 'today' | 'upcoming'>('all');

    // Reschedule Modal State
    const [reschedulingBooking, setReschedulingBooking] = useState<Booking | null>(null);

    // --- ANALYTICS DATA ---
    const stats = useMemo(() => {
        const confirmedBookings = allBookings.filter(b => b.status === 'confirmed');
        const cancelledBookings = allBookings.filter(b => b.status !== 'confirmed'); // Assuming anything not confirmed is cancelled/pending

        const totalRevenue = confirmedBookings.reduce((sum, b) => sum + b.price, 0);
        const totalBookings = confirmedBookings.length;

        // 1. Revenue by Day (Basic)
        const revenueByDay = confirmedBookings.reduce((acc, curr) => {
            const day = new Date(curr.date).toLocaleDateString('cs-CZ', { weekday: 'short' });
            acc[day] = (acc[day] || 0) + curr.price;
            return acc;
        }, {} as Record<string, number>);
        const chartData = Object.keys(revenueByDay).map(day => ({ name: day, value: revenueByDay[day] }));

        // 2. Peak Hours Heatmap Logic
        const hoursMap: Record<string, number> = {};
        confirmedBookings.forEach(b => {
            const hour = b.time.split(':')[0]; // "09", "10"...
            hoursMap[hour] = (hoursMap[hour] || 0) + 1;
        });
        const peakHoursData = Object.keys(hoursMap).sort().map(h => ({ name: `${h}:00`, count: hoursMap[h] }));

        // 3. Equipment Utilization
        const tableCount = confirmedBookings.filter(b => b.equipment === 'table').length;
        const futonCount = confirmedBookings.filter(b => b.equipment === 'futon').length;
        const equipmentData = [
            { name: 'Lehátko', value: tableCount || 15, color: '#4f46e5' }, // Indigo
            { name: 'Futon', value: futonCount || 8, color: '#9ca3af' },   // Gray
        ];

        // 4. Room Utilization
        const room1Count = confirmedBookings.filter(b => b.room === 1).length;
        const room2Count = confirmedBookings.filter(b => b.room === 2).length;
        const roomData = [
            { name: 'Malá (R1)', value: room1Count, color: '#ba8a5b' }, // Gold/Sage
            { name: 'Velká (R2)', value: room2Count, color: '#7a573d' }, // Brown
        ];

        // 5. Mock Revenue Trend (Last 6 months)
        const revenueTrendData = [
            { name: 'Září', revenue: 45000 },
            { name: 'Říjen', revenue: 52000 },
            { name: 'Listopad', revenue: 48000 },
            { name: 'Prosinec', revenue: 65000 },
            { name: 'Leden', revenue: 58000 },
            { name: 'Únor', revenue: totalRevenue }, // Current
        ];

        // 6. REVENUE ATTRIBUTION (Top Performers)
        const revenueByPractitioner: Record<string, number> = {};
        confirmedBookings.forEach(b => {
            // Exclude Admin/Rental from "Team Performance" usually, but let's keep Rental to see comparison
            revenueByPractitioner[b.practitionerName] = (revenueByPractitioner[b.practitionerName] || 0) + b.price;
        });
        const topPerformersData = Object.entries(revenueByPractitioner)
            .map(([name, value]) => ({ name, value }))
            .sort((a, b) => b.value - a.value); // Descending

        // 7. CANCELLATION METRICS (Lead Time Simulation)
        // Since our booking model doesn't strictly store 'cancelledAt', we will simulate the distribution
        // based on typical industry data for the demo, or use real counts if available.
        const totalCancelled = cancelledBookings.length;
        const cancellationRate = totalBookings > 0 ? ((totalCancelled / (totalBookings + totalCancelled)) * 100).toFixed(1) : "0";

        const cancellationLeadTimeData = [
            { name: '< 24h (Krizové)', value: 15, color: '#ef4444' }, // Red
            { name: '24-48h (Varovné)', value: 30, color: '#f59e0b' }, // Orange
            { name: '> 48h (Bezpečné)', value: 55, color: '#10b981' }, // Green
        ];

        return { 
            totalRevenue, 
            totalBookings, 
            chartData, 
            peakHoursData,
            equipmentData,
            roomData,
            revenueTrendData,
            topPerformersData,
            cancellationLeadTimeData,
            cancellationRate
        };
    }, [allBookings]);

    // --- TEAM MANAGEMENT ---
    const handleToggleActive = (practitioner: Practitioner) => {
        if (window.confirm(`Opravdu chcete ${practitioner.isActive ? 'deaktivovat' : 'aktivovat'} profil lektora ${practitioner.name}?`)) {
            updatePractitioner({
                ...practitioner,
                isActive: !practitioner.isActive
            });
        }
    };

    // --- SCHEDULE FILTERING ---
    const filteredBookings = allBookings.filter(b => {
        const matchesSearch = b.practitionerName.toLowerCase().includes(searchQuery.toLowerCase()) || 
                              b.serviceName.toLowerCase().includes(searchQuery.toLowerCase());

        if (!matchesSearch) return false;

        const bookingDate = new Date(b.date);
        const today = new Date();
        today.setHours(0,0,0,0);

        if (scheduleFilter === 'today') {
            return bookingDate.getTime() === today.getTime();
        }
        if (scheduleFilter === 'upcoming') {
            return bookingDate >= today;
        }
        return true;
    }).sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());


    return (
