import React, { useState, useMemo } from 'react';
import { Booking, Practitioner, Service, Role } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line, AreaChart, Area, PieChart, Pie, Cell, Legend } from 'recharts';
import { Users, Calendar, DollarSign, TrendingUp, Search, MoreHorizontal, Settings, ShieldAlert, Edit, Trash2, CheckCircle, XCircle, Clock, Filter, Eye, EyeOff, Activity, Layers, BoxSelect, AlertTriangle, Trophy } from 'lucide-react';
import Button from '../components/Button';
import RescheduleModal from '../components/RescheduleModal';

interface AdminDashboardProps {
  allBookings: Booking[];
  practitioners: Practitioner[];
  updatePractitioner: (p: Practitioner) => void;
  onAdminReschedule: (bookingId: string, newDate: string, newTime: string, reason?: string) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
    allBookings, 
    practitioners, 
    updatePractitioner,
    onAdminReschedule 
}) => {
    const [activeTab, setActiveTab] = useState<'analytics' | 'schedule' | 'team'>('analytics');
    const [searchQuery, setSearchQuery] = useState('');
    const [scheduleFilter, setScheduleFilter] = useState<'all' | 'today' | 'upcoming'>('all');

    // Reschedule Modal State
    const [reschedulingBooking, setReschedulingBooking] = useState<Booking | null>(null);

    // --- ANALYTICS DATA ---
    const stats = useMemo(() => {
        const confirmedBookings = allBookings.filter(b => b.status === 'confirmed');
        const cancelledBookings = allBookings.filter(b => b.status !== 'confirmed'); // Assuming anything not confirmed is cancelled/pending

        const totalRevenue = confirmedBookings.reduce((sum, b) => sum + b.price, 0);
        const totalBookings = confirmedBookings.length;

        // 1. Revenue by Day (Basic)
        const revenueByDay = confirmedBookings.reduce((acc, curr) => {
            const day = new Date(curr.date).toLocaleDateString('cs-CZ', { weekday: 'short' });
            acc[day] = (acc[day] || 0) + curr.price;
            return acc;
        }, {} as Record<string, number>);
        const chartData = Object.keys(revenueByDay).map(day => ({ name: day, value: revenueByDay[day] }));

        // 2. Peak Hours Heatmap Logic
        const hoursMap: Record<string, number> = {};
        confirmedBookings.forEach(b => {
            const hour = b.time.split(':')[0]; // "09", "10"...
            hoursMap[hour] = (hoursMap[hour] || 0) + 1;
        });
        const peakHoursData = Object.keys(hoursMap).sort().map(h => ({ name: `${h}:00`, count: hoursMap[h] }));

        // 3. Equipment Utilization
        const tableCount = confirmedBookings.filter(b => b.equipment === 'table').length;
        const futonCount = confirmedBookings.filter(b => b.equipment === 'futon').length;
        const equipmentData = [
            { name: 'Lehátko', value: tableCount || 15, color: '#4f46e5' }, // Indigo
            { name: 'Futon', value: futonCount || 8, color: '#9ca3af' },   // Gray
        ];

        // 4. Room Utilization
        const room1Count = confirmedBookings.filter(b => b.room === 1).length;
        const room2Count = confirmedBookings.filter(b => b.room === 2).length;
        const roomData = [
            { name: 'Malá (R1)', value: room1Count, color: '#ba8a5b' }, // Gold/Sage
            { name: 'Velká (R2)', value: room2Count, color: '#7a573d' }, // Brown
        ];

        // 5. Mock Revenue Trend (Last 6 months)
        const revenueTrendData = [
            { name: 'Září', revenue: 45000 },
            { name: 'Říjen', revenue: 52000 },
            { name: 'Listopad', revenue: 48000 },
            { name: 'Prosinec', revenue: 65000 },
            { name: 'Leden', revenue: 58000 },
            { name: 'Únor', revenue: totalRevenue }, // Current
        ];

        // 6. REVENUE ATTRIBUTION (Top Performers)
        const revenueByPractitioner: Record<string, number> = {};
        confirmedBookings.forEach(b => {
            // Exclude Admin/Rental from "Team Performance" usually, but let's keep Rental to see comparison
            revenueByPractitioner[b.practitionerName] = (revenueByPractitioner[b.practitionerName] || 0) + b.price;
        });
        const topPerformersData = Object.entries(revenueByPractitioner)
            .map(([name, value]) => ({ name, value }))
            .sort((a, b) => b.value - a.value); // Descending

        // 7. CANCELLATION METRICS (Lead Time Simulation)
        // Since our booking model doesn't strictly store 'cancelledAt', we will simulate the distribution
        // based on typical industry data for the demo, or use real counts if available.
        const totalCancelled = cancelledBookings.length;
        const cancellationRate = totalBookings > 0 ? ((totalCancelled / (totalBookings + totalCancelled)) * 100).toFixed(1) : "0";

        const cancellationLeadTimeData = [
            { name: '< 24h (Krizové)', value: 15, color: '#ef4444' }, // Red
            { name: '24-48h (Varovné)', value: 30, color: '#f59e0b' }, // Orange
            { name: '> 48h (Bezpečné)', value: 55, color: '#10b981' }, // Green
        ];

        return { 
            totalRevenue, 
            totalBookings, 
            chartData, 
            peakHoursData,
            equipmentData,
            roomData,
            revenueTrendData,
            topPerformersData,
            cancellationLeadTimeData,
