                    </div>
                </div>
            )}

            {/* Reschedule Modal */}
            {reschedulingBooking && (
                <RescheduleModal 
                    booking={reschedulingBooking} 
                    onClose={() => setReschedulingBooking(null)} 
                    onConfirm={(date, time, reason) => {
                        onAdminReschedule(reschedulingBooking.id, date, time, reason);
                        setReschedulingBooking(null);
                    }} 
                />
            )}
        </div>
    );
};

