const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];
const BookingModal = ({ practitioner, onClose, onConfirm, allBookings, initialDate, initialTime }: { practitioner: Practitioner | null, onClose: () => void, onConfirm: (date: string, time: string, paymentMethod: 'card' | 'cash' | 'apple_pay', service: Service) => void, allBookings: Booking[], initialDate?: string, initialTime?: string }) => {
    const [step, setStep] = useState<0 | 1 | 2>(0); 
    const [selectedService, setSelectedService] = useState<Service | null>(null);
    const [selectedDate, setSelectedDate] = useState<string>(initialDate || '');
    const [selectedTime, setSelectedTime] = useState<string>(initialTime || '');
    const [paymentMethod, setPaymentMethod] = useState<'card' | 'cash' | 'apple_pay'>('apple_pay');
    const [isProcessing, setIsProcessing] = useState(false);
    const [isApplePayAvailable, setIsApplePayAvailable] = useState(false);

    useEffect(() => {
        // Safe check for Apple Pay availability
        if (typeof window !== 'undefined' && window.ApplePaySession && window.ApplePaySession.canMakePayments()) {
            setIsApplePayAvailable(true);
        }
    }, []);
    useEffect(() => {
        if (initialDate && initialTime && practitioner?.services.length) {
            setSelectedService(practitioner.services[0]);
            setStep(1);
        }
    }, [initialDate, initialTime, practitioner]);

    if (!practitioner) return null;

    const dates = Array.from({length: 5}, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() + i + 1);
        return d.toISOString().split('T')[0];
    });
    if (initialDate && !dates.includes(initialDate)) { dates.unshift(initialDate); }

    const getSlotStatus = (date: string, time: string): 'available' | 'room_full' | 'practitioner_busy' => {
        if (!selectedService) return 'available';
        const d = new Date(date);
        const dayName = DAYS_MAP[d.getDay()];
        const slotKey = `${dayName}-${time}`;
        if (!practitioner.availability.includes(slotKey)) return 'practitioner_busy';

        const candidateStart = timeToMinutes(time);
        const candidateEnd = candidateStart + selectedService.durationMinutes;

        const relevantBookings = allBookings.filter(b => b.date === date && b.status === 'confirmed');

        for (const booking of relevantBookings) {
            const bookingStart = timeToMinutes(booking.time);
            const bookingEnd = bookingStart + booking.durationMinutes;
            const bookingOccupancyEnd = bookingEnd + CLEANING_BUFFER_MINUTES;

            const isOverlap = (candidateStart < bookingOccupancyEnd) && (candidateEnd > bookingStart);

            if (isOverlap) {
                if (selectedService.type === 'rental') { if (booking.room === selectedService.targetRoom) return 'room_full'; }
                else if (selectedService.type === '1-1') { if (booking.practitionerId === practitioner.id) return 'practitioner_busy'; if (booking.room === selectedService.targetRoom) return 'room_full'; }
                else if (selectedService.type === 'group') { if (booking.practitionerId === practitioner.id) return 'practitioner_busy'; if (booking.room === selectedService.targetRoom) return 'room_full'; }
            }
        }
        return 'available';
    };

    const processDirectApplePay = () => {
        if (!selectedService) return;
        const request = {
            countryCode: 'CZ',
            currencyCode: 'CZK',
            supportedNetworks: ['visa', 'masterCard', 'amex'],
            merchantCapabilities: ['supports3DS'],
            total: { label: 'Centrum Unity', amount: selectedService.price.toString() }
        };
        try {
            const session = new window.ApplePaySession(3, request);
            session.onvalidatemerchant = (event: any) => { session.abort(); };
            session.onpaymentauthorized = (event: any) => {
                session.completePayment(window.ApplePaySession.STATUS_SUCCESS);
                Monitoring.trackEvent({ name: 'purchase', params: { price: selectedService.price, service: selectedService.name } });
                onConfirm(selectedDate, selectedTime, 'apple_pay', selectedService);
            };
            session.begin();
        } catch (e) {
            Monitoring.trackEvent({ name: 'purchase', params: { price: selectedService.price, service: selectedService.name, mock: true } });
            alert("Direct Apple Pay simulation: Platba proběhla úspěšně (Mock).");
            onConfirm(selectedDate, selectedTime, 'apple_pay', selectedService);
        }
    };

    const handlePayAndBook = async () => {
        if (!selectedService) return;
        Monitoring.trackEvent({ name: 'begin_checkout', params: { service: selectedService.name, price: selectedService.price } });
        setIsProcessing(true);
        if (paymentMethod === 'apple_pay') { setTimeout(() => { setIsProcessing(false); processDirectApplePay(); }, 500); return; } 
        if (paymentMethod === 'card') {
            try {
                await createStripePaymentIntent(selectedService.price * 100);
                setTimeout(() => { 
                    setIsProcessing(false); 
                    Monitoring.trackEvent({ name: 'purchase', params: { price: selectedService.price, service: selectedService.name } });
                    onConfirm(selectedDate, selectedTime, paymentMethod, selectedService); 
                }, 1500);
            } catch (error) { 
                setIsProcessing(false); 
                Monitoring.logError(error as Error, { context: 'StripePayment' });
                alert("Chyba při komunikaci s platební bránou."); 
            }
            return;
        }
        setTimeout(() => { 
            setIsProcessing(false); 
            Monitoring.trackEvent({ name: 'purchase', params: { price: selectedService.price, service: selectedService.name, method: 'cash' } });
            onConfirm(selectedDate, selectedTime, paymentMethod, selectedService); 
        }, 1000);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl w-full max-w-4xl overflow-hidden shadow-2xl flex flex-col md:flex-row h-[600px] md:h-[600px]">
                <div className="bg-sage-600 text-white p-8 md:w-1/3 flex flex-col justify-between relative overflow-hidden">
                    <div className="relative z-10">
                        <div className="flex items-center gap-2 mb-6 cursor-pointer opacity-80 hover:opacity-100" onClick={onClose}><ChevronLeft className="w-4 h-4" /> Zpět</div>
                        <h2 className="text-2xl font-bold font-heading mb-2">{step === 0 ? 'Výběr služby' : step === 1 ? 'Výběr termínu' : 'Platba'}</h2>
                        <div className="w-12 h-1 bg-white/30 rounded-full mb-6"></div>
                        <div className="space-y-6">
                             <div><p className="text-sage-200 text-xs uppercase tracking-wider mb-1">Terapeut</p><p className="font-bold text-lg leading-tight">{practitioner.name}</p><p className="text-sage-100 text-sm">{practitioner.title}</p></div>
                            {selectedService && (<div className="bg-white/10 p-3 rounded-lg border border-white/10 animate-in fade-in"><p className="text-sage-200 text-xs uppercase tracking-wider mb-1">Služba</p><p className="font-bold">{selectedService.name}</p><p className="text-sm opacity-80">{selectedService.price} Kč • {selectedService.durationMinutes} min</p></div>)}
                            {selectedDate && selectedTime && (<div className="bg-white/10 p-3 rounded-lg border border-white/10 animate-in fade-in"><p className="text-sage-200 text-xs uppercase tracking-wider mb-1">Termín</p><div className="flex items-center gap-2 font-bold"><CalendarIcon className="w-4 h-4" />{new Date(selectedDate).toLocaleDateString('cs-CZ')}</div><div className="flex items-center gap-2 mt-1"><div className="bg-white/20 px-2 py-0.5 rounded text-sm">{selectedTime}</div></div></div>)}
                        </div>
                    </div>
                </div>
                <div className="p-8 md:w-2/3 flex flex-col h-full bg-white overflow-y-auto">
                    {step === 0 && (
                        <div className="flex-grow space-y-4 animate-in slide-in-from-right-8 duration-300">
                             {practitioner.id === 'rental' && (<div className="bg-blue-50 border border-blue-100 p-4 rounded-xl mb-4 flex gap-3"><Info className="w-5 h-5 text-blue-600 flex-shrink-0" /><div><h4 className="font-bold text-blue-800 text-sm">Pronájem pro skupiny</h4><p className="text-xs text-blue-700 mt-1">Chystáte skupinovou akci? Pro rezervaci celého prostoru pro skupiny nás prosím kontaktujte e-mailem na <a href="mailto:info@centrumunity.cz" className="underline font-bold">info@centrumunity.cz</a>.</p></div></div>)}
