};

const AppContent = () => {
  const [practitioners, setPractitioners] = useState<Practitioner[]>(PRACTITIONERS);
  // SEED INITIAL DATA: We load mock bookings so the analytics dashboard isn't empty on first load.
  const [bookings, setBookings] = useState<Booking[]>(generateMockBookings());
  const [selectedPractitioner, setSelectedPractitioner] = useState<Practitioner | null>(null);
  const [currentUser, setCurrentUser] = useState<Practitioner | null>(null);
  const [initialBookingDate, setInitialBookingDate] = useState<string>('');
  const [initialBookingTime, setInitialBookingTime] = useState<string>('');
  const navigate = useNavigate();

  const handleBook = (practitioner: Practitioner, date?: string, time?: string) => {
    if (!currentUser) { navigate('/login'); return; }
    const upToDatePractitioner = practitioners.find(p => p.id === practitioner.id) || practitioner;
    if (date) setInitialBookingDate(date); else setInitialBookingDate('');
    if (time) setInitialBookingTime(time); else setInitialBookingTime('');
    setSelectedPractitioner(upToDatePractitioner);
  };

  // --- ADMIN & PRACTITIONER ACTIONS ---

  // 1. Internal Booking (Practitioner Dashboard)
  const handleInternalBooking = async (
      date: string, 
      time: string, 
      service: Service, 
      clientName?: string, 
      paymentMethod: 'invoice' | 'qr' | 'apple_pay' = 'apple_pay',
      equipment: 'futon' | 'table' = 'table'
  ) => {
      if (!currentUser) return;

      const newBooking: Booking = {
          id: Date.now().toString(),
          practitionerId: currentUser.id,
          practitionerName: currentUser.name,
          serviceName: service.name + (clientName ? ` (${clientName})` : ''),
          date: date,
          time: time,
          durationMinutes: service.durationMinutes,
          status: 'confirmed',
          price: service.price,
          paymentMethod: paymentMethod === 'apple_pay' ? 'apple_pay' : 'invoice', 
          paymentStatus: paymentMethod === 'apple_pay' ? 'paid' : (paymentMethod === 'qr' ? 'pay_at_venue' : 'invoice_pending'),
          room: service.targetRoom || 1,
          equipment: equipment // Save equipment
      };

      await saveBookingToFirestore(newBooking);
      setBookings(prev => [...prev, newBooking]);

      NotificationService.sendBookingConfirmation(newBooking, service, 'lektor@centrumunity.cz');
      NotificationService.notifyPractitioner(newBooking, currentUser);

      Monitoring.trackEvent({ 
          name: 'purchase', 
          params: { price: service.price, service: 'Internal Booking', method: paymentMethod } 
      });
  };

  // 2. Admin Rescheduling (Admin Dashboard)
  const handleAdminReschedule = async (bookingId: string, newDate: string, newTime: string, reason?: string) => {
      setBookings(prev => prev.map(b => {
          if (b.id === bookingId) {
              const oldBooking = { ...b };
              const updated = { ...b, date: newDate, time: newTime };

              // Notify Client via Email
              NotificationService.sendRescheduleNotice(oldBooking, newDate, newTime, reason);

              // Log Audit Trail (Console for now)
              console.group("⚠️ ADMIN ACTION: RESCHEDULE");
              console.log(`Booking ID: ${bookingId}`);
              console.log(`Change: ${oldBooking.date} ${oldBooking.time} -> ${newDate} ${newTime}`);
              console.log(`Reason: ${reason || 'N/A'}`);
              console.groupEnd();

              return updated;
          }
          return b;
      }));
  };

  // 3. Client Booking (Standard)
  const confirmBooking = async (date: string, time: string, paymentMethod: 'card' | 'cash' | 'apple_pay', service: Service) => {
    if (selectedPractitioner) {
        const newBooking: Booking = {
            id: Date.now().toString(),
            practitionerId: selectedPractitioner.id,
            practitionerName: selectedPractitioner.name,
            serviceName: service.name,
            date: date,
            time: time,
            durationMinutes: service.durationMinutes,
            status: 'confirmed',
            price: service.price,
            paymentMethod: paymentMethod,
            paymentStatus: paymentMethod === 'cash' ? 'pay_at_venue' : 'paid',
            room: service.targetRoom || 1
        };
        await saveBookingToFirestore(newBooking);
        setBookings(prev => [...prev, newBooking]);

        NotificationService.sendBookingConfirmation(newBooking, service);
        NotificationService.notifyPractitioner(newBooking, selectedPractitioner);

        setSelectedPractitioner(null);
    }
  };

  const handleCancelBooking = (bookingId: string) => {
      const booking = bookings.find(b => b.id === bookingId);
      if (window.confirm("Opravdu chcete zrušit tuto rezervaci?")) {
          // SOFT DELETE LOGIC
          const cancellationTime = new Date().toISOString();
          const reason = "Zrušeno uživatelem / lektorem";

          setBookings(prev => prev.map(b => {
             if (b.id === bookingId) {
                 return {
                     ...b,
                     status: 'cancelled',
                     paymentStatus: 'cancelled', // Or refunded if paid
                     cancelledAt: cancellationTime,
                     cancellationReason: reason
                 };
             }
             return b;
          }));

          if (booking) {
             NotificationService.sendCancellationNotice(booking, reason);
          } else {
             alert("Rezervace byla zrušena.");
          }
      }
  };

  const handleUpdatePractitioner = (updated: Practitioner) => {
    setPractitioners(prev => prev.map(p => p.id === updated.id ? updated : p));
  };
  const handleLogin = (user: Practitioner) => { 
      setCurrentUser(user); 
      Monitoring.trackEvent({ name: 'login', params: { method: 'demo_select' } });
  };
