const AppContent = () => {
  const [practitioners, setPractitioners] = useState<Practitioner[]>(PRACTITIONERS);
  // SEED INITIAL DATA: We load mock bookings so the analytics dashboard isn't empty on first load.
  const [bookings, setBookings] = useState<Booking[]>(generateMockBookings());
  const [currentUser, setCurrentUser] = useState<Practitioner | null>(null);
  const navigate = useNavigate();

  // --- ADMIN & PRACTITIONER ACTIONS ---

  // 1. Internal Booking (Practitioner Dashboard)
  const handleInternalBooking = async (
      date: string, 
      time: string, 
      service: Service, 
      clientName?: string, 
      paymentMethod: 'invoice' | 'qr' | 'apple_pay' = 'apple_pay',
      equipment: 'futon' | 'table' = 'table',
      clientEmail?: string,
      clientPhone?: string,
      note?: string
  ) => {
      if (!currentUser) return;

      const newBooking: Booking = {
          id: Date.now().toString(),
          practitionerId: currentUser.id,
          practitionerName: currentUser.name,
          serviceName: service.name + (clientName ? ` (${clientName})` : ''),
          date: date,
          time: time,
          durationMinutes: service.durationMinutes,
          status: 'confirmed',
          price: service.price,
          paymentMethod: paymentMethod === 'apple_pay' ? 'apple_pay' : 'invoice', 
          paymentStatus: paymentMethod === 'apple_pay' ? 'paid' : (paymentMethod === 'qr' ? 'pay_at_venue' : 'invoice_pending'),
          room: service.targetRoom || 1,
          equipment: equipment,
          clientName,
          clientEmail,
          clientPhone,
          note
      };

      await saveBookingToFirestore(newBooking);
      setBookings(prev => [...prev, newBooking]);

      NotificationService.sendBookingConfirmation(newBooking, service, clientEmail || 'lektor@centrumunity.cz');
      NotificationService.notifyPractitioner(newBooking, currentUser);

      Monitoring.trackEvent({ 
          name: 'purchase', 
          params: { price: service.price, service: 'Internal Booking', method: paymentMethod } 
      });
  };

  // 2. Admin Rescheduling (Admin Dashboard)
  const handleAdminReschedule = async (bookingId: string, newDate: string, newTime: string, reason?: string) => {
      setBookings(prev => prev.map(b => {
          if (b.id === bookingId) {
              const oldBooking = { ...b };
              const updated = { ...b, date: newDate, time: newTime };

              // Notify Client via Email
              NotificationService.sendRescheduleNotice(oldBooking, newDate, newTime, reason);

              return updated;
          }
          return b;
      }));
  };

  const handleCancelBooking = (bookingId: string) => {
      const booking = bookings.find(b => b.id === bookingId);
      if (window.confirm("Opravdu chcete zrušit tuto rezervaci?")) {
          // SOFT DELETE LOGIC
          const cancellationTime = new Date().toISOString();
          const reason = "Zrušeno uživatelem / lektorem";

          setBookings(prev => prev.map(b => {
             if (b.id === bookingId) {
                 return {
                     ...b,
                     status: 'cancelled',
                     paymentStatus: 'cancelled', // Or refunded if paid
                     cancelledAt: cancellationTime,
                     cancellationReason: reason
                 };
             }
             return b;
          }));

          if (booking) {
             NotificationService.sendCancellationNotice(booking, reason);
          }
      }
  };

  const handleUpdatePractitioner = (updated: Practitioner) => {
    setPractitioners(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  const handleLogin = (user: Practitioner) => { 
      setCurrentUser(user); 
      Monitoring.trackEvent({ name: 'login', params: { method: 'demo_select' } });
  };

  const handleLogout = () => { setCurrentUser(null); navigate('/login'); };

  // NEW: Quick Switch Role for Demo
  const handleQuickSwitch = (targetId: string) => {
      const user = practitioners.find(p => p.id === targetId);
      if (user) {
          setCurrentUser(user);
          // Navigate to respective dashboard
          if (user.role === Role.ADMIN) {
              navigate('/admin');
          } else {
              navigate('/practitioner');
          }
          Monitoring.trackEvent({ name: 'login', params: { method: 'quick_switch', userId: user.id } });
      }
  };

  return (
      <div className="min-h-screen bg-stone-50 font-sans text-stone-800 flex flex-col">
        <Navbar currentUser={currentUser} onLogout={handleLogout} onSwitchUser={handleQuickSwitch} />
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 flex-grow w-full">
          <Routes>
            {/* PUBLIC / ENTRY ROUTES */}
            <Route path="/login" element={<Login onLogin={handleLogin} />} />

            {/* ROOT REDIRECT */}
            <Route path="/" element={
                currentUser ? (
                    currentUser.role === Role.ADMIN ? <Navigate to="/admin" /> : <Navigate to="/practitioner" />
                ) : (
                    <Navigate to="/login" />
                )
            } />

            {/* PROTECTED ROUTES */}
            <Route path="/practitioner" element={
                currentUser ? (
                    <PractitionerDashboard 
                        practitioners={practitioners} 
                        updatePractitioner={handleUpdatePractitioner} 
                        allBookings={bookings} 
                        currentUser={currentUser} 
                        onCancelBooking={handleCancelBooking} 
                        onInternalBook={handleInternalBooking} 
                    />
                ) : <Navigate to="/login" />
            } />

            <Route path="/admin" element={
                currentUser && currentUser.role === Role.ADMIN ? (
                    <AdminDashboard 
                        allBookings={bookings}
                        practitioners={practitioners}
                        updatePractitioner={handleUpdatePractitioner}
                        onAdminReschedule={handleAdminReschedule}
                    />
                ) : <Navigate to="/login" />
            } />

            {/* CATCH ALL - Redirect to login */}
            <Route path="*" element={<Navigate to="/login" />} />
          </Routes>
        </main>
        <footer className="bg-white border-t border-stone-200 mt-auto py-8">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                 <p className="text-sm text-stone-400">&copy; 2026 Centrum Unity | Interní Rezervační Systém</p>
                 <p className="text-xs text-stone-300 mt-1">Technická podpora: support@centrumunity.cz</p>
            </div>
        </footer>
        <AIChatBot />
      </div>
  );
};

