import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { PRACTITIONERS } from '../constants';
import { Practitioner, Role } from '../types';
import Button from '../components/Button';
import { User, Lock, ArrowRight, ShieldCheck, Key } from 'lucide-react';

interface LoginProps {
  onLogin: (user: Practitioner) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const navigate = useNavigate();
  const [selectedId, setSelectedId] = useState<string>(PRACTITIONERS[0].id);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = PRACTITIONERS.find(p => p.id === selectedId);
    if (user) {
      onLogin(user);
      if (user.role === Role.ADMIN) {
          navigate('/admin');
      } else {
          navigate('/practitioner');
      }
    }
  };

  const selectedUser = PRACTITIONERS.find(p => p.id === selectedId);
  const isAdmin = selectedUser?.role === Role.ADMIN;

  return (
    <div className="min-h-[80vh] flex flex-col items-center justify-center px-4 animate-in fade-in">

      {/* Portal Branding */}
      <div className="mb-8 text-center">
          <div className="inline-block p-4 bg-white rounded-full shadow-lg mb-4">
               <img src="logo.png" alt="Logo" className="w-16 h-16 rounded-full object-cover" />
          </div>
          <h1 className="text-3xl font-bold text-stone-900 font-heading tracking-tight">Centrum Unity</h1>
          <p className="text-stone-500 tracking-widest text-sm uppercase font-bold mt-1">Interní Rezervační Portál</p>
      </div>

      <div className={`max-w-md w-full bg-white rounded-2xl shadow-xl border overflow-hidden transition-all duration-500 ${isAdmin ? 'border-indigo-200 ring-4 ring-indigo-50/50' : 'border-stone-200 ring-4 ring-stone-50/50'}`}>

        {/* Header Strip */}
        <div className={`h-2 w-full ${isAdmin ? 'bg-indigo-600' : 'bg-sage-600'}`}></div>

        <div className="p-8">
          <div className="text-center mb-8">
               <h2 className="text-2xl font-bold text-stone-900">Vítejte zpět</h2>
               <p className="text-stone-500 text-sm mt-1">Přihlaste se pro správu rezervací</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-stone-400 uppercase tracking-wider mb-2">Identita uživatele (Demo Výběr)</label>
              <div className="relative group">
                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400 group-focus-within:text-sage-600 transition-colors">
                     <Key className="w-5 h-5" />
                </div>
                <select
                  value={selectedId}
                  onChange={(e) => setSelectedId(e.target.value)}
                  className="w-full pl-10 pr-4 py-4 border border-stone-200 bg-stone-50 rounded-xl focus:ring-2 focus:ring-sage-500 focus:border-sage-500 outline-none appearance-none font-medium text-stone-900 transition-all hover:bg-white"
                >
                  <optgroup label="Management Studia">
                      {PRACTITIONERS.filter(p => p.role === Role.ADMIN).map(p => (
                        <option key={p.id} value={p.id}>
                          {p.name} (Admin)
                        </option>
                      ))}
                  </optgroup>
                  <optgroup label="Aktivní Lektoři">
                      {PRACTITIONERS.filter(p => p.role !== Role.ADMIN).map(p => (
                        <option key={p.id} value={p.id}>
                          {p.name}
                        </option>
                      ))}
                  </optgroup>
                </select>
              </div>
            </div>

            {/* Context Info Box */}
            <div className={`p-4 rounded-xl border flex gap-3 transition-colors duration-300 ${isAdmin ? 'bg-indigo-50 border-indigo-100' : 'bg-stone-50 border-stone-100'}`}>
                <div className="flex-shrink-0 mt-0.5">
                    {isAdmin ? <ShieldCheck className="w-5 h-5 text-indigo-600" /> : <User className="w-5 h-5 text-sage-600" />}
                </div>
                <div className="text-sm">
                    <span className={`font-bold block mb-0.5 ${isAdmin ? 'text-indigo-900' : 'text-stone-900'}`}>
                        {isAdmin ? 'Administrátorská práva' : 'Lektorský přístup'}
                    </span>
                    <p className={`text-xs leading-relaxed ${isAdmin ? 'text-indigo-700' : 'text-stone-500'}`}>
                        {isAdmin 
                         ? 'Plný přístup k nastavení studia, správě týmu a přehledu všech tržeb.' 
                         : 'Správa vlastního kalendáře, rezervace místností pro klienty a osobní statistiky.'}
                    </p>
                </div>
            </div>

            <Button 
                type="submit" 
                className={`w-full py-4 text-lg font-bold rounded-xl shadow-lg hover:shadow-xl transition-all transform hover:-translate-y-0.5 ${isAdmin ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-sage-600 hover:bg-sage-700'}`}
            >
              Vstoupit do systému <ArrowRight className="w-5 h-5 ml-2" />
            </Button>
          </form>
        </div>
      </div>

      <p className="mt-8 text-xs text-stone-400">
          © 2026 Centrum Unity Internal System v2.1
      </p>
    </div>
  );
};

export default Login;

