                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-stone-300 rounded-sm"></div> Obsazeno</div>
                        </div>
                        <button onClick={onLogout} className="p-2 hover:bg-red-50 text-stone-400 hover:text-red-600 rounded-lg transition-colors">
                            <LogOut className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-4 py-6">

                {/* Controls */}
                <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                     <h2 className="text-2xl font-bold font-heading text-stone-800">Rozvrh Studia</h2>

                     <div className="flex items-center gap-4 bg-white p-1.5 rounded-xl shadow-sm border border-stone-200">
