                                            // Anonymized
                                            content = <span className="text-[9px] font-bold text-stone-500 truncate px-1">{data.booking?.bookedByName}</span>;
                                        } else if (data.status === 'cleaning') {
                                            bgClass = "bg-amber-100 cursor-not-allowed repeating-linear-gradient-45";
                                        }

                                        return (
                                            <div 
