export default PractitionerDashboard;

import React, { useState } from 'react';
import { Practitioner, Booking } from '../types';
import { GENERATED_TIMES, CATEGORIES, BUFFER_SAME_USER, BUFFER_DIFF_USER } from '../constants';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon, Clock, Users, Sparkles, AlertCircle, Filter, X } from 'lucide-react';

interface CalendarViewProps {
  practitioners: Practitioner[];
  bookings: Booking[];
  onBook: (practitioner: Practitioner, date: string, time: string) => void;
}

const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];

// Helper to convert time string to minutes
const timeToMinutes = (time: string): number => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

const CalendarView: React.FC<CalendarViewProps> = ({ practitioners, bookings, onBook }) => {
  const [currentWeekStart, setCurrentWeekStart] = useState(new Date());
  const [selectedCategory, setSelectedCategory] = useState<string>('Vše');

  // State for the "Show All" modal when a slot has too many people
  const [expandedSlot, setExpandedSlot] = useState<{date: Date, time: string, people: Practitioner[]} | null>(null);

  // Helper to move weeks
  const changeWeek = (offset: number) => {
    const newDate = new Date(currentWeekStart);
    newDate.setDate(newDate.getDate() + (offset * 7));
    setCurrentWeekStart(newDate);
  };

  // Generate dates for the view (Monday to Friday)
  const weekDays = Array.from({ length: 5 }, (_, i) => {
    const d = new Date(currentWeekStart);
    // Adjust to Monday of current week if today isn't Monday
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
    d.setDate(diff + i);
    return d;
  });

  const formatDate = (date: Date) => date.toISOString().split('T')[0];

  const getAvailablePractitionersForSlot = (date: Date, time: string) => {
    const dateStr = formatDate(date);
    const dayName = DAYS_MAP[date.getDay()]; // "Po", "Út"...
    const availabilityKey = `${dayName}-${time}`;

    // Convert current slot time to minutes for overlap check
    const slotStartMinutes = timeToMinutes(time);

    // Filter Practitioners
    let available = practitioners.filter(p => {
      // 0. EXCLUDE RENTALS
      if (p.category === 'Pronájem prostor' || p.id === 'rental') return false;

      // 1. Availability Template
      if (!p.availability.includes(availabilityKey)) return false;

      // 2. Personal Booking (If practitioner is already booked somewhere else at this time)
      const isPersonallyBooked = bookings.some(b => {
          if (b.date !== dateStr || b.status !== 'confirmed' || b.practitionerId !== p.id) return false;
          const bStart = timeToMinutes(b.time);
          const bEnd = bStart + b.durationMinutes;
          // Check overlap with slot start
          return (slotStartMinutes >= bStart && slotStartMinutes < bEnd);
      });
      if (isPersonallyBooked) return false;

      // 3. Room Constraints & DYNAMIC BUFFER
      const needsRoom1 = p.services.some(s => s.type === '1-1' || s.targetRoom === 1);
      const needsRoom2 = p.services.some(s => s.type === 'group' || s.targetRoom === 2);

      const isRoomAvailableForP = (roomNum: 1 | 2) => {
          // Check if any booking in this room blocks P
          return !bookings.some(b => {
                if (b.date !== dateStr || b.status !== 'confirmed' || b.room !== roomNum) return false;

                const bStart = timeToMinutes(b.time);
                const bEnd = bStart + b.durationMinutes;

                // DYNAMIC BUFFER:
                // If the existing booking is by P -> 30 min buffer.
                // If the existing booking is by someone else -> 60 min buffer.
                const bufferAfterB = (b.practitionerId === p.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
                const blockedUntil = bEnd + bufferAfterB;

                // Is the slot start time blocked?
                // Booking interval: [bStart, bEnd]
                // Cleaning interval: [bEnd, blockedUntil]

                if (slotStartMinutes >= bStart && slotStartMinutes < blockedUntil) return true;

                return false;
          });
      };

      if (needsRoom1 && !isRoomAvailableForP(1)) return false;
      if (needsRoom2 && !isRoomAvailableForP(2)) {
          // For Room 2, we might have different logic for groups, but assuming strict slot booking here.
          return false;
      }

      return true;
    });

    // 4. Apply Category Filter
    if (selectedCategory !== 'Vše') {
        available = available.filter(p => p.category === selectedCategory);
    }

    return available;
  };

  // Helper to render a practitioner button (used in both grid and modal)
  const renderPractitionerButton = (p: Practitioner, date: Date, time: string) => (
      <button
          key={p.id}
          onClick={() => {
              onBook(p, formatDate(date), time);
              setExpandedSlot(null);
          }}
          className="w-full text-left bg-white border border-stone-200 rounded-lg p-1.5 shadow-sm hover:shadow-md hover:border-sage-300 hover:ring-1 hover:ring-sage-300 transition-all group mb-1 last:mb-0"
      >
          <div className="flex items-center justify-between gap-1 mb-0.5">
              <span className="text-[9px] font-bold uppercase tracking-wider text-sage-600 bg-sage-50 px-1 py-0.5 rounded-sm truncate max-w-[80px]">
                  {p.category.split(' ')[0]}
              </span>
              <Sparkles className="w-2.5 h-2.5 text-stone-300 group-hover:text-sage-500 flex-shrink-0" />
          </div>
          <div className="text-xs font-bold text-stone-800 leading-tight truncate">
              {p.name}
          </div>
      </button>
  );

  const visibleCategories = CATEGORIES.filter(c => c !== 'Pronájem prostor');

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12 relative">
      {/* Header */}
      <div className="flex flex-col gap-6 pt-4 px-2">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
            <div>
               <h1 className="text-3xl font-bold text-stone-900 font-heading">Rozvrh dostupných lektorů</h1>
               <p className="text-stone-600">Vyberte si termín a rezervujte si své místo.</p>
            </div>

            {/* Week Navigation */}
            <div className="flex items-center gap-4 bg-white p-2 rounded-xl shadow-sm border border-stone-200 self-end">
                <button onClick={() => changeWeek(-1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600">
                    <ChevronLeft className="w-5 h-5" />
                </button>
                <div className="flex items-center gap-2 font-medium min-w-[140px] justify-center text-stone-800">
                    <CalendarIcon className="w-4 h-4 text-sage-600" />
                    <span>
                        {weekDays[0].getDate()}. {weekDays[0].getMonth() + 1}. – {weekDays[4].getDate()}. {weekDays[4].getMonth() + 1}.
                    </span>
                </div>
                <button onClick={() => changeWeek(1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600">
                    <ChevronRight className="w-5 h-5" />
                </button>
            </div>
        </div>

        {/* Filters */}
        <div className="flex items-center gap-2 overflow-x-auto pb-2 scrollbar-hide">
            <div className="flex items-center gap-2 px-3 text-stone-400 font-medium text-sm">
                <Filter className="w-4 h-4" /> Filtrovat:
            </div>
            {visibleCategories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-3 py-1.5 rounded-full whitespace-nowrap text-xs font-bold transition-all ${
                  selectedCategory === cat 
                  ? 'bg-sage-600 text-white shadow-md' 
                  : 'bg-white text-stone-600 hover:bg-stone-100 border border-stone-200'
                }`}
              >
                {cat}
              </button>
            ))}
        </div>
      </div>

      {/* Calendar Grid */}
      <div className="overflow-x-auto pb-4">
        <div className="min-w-[1000px] bg-white rounded-2xl shadow-sm border border-stone-200 overflow-hidden">
            {/* Header Row */}
            <div className="grid grid-cols-6 border-b border-stone-200 bg-stone-50">
                <div className="p-4 text-center font-bold text-stone-400 border-r border-stone-200 flex items-center justify-center">
                    <Clock className="w-5 h-5" />
                </div>
                {weekDays.map(d => (
                    <div key={d.toString()} className="p-4 text-center border-r border-stone-200 last:border-0">
                        <div className="font-bold text-sage-900">{DAYS_MAP[d.getDay()]}</div>
                        <div className="text-sm text-stone-500">{d.getDate()}. {d.getMonth() + 1}.</div>
                    </div>
                ))}
            </div>

            {/* Time Rows */}
            {GENERATED_TIMES.map((time, idx) => {
                const isHalfHour = time.endsWith(':30');
                return (
                <div key={time} className={`grid grid-cols-6 border-b border-stone-100 last:border-0 hover:bg-stone-50/30 transition-colors ${isHalfHour ? 'bg-stone-50/20' : ''}`}>
                    {/* Time Column */}
                    <div className={`p-4 flex items-center justify-center font-bold border-r border-stone-200 bg-stone-50/50 ${isHalfHour ? 'text-stone-400 text-xs' : 'text-stone-600'}`}>
                        {time}
                    </div>

                    {/* Days Columns */}
                    {weekDays.map(date => {
                        const availablePeople = getAvailablePractitionersForSlot(date, time);
                        const isPast = date < new Date(new Date().setHours(0,0,0,0));

                        // LOGIC FOR HANDLING MANY PRACTITIONERS
                        const MAX_VISIBLE = 3;
                        const visiblePeople = availablePeople.slice(0, MAX_VISIBLE);
                        const hiddenCount = availablePeople.length - MAX_VISIBLE;

                        return (
                            <div key={`${date}-${time}`} className="p-2 border-r border-stone-200 last:border-0 min-h-[80px] relative">
                                {isPast ? (
                                    <div className="absolute inset-0 bg-stone-100/50 flex items-center justify-center">
                                        {/* Grayed out for past */}
                                    </div>
                                ) : (
                                    <div className="space-y-1">
                                        {availablePeople.length === 0 ? (
                                            <div className="h-full flex items-center justify-center text-stone-300 text-xs py-4">
                                                -
                                            </div>
                                        ) : (
                                            <>
                                                {visiblePeople.map(p => renderPractitionerButton(p, date, time))}

                                                {/* "Show More" Button if too many people */}
                                                {hiddenCount > 0 && (
                                                    <button 
                                                        onClick={() => setExpandedSlot({ date, time, people: availablePeople })}
                                                        className="w-full text-center text-[10px] font-bold text-sage-700 bg-sage-50 hover:bg-sage-100 py-1.5 rounded transition-colors"
                                                    >
                                                        +{hiddenCount} dalších
                                                    </button>
                                                )}
                                            </>
                                        )}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )})}
        </div>
      </div>

      <div className="bg-sage-50 p-4 rounded-xl flex items-start gap-3 border border-sage-100 max-w-2xl mx-auto">
        <AlertCircle className="w-5 h-5 text-sage-600 mt-0.5" />
        <div className="text-sm text-sage-800">
            <p className="font-bold mb-1">Jak číst rozvrh?</p>
            <p>Kliknutím na kartičku přejdete k rezervaci. Pro zúžení nabídky použijte filtr kategorií nahoře.</p>
        </div>
      </div>

      {/* Expanded Slot Modal */}
      {expandedSlot && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-in fade-in">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[80vh]">
                  <div className="bg-sage-600 p-4 flex justify-between items-center text-white flex-shrink-0">
                      <div>
                          <h3 className="font-bold text-lg">Volné termíny</h3>
                          <p className="text-sage-100 text-sm">
                              {DAYS_MAP[expandedSlot.date.getDay()]} {expandedSlot.date.getDate()}.{expandedSlot.date.getMonth()+1}. v {expandedSlot.time}
                          </p>
                      </div>
                      <button onClick={() => setExpandedSlot(null)} className="hover:bg-white/20 p-1 rounded-full">
                          <X className="w-5 h-5" />
                      </button>
                  </div>

                  <div className="p-4 overflow-y-auto space-y-2">
                      <p className="text-sm text-stone-500 mb-2">V tento čas je k dispozici {expandedSlot.people.length} lektorů:</p>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                          {expandedSlot.people.map(p => renderPractitionerButton(p, expandedSlot.date, expandedSlot.time))}
                      </div>
                  </div>

                  <div className="p-4 border-t border-stone-100 bg-stone-50 text-right flex-shrink-0">
                      <button onClick={() => setExpandedSlot(null)} className="text-stone-500 hover:text-stone-800 text-sm font-medium">Zavřít</button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useMemo } from 'react';
import { Booking, Practitioner } from '../types';
import { GENERATED_TIMES, BUFFER_SAME_USER, BUFFER_DIFF_USER, RENTAL_PRICING } from '../constants';
import Button from '../components/Button';
import { Calendar, ChevronLeft, ChevronRight, Clock, User, Check, AlertCircle, Info, Lock, Zap, LogOut, Loader2, Bed, Layers, Sparkles } from 'lucide-react';

interface StudioScheduleProps {
  currentUser: Practitioner;
  allBookings: Booking[];
  onBook: (bookingData: Partial<Booking>) => Promise<void>;
  onCancel: (bookingId: string) => void;
  onLogout: () => void;
}

const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];

// Helper: Convert time "14:30" -> minutes 870
const timeToMinutes = (time: string): number => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

// Helper: Convert minutes -> time string "14:30"
const minutesToTime = (minutes: number): string => {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
};

const StudioSchedule: React.FC<StudioScheduleProps> = ({ 
    currentUser, 
    allBookings, 
    onBook, 
    onCancel,
    onLogout
}) => {
    const [currentWeekStart, setCurrentWeekStart] = useState(new Date());
    const [selectedSlot, setSelectedSlot] = useState<{date: string, time: string, room: 1 | 2} | null>(null);

    // Booking Form State
    const [duration, setDuration] = useState<number>(60);
    const [clientName, setClientName] = useState('');
    const [equipment, setEquipment] = useState<'table' | 'futon'>('table'); 
    const [isProcessing, setIsProcessing] = useState(false);

    // --- CALENDAR LOGIC ---

    const changeWeek = (offset: number) => {
        const newDate = new Date(currentWeekStart);
        newDate.setDate(newDate.getDate() + (offset * 7));
        setCurrentWeekStart(newDate);
    };

    // Generate 5 days (Mon-Fri) for the view
    const weekDays = useMemo(() => {
        return Array.from({ length: 5 }, (_, i) => {
            const d = new Date(currentWeekStart);
            const day = d.getDay();
            const diff = d.getDate() - day + (day === 0 ? -6 : 1);
            d.setDate(diff + i);
            return d;
        });
    }, [currentWeekStart]);

    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    // Determine status of a specific slot (Free, Mine, Occupied, Cleaning)
    const getSlotStatus = (date: Date, time: string, room: 1 | 2) => {
        const dateStr = formatDate(date);
        const slotStart = timeToMinutes(time);
        const slotEnd = slotStart + 30; // Visual slot size

        // Check against existing bookings
        const overlap = allBookings.find(b => {
            if (b.date !== dateStr || b.status !== 'confirmed' || b.room !== room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            // DYNAMIC BUFFER CALCULATION:
            // If the booking is MINE, the buffer I see after it is 30 mins.
            // If the booking is SOMEONE ELSE'S, the buffer I see after it is 60 mins.
            const bufferDuration = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferDuration;

            // Check if slot is inside booking OR inside buffer
            // Slot interval: [slotStart, slotEnd]

            const isBooking = (slotStart < bEnd && slotEnd > bStart);
            const isBuffer = (slotStart < bBufferEnd && slotEnd > bEnd);

            return isBooking || isBuffer;
        });

        if (!overlap) return { status: 'free' as const };

        const bStart = timeToMinutes(overlap.time);
        const bEnd = bStart + overlap.durationMinutes;

        // Distinguish actual booking vs buffer
        const isBuffer = slotStart >= bEnd; 

        const isMine = overlap.bookedByUserId === currentUser.id;

        return {
            status: isBuffer ? 'cleaning' as const : (isMine ? 'mine' as const : 'occupied' as const),
            booking: overlap,
            // Pass the buffer info for UI if needed
            bufferUsed: (overlap.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER
        };
    };

    // --- HANDLERS ---

    const handleSlotClick = (date: Date, time: string, room: 1 | 2, statusData: ReturnType<typeof getSlotStatus>) => {
        if (statusData.status === 'free') {
            // Open Booking Modal
            setSelectedSlot({
                date: formatDate(date),
                time,
                room
            });
            setDuration(60);
            setClientName('');
            setEquipment('table'); // Default
        } else if (statusData.status === 'mine' && statusData.booking) {
            // Confirm Cancellation
            if (window.confirm(`Chcete zrušit svou rezervaci?\n\n${statusData.booking.date} v ${statusData.booking.time}`)) {
                onCancel(statusData.booking.id);
            }
        } else {
            // Occupied or Cleaning
            // alert("Tento termín je blokován.");
        }
    };

    const handleConfirmBooking = async () => {
        if (!selectedSlot) return;

        // Check for collisions with new duration
        const newStart = timeToMinutes(selectedSlot.time);
        const newEnd = newStart + duration;

        // 1. Check if USER is already booked in ANY room at this time (Bilocation check)
        const isUserDoubleBooked = allBookings.some(b => {
             if (b.bookedByUserId !== currentUser.id) return false; // Check only my bookings
             if (b.date !== selectedSlot.date || b.status !== 'confirmed') return false;

             const bStart = timeToMinutes(b.time);
             const bEnd = bStart + b.durationMinutes;

             // Check overlap
             return (newStart < bEnd && newEnd > bStart);
        });

        if (isUserDoubleBooked) {
             alert("Nelze rezervovat: V tomto čase již máte rezervaci v jiné místnosti. Nemůžete být na dvou místech najednou.");
             return;
        }

        // 2. Determine collision with OTHER bookings in the SAME room
        const hasCollision = allBookings.some(b => {
            if (b.date !== selectedSlot.date || b.status !== 'confirmed' || b.room !== selectedSlot.room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            // COLLISION LOGIC A: OVERLAP WITH BOOKING ITSELF
            if (newStart < bEnd && newEnd > bStart) return true;

            // COLLISION LOGIC B: BUFFER AFTER EXISTING BOOKING (THEY BLOCK ME)
            const bufferAfterThem = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferAfterThem;
            if (newStart < bBufferEnd && newStart >= bEnd) return true;

            // COLLISION LOGIC C: BUFFER AFTER MY NEW BOOKING (I BLOCK THEM)
            const bufferAfterMe = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const myBufferEnd = newEnd + bufferAfterMe;
            if (newEnd <= bStart && myBufferEnd > bStart) return true;

            return false;
        });

        if (hasCollision) {
            alert("Nelze rezervovat: Zvolený čas koliduje s jinou rezervací nebo povinným úklidem (60 min pro různé lektory, 30 min pro stejného).");
            return;
        }

        setIsProcessing(true);

        // Calculate Price
        const priceRate = selectedSlot.room === 1 ? RENTAL_PRICING.room1 : RENTAL_PRICING.room2;
        const finalPrice = (duration / 60) * priceRate;

        await onBook({
            bookedByUserId: currentUser.id,
            bookedByName: currentUser.name,
            date: selectedSlot.date,
            time: selectedSlot.time,
            durationMinutes: duration,
            room: selectedSlot.room,
            price: finalPrice,
            paymentStatus: 'unpaid', // In real app, redirect to gateway
            clientName: clientName,
            equipment: equipment // Pass equipment selection
        });

        setIsProcessing(false);
        setSelectedSlot(null);
    };

    return (
        <div className="min-h-screen bg-stone-50 pb-20">
            {/* Header / Navbar */}
            <div className="bg-white border-b border-stone-200 sticky top-0 z-30 shadow-sm">
                <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                         <div className="w-10 h-10 rounded-full overflow-hidden border border-stone-200">
                             <img src={currentUser.imageUrl} alt="Profile" className="w-full h-full object-cover" />
                         </div>
                         <div>
                             <h1 className="font-bold text-stone-900 leading-tight">{currentUser.name}</h1>
                             <div className="text-xs text-stone-500 font-medium">Kredit: 1200 Kč</div>
                         </div>
                    </div>

                    <div className="flex items-center gap-4">
                        <div className="hidden md:flex items-center gap-6 mr-6 text-sm font-medium text-stone-500">
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-white border border-stone-300 rounded-sm"></div> Volno</div>
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-emerald-500 rounded-sm"></div> Moje</div>
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-stone-300 rounded-sm"></div> Obsazeno</div>
                        </div>
                        <button onClick={onLogout} className="p-2 hover:bg-red-50 text-stone-400 hover:text-red-600 rounded-lg transition-colors">
                            <LogOut className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-4 py-6">

                {/* Controls */}
                <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                     <h2 className="text-2xl font-bold font-heading text-stone-800">Rozvrh Studia</h2>

                     <div className="flex items-center gap-4 bg-white p-1.5 rounded-xl shadow-sm border border-stone-200">
                        <button onClick={() => changeWeek(-1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600"><ChevronLeft className="w-5 h-5" /></button>
                        <div className="flex items-center gap-2 px-2 font-medium text-stone-800 min-w-[140px] justify-center">
                            <Calendar className="w-4 h-4 text-sage-600" />
                            <span>{weekDays[0].getDate()}.{weekDays[0].getMonth()+1}. – {weekDays[4].getDate()}.{weekDays[4].getMonth()+1}.</span>
                        </div>
                        <button onClick={() => changeWeek(1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600"><ChevronRight className="w-5 h-5" /></button>
                     </div>
                </div>

                {/* --- THE CALENDAR GRID --- */}
                <div className="bg-white rounded-2xl shadow-sm border border-stone-200 overflow-hidden">

                    {/* Header Row (Days) */}
                    <div className="grid grid-cols-[60px_1fr_1fr_1fr_1fr_1fr] border-b border-stone-200">
                         <div className="p-4 bg-stone-50/50 border-r border-stone-100"></div> {/* Time Corner */}
                         {weekDays.map(d => (
                             <div key={d.toISOString()} className="text-center border-r border-stone-100 last:border-0 flex flex-col h-full">
                                 {/* Top part: Date */}
                                 <div className="p-2 border-b border-stone-100/50 bg-white">
                                     <div className="text-xs uppercase font-bold text-stone-400 mb-0.5">{DAYS_MAP[d.getDay()]}</div>
                                     <div className={`font-bold text-lg ${d.toDateString() === new Date().toDateString() ? 'text-sage-700' : 'text-stone-800'}`}>
                                         {d.getDate()}
                                     </div>
                                 </div>
                                 {/* Bottom part: Room Columns Headers */}
                                 <div className="flex flex-1 text-[10px] font-bold uppercase tracking-wider text-stone-500">
                                     <div className="flex-1 py-1 bg-stone-50 border-r border-stone-100 flex items-center justify-center gap-1">
                                         <span className="w-2 h-2 rounded-full bg-stone-300"></span> M1 <span className="hidden xl:inline">(Malá)</span>
                                     </div>
                                     <div className="flex-1 py-1 bg-indigo-50/30 flex items-center justify-center gap-1">
                                         <span className="w-2 h-2 rounded-full bg-indigo-200"></span> M2 <span className="hidden xl:inline">(Velká)</span>
                                     </div>
                                 </div>
                             </div>
                         ))}
                    </div>

                    {/* Time Rows */}
                    <div className="relative">
                        {GENERATED_TIMES.map((time, tIdx) => (
                            <div key={time} className="grid grid-cols-[60px_1fr_1fr_1fr_1fr_1fr] min-h-[50px] border-b border-stone-100 last:border-0 group">
