export default PractitionerDashboard;

import React, { useState, useMemo } from 'react';
import { Booking, Practitioner } from '../types';
import { GENERATED_TIMES, BUFFER_SAME_USER, BUFFER_DIFF_USER, RENTAL_PRICING } from '../constants';
import Button from '../components/Button';
import { Calendar, ChevronLeft, ChevronRight, Clock, User, Check, AlertCircle, Info, Lock, Zap, LogOut, Loader2, Bed, Layers, Sparkles, History } from 'lucide-react';

interface StudioScheduleProps {
  currentUser: Practitioner;
  allBookings: Booking[];
  onBook: (bookingData: Partial<Booking>) => Promise<void>;
  onCancel: (bookingId: string) => void;
  onLogout: () => void;
}

const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];

// Helper: Convert time "14:30" -> minutes 870
const timeToMinutes = (time: string): number => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

// Helper: Convert minutes -> time string "14:30"
const minutesToTime = (minutes: number): string => {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
};

const StudioSchedule: React.FC<StudioScheduleProps> = ({ 
    currentUser, 
    allBookings, 
    onBook, 
    onCancel,
    onLogout
}) => {
    const [currentWeekStart, setCurrentWeekStart] = useState(new Date());
    const [selectedSlot, setSelectedSlot] = useState<{date: string, time: string, room: 1 | 2} | null>(null);

    // Booking Form State
    const [duration, setDuration] = useState<number>(60);
    const [clientName, setClientName] = useState('');
    const [equipment, setEquipment] = useState<'table' | 'futon'>('table'); 
    const [isProcessing, setIsProcessing] = useState(false);

    // --- CALENDAR LOGIC ---

    const changeWeek = (offset: number) => {
        const newDate = new Date(currentWeekStart);
        newDate.setDate(newDate.getDate() + (offset * 7));
        setCurrentWeekStart(newDate);
    };

    // Generate 5 days (Mon-Fri) for the view
    const weekDays = useMemo(() => {
        return Array.from({ length: 5 }, (_, i) => {
            const d = new Date(currentWeekStart);
            const day = d.getDay();
            const diff = d.getDate() - day + (day === 0 ? -6 : 1);
            d.setDate(diff + i);
            return d;
        });
    }, [currentWeekStart]);

    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    // Determine status of a specific slot (Free, Mine, Occupied, Cleaning, Past)
    const getSlotStatus = (date: Date, time: string, room: 1 | 2) => {
        const dateStr = formatDate(date);
        const slotStart = timeToMinutes(time);
        const slotEnd = slotStart + 30; // Visual slot size

        // 1. PAST CHECK Logic
        const now = new Date();
        const slotDateTime = new Date(`${dateStr}T${time}`);
        // Add minimal buffer (e.g. current minute) so we can't book this exact minute if it just passed
        if (slotDateTime < now) {
             // We still want to show bookings in the past, but mark empty slots as 'past'
             // So we proceed to check bookings first, and if no booking, return 'past'
        }

        // Check against existing bookings
        const overlap = allBookings.find(b => {
            if (b.date !== dateStr || b.status !== 'confirmed' || b.room !== room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            // DYNAMIC BUFFER CALCULATION
            const bufferDuration = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferDuration;

            const isBooking = (slotStart < bEnd && slotEnd > bStart);
            const isBuffer = (slotStart < bBufferEnd && slotEnd > bEnd);

            return isBooking || isBuffer;
        });

        if (!overlap) {
            // If no booking overlap, check if it's in the past
            if (slotDateTime < now) {
                return { status: 'past' as const };
            }
            return { status: 'free' as const };
        }

        const bStart = timeToMinutes(overlap.time);
        const bEnd = bStart + overlap.durationMinutes;

        // Distinguish actual booking vs buffer
        const isBuffer = slotStart >= bEnd; 

        const isMine = overlap.bookedByUserId === currentUser.id;

        return {
            status: isBuffer ? 'cleaning' as const : (isMine ? 'mine' as const : 'occupied' as const),
            booking: overlap,
            bufferUsed: (overlap.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER
        };
    };

    // --- HANDLERS ---

    const handleSlotClick = (date: Date, time: string, room: 1 | 2, statusData: ReturnType<typeof getSlotStatus>) => {
        if (statusData.status === 'past') {
            // Do nothing for past slots
            return;
        }

        if (statusData.status === 'free') {
            // Open Booking Modal
            setSelectedSlot({
                date: formatDate(date),
                time,
                room
            });
            setDuration(60);
            setClientName('');
            setEquipment('table'); // Default
        } else if (statusData.status === 'mine' && statusData.booking) {
            // 2. CANCELLATION POLICY CHECK
            const bookingStart = new Date(`${statusData.booking.date}T${statusData.booking.time}`);
            const now = new Date();
            const hoursDifference = (bookingStart.getTime() - now.getTime()) / (1000 * 60 * 60);

            if (hoursDifference < 24) {
                alert("Rezervaci nelze zrušit méně než 24 hodin předem.\n\nPro storno prosím kontaktujte manažera studia.");
                return;
            }

            // Confirm Cancellation
            if (window.confirm(`Chcete zrušit svou rezervaci?\n\n${statusData.booking.date} v ${statusData.booking.time}\n(Zbývá ${Math.floor(hoursDifference)}h do začátku)`)) {
                onCancel(statusData.booking.id);
            }
        }
    };

    const handleConfirmBooking = async () => {
        if (!selectedSlot) return;

        // Check for collisions with new duration
        const newStart = timeToMinutes(selectedSlot.time);
        const newEnd = newStart + duration;

        // 1. Check if USER is already booked in ANY room at this time (Bilocation check)
        const isUserDoubleBooked = allBookings.some(b => {
             if (b.bookedByUserId !== currentUser.id) return false; // Check only my bookings
             if (b.date !== selectedSlot.date || b.status !== 'confirmed') return false;

             const bStart = timeToMinutes(b.time);
             const bEnd = bStart + b.durationMinutes;

             // Check overlap
             return (newStart < bEnd && newEnd > bStart);
        });

        if (isUserDoubleBooked) {
             alert("Nelze rezervovat: V tomto čase již máte rezervaci v jiné místnosti. Nemůžete být na dvou místech najednou.");
             return;
        }

        // 2. Determine collision with OTHER bookings in the SAME room
        const hasCollision = allBookings.some(b => {
            if (b.date !== selectedSlot.date || b.status !== 'confirmed' || b.room !== selectedSlot.room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            // COLLISION LOGIC A: OVERLAP WITH BOOKING ITSELF
            if (newStart < bEnd && newEnd > bStart) return true;

            // COLLISION LOGIC B: BUFFER AFTER EXISTING BOOKING (THEY BLOCK ME)
            const bufferAfterThem = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferAfterThem;
            if (newStart < bBufferEnd && newStart >= bEnd) return true;

            // COLLISION LOGIC C: BUFFER AFTER MY NEW BOOKING (I BLOCK THEM)
            const bufferAfterMe = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const myBufferEnd = newEnd + bufferAfterMe;
            if (newEnd <= bStart && myBufferEnd > bStart) return true;

            return false;
        });

        if (hasCollision) {
            alert("Nelze rezervovat: Zvolený čas koliduje s jinou rezervací nebo povinným úklidem (60 min pro různé lektory, 30 min pro stejného).");
            return;
        }

        setIsProcessing(true);

        // Calculate Price
        const priceRate = selectedSlot.room === 1 ? RENTAL_PRICING.room1 : RENTAL_PRICING.room2;
        const finalPrice = (duration / 60) * priceRate;

        await onBook({
            bookedByUserId: currentUser.id,
            bookedByName: currentUser.name,
            date: selectedSlot.date,
            time: selectedSlot.time,
            durationMinutes: duration,
            room: selectedSlot.room,
            price: finalPrice,
            paymentStatus: 'unpaid', // In real app, redirect to gateway
            clientName: clientName,
            equipment: equipment // Pass equipment selection
        });

        setIsProcessing(false);
        setSelectedSlot(null);
    };

    return (
        <div className="min-h-screen bg-stone-50 pb-20">
            {/* Header / Navbar */}
            <div className="bg-white border-b border-stone-200 sticky top-0 z-30 shadow-sm">
                <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                         <div className="w-10 h-10 rounded-full overflow-hidden border border-stone-200">
                             <img src={currentUser.imageUrl} alt="Profile" className="w-full h-full object-cover" />
                         </div>
                         <div>
                             <h1 className="font-bold text-stone-900 leading-tight">{currentUser.name}</h1>
                             <div className="text-xs text-stone-500 font-medium">Kredit: 1200 Kč</div>
                         </div>
                    </div>

                    <div className="flex items-center gap-4">
                        <div className="hidden md:flex items-center gap-6 mr-6 text-sm font-medium text-stone-500">
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-white border border-stone-300 rounded-sm"></div> Volno</div>
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-stone-100 rounded-sm"></div> Uplynulé</div>
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-emerald-500 rounded-sm"></div> Moje</div>
                        </div>
                        <button onClick={onLogout} className="p-2 hover:bg-red-50 text-stone-400 hover:text-red-600 rounded-lg transition-colors">
                            <LogOut className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-4 py-6">

                {/* Controls */}
                <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                     <h2 className="text-2xl font-bold font-heading text-stone-800">Rozvrh Studia</h2>

                     <div className="flex items-center gap-4 bg-white p-1.5 rounded-xl shadow-sm border border-stone-200">
                        <button onClick={() => changeWeek(-1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600"><ChevronLeft className="w-5 h-5" /></button>
                        <div className="flex items-center gap-2 px-2 font-medium text-stone-800 min-w-[140px] justify-center">
                            <Calendar className="w-4 h-4 text-sage-600" />
                            <span>{weekDays[0].getDate()}.{weekDays[0].getMonth()+1}. – {weekDays[4].getDate()}.{weekDays[4].getMonth()+1}.</span>
                        </div>
                        <button onClick={() => changeWeek(1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600"><ChevronRight className="w-5 h-5" /></button>
                     </div>
                </div>

                {/* --- THE CALENDAR GRID --- */}
                <div className="bg-white rounded-2xl shadow-sm border border-stone-200 overflow-hidden">

                    {/* Header Row (Days) */}
                    <div className="grid grid-cols-[60px_1fr_1fr_1fr_1fr_1fr] border-b border-stone-200">
                         <div className="p-4 bg-stone-50/50 border-r border-stone-100"></div> {/* Time Corner */}
                         {weekDays.map(d => (
                             <div key={d.toISOString()} className="text-center border-r border-stone-100 last:border-0 flex flex-col h-full">
                                 {/* Top part: Date */}
                                 <div className="p-2 border-b border-stone-100/50 bg-white">
                                     <div className="text-xs uppercase font-bold text-stone-400 mb-0.5">{DAYS_MAP[d.getDay()]}</div>
                                     <div className={`font-bold text-lg ${d.toDateString() === new Date().toDateString() ? 'text-sage-700' : 'text-stone-800'}`}>
                                         {d.getDate()}
                                     </div>
                                 </div>
                                 {/* Bottom part: Room Columns Headers */}
                                 <div className="flex flex-1 text-[10px] font-bold uppercase tracking-wider text-stone-500">
                                     <div className="flex-1 py-1 bg-stone-50 border-r border-stone-100 flex items-center justify-center gap-1">
                                         <span className="w-2 h-2 rounded-full bg-stone-300"></span> M1 <span className="hidden xl:inline">(Malá)</span>
                                     </div>
                                     <div className="flex-1 py-1 bg-indigo-50/30 flex items-center justify-center gap-1">
                                         <span className="w-2 h-2 rounded-full bg-indigo-200"></span> M2 <span className="hidden xl:inline">(Velká)</span>
                                     </div>
                                 </div>
                             </div>
                         ))}
                    </div>

                    {/* Time Rows */}
                    <div className="relative">
                        {GENERATED_TIMES.map((time, tIdx) => (
                            <div key={time} className="grid grid-cols-[60px_1fr_1fr_1fr_1fr_1fr] min-h-[50px] border-b border-stone-100 last:border-0 group">
                                {/* Time Column */}
                                <div className="py-2 px-1 text-center text-xs font-medium text-stone-400 border-r border-stone-100 flex items-start justify-center pt-3 bg-stone-50/30">
                                    {time}
                                </div>

                                {/* Day Columns */}
                                {weekDays.map((date, dIdx) => {
                                    const r1 = getSlotStatus(date, time, 1);
                                    const r2 = getSlotStatus(date, time, 2);

                                    const renderSubSlot = (roomNum: 1|2, data: typeof r1) => {
                                        let bgClass = roomNum === 1 ? "bg-white hover:bg-stone-50" : "bg-indigo-50/10 hover:bg-indigo-50";
                                        let content = null;

                                        if (data.status === 'past') {
                                            bgClass = "bg-stone-100/60 cursor-not-allowed";
                                            // Optional: visual indicator for past
                                            // content = <span className="text-stone-300">●</span>;
                                        } else if (data.status === 'mine') {
                                            bgClass = "bg-emerald-500 hover:bg-emerald-600 text-white shadow-sm";
                                            content = <span className="text-[10px] font-bold">MOJE</span>;
                                        } else if (data.status === 'occupied') {
                                            bgClass = "bg-stone-200 cursor-not-allowed";
                                            content = <span className="text-[9px] font-bold text-stone-500 truncate px-1">{data.booking?.bookedByName}</span>;
                                        } else if (data.status === 'cleaning') {
                                            bgClass = "bg-amber-100 cursor-not-allowed repeating-linear-gradient-45";
                                        }

                                        return (
                                            <div 
                                                onClick={() => handleSlotClick(date, time, roomNum, data)}
                                                className={`flex-1 flex items-center justify-center transition-all cursor-pointer relative ${bgClass} ${roomNum === 1 ? 'border-r border-stone-200' : ''}`}
                                            >
                                                {content}
                                                {/* Hover Hint for Free Slots */}
                                                {data.status === 'free' && (
                                                    <div className="opacity-0 hover:opacity-100 absolute inset-0 flex items-center justify-center bg-sage-100/50 text-sage-700 font-bold text-xs">
                                                        +
                                                    </div>
                                                )}
                                            </div>
                                        );
                                    };

                                    return (
                                        <div key={`${date}-${time}`} className="border-r border-stone-100 last:border-0 flex">
                                            {/* Room 1 Column */}
                                            {renderSubSlot(1, r1)}
                                            {/* Room 2 Column */}
                                            {renderSubSlot(2, r2)}
                                        </div>
                                    );
                                })}
                            </div>
                        ))}
                    </div>
                </div>

                <div className="mt-6 flex gap-4 text-xs text-stone-400 justify-center">
                    <span className="flex items-center gap-2"><span className="w-3 h-3 bg-stone-50 border border-stone-200"></span> Místnost 1 (Malá)</span>
                    <span className="text-stone-300">|</span>
                    <span className="flex items-center gap-2"><span className="w-3 h-3 bg-indigo-50 border border-indigo-100"></span> Místnost 2 (Velká)</span>
                    <span className="ml-4 text-amber-600 font-bold">* Úklid: 30 min (stejný lektor) / 60 min (výměna)</span>
                    <span className="ml-4 text-red-400 font-bold">* Storno: min. 24h předem</span>
                </div>

            </div>

            {/* Booking Modal */}
            {selectedSlot && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in">
                    <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col max-h-[90vh]">
                        <div className="bg-stone-900 text-white p-6 relative flex-shrink-0">
                            <h3 className="text-xl font-bold font-heading">Nová Rezervace</h3>
                            <div className="flex items-center gap-4 text-stone-400 text-sm mt-2">
                                <span className="flex items-center gap-1"><Calendar className="w-3 h-3" /> {new Date(selectedSlot.date).toLocaleDateString('cs-CZ')}</span>
                                <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {selectedSlot.time}</span>
                            </div>
                            <button onClick={() => setSelectedSlot(null)} className="absolute top-4 right-4 p-2 bg-white/10 rounded-full hover:bg-white/20"><X className="w-4 h-4" /></button>
                        </div>

                        <div className="p-6 space-y-6 overflow-y-auto">
                            {/* Room Info */}
                            <div className="flex gap-4">
                                <div className={`flex-1 p-3 rounded-xl border-2 text-center ${selectedSlot.room === 1 ? 'border-sage-500 bg-sage-50 text-sage-800' : 'border-stone-100 text-stone-400 bg-stone-50 opacity-50'}`}>
                                    <div className="text-xs font-bold uppercase mb-1">Místnost 1</div>
                                    <div className="font-bold">Malá Terapeutovna</div>
                                    <div className="text-xs mt-1">300 Kč/h</div>
                                </div>
                                <div className={`flex-1 p-3 rounded-xl border-2 text-center ${selectedSlot.room === 2 ? 'border-sage-500 bg-sage-50 text-sage-800' : 'border-stone-100 text-stone-400 bg-stone-50 opacity-50'}`}>
                                    <div className="text-xs font-bold uppercase mb-1">Místnost 2</div>
                                    <div className="font-bold">Velký Sál</div>
                                    <div className="text-xs mt-1">500 Kč/h</div>
                                </div>
                            </div>

                            {/* Equipment Selection - NEW */}
                            <div>
                                <label className="block text-sm font-bold text-stone-700 mb-2">Jaké vybavení potřebujete?</label>
                                <div className="grid grid-cols-2 gap-3">
                                    <button
                                        onClick={() => setEquipment('table')}
                                        className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${
                                            equipment === 'table' 
                                            ? 'border-sage-600 bg-sage-50 text-sage-900 shadow-sm' 
                                            : 'border-stone-200 text-stone-500 hover:border-sage-200 hover:bg-stone-50'
                                        }`}
                                    >
                                        <Bed className="w-6 h-6" />
                                        <span className="font-bold text-sm">Lehátko (Stůl)</span>
                                    </button>
                                    <button
                                        onClick={() => setEquipment('futon')}
                                        className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${
                                            equipment === 'futon' 
                                            ? 'border-sage-600 bg-sage-50 text-sage-900 shadow-sm' 
                                            : 'border-stone-200 text-stone-500 hover:border-sage-200 hover:bg-stone-50'
                                        }`}
                                    >
                                        <Layers className="w-6 h-6" />
                                        <span className="font-bold text-sm">Futon (Země)</span>
                                    </button>
                                </div>
                            </div>

                            {/* Duration Slider/Select */}
                            <div>
                                <label className="block text-sm font-bold text-stone-700 mb-2">Délka rezervace</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {[60, 90, 120, 180, 240, 300].map(m => (
                                        <button
                                            key={m}
                                            onClick={() => setDuration(m)}
                                            className={`py-2 rounded-lg text-sm font-bold transition-all ${duration === m ? 'bg-stone-800 text-white' : 'bg-stone-100 text-stone-600 hover:bg-stone-200'}`}
                                        >
                                            {m} min
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Client Note (Optional) */}
                            <div>
                                <label className="block text-sm font-bold text-stone-700 mb-1">Klient / Poznámka (Volitelné)</label>
                                <input 
                                    type="text" 
                                    className="w-full p-3 bg-white border border-stone-200 rounded-xl text-stone-900 placeholder-stone-400 focus:ring-2 focus:ring-sage-500 outline-none"
                                    placeholder="Jméno klienta pro vaši orientaci..."
                                    value={clientName}
                                    onChange={e => setClientName(e.target.value)}
                                />
                            </div>

                            {/* Summary & Action */}
                            <div className="bg-stone-50 p-4 rounded-xl flex justify-between items-center border border-stone-100 mt-auto">
                                <div>
                                    <div className="text-xs font-bold text-stone-500 uppercase">Cena celkem</div>
                                    <div className="text-xl font-bold text-stone-900">
                                        {((duration/60) * (selectedSlot.room === 1 ? RENTAL_PRICING.room1 : RENTAL_PRICING.room2)).toFixed(0)} Kč
                                    </div>
                                </div>
                                <Button 
                                    onClick={handleConfirmBooking} 
                                    disabled={isProcessing}
                                    className="bg-black text-white hover:bg-stone-800 px-6"
                                >
                                    {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Potvrdit a Zaplatit'}
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

        </div>
    );
};

// Simple Close Icon Helper
const X = ({ className }: { className?: string }) => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M18 6 6 18"/><path d="m6 6 18 18"/></svg>
);

export default StudioSchedule;

import React, { useState, useMemo } from 'react';
import { Booking, Practitioner } from '../types';
import { GENERATED_TIMES, BUFFER_SAME_USER, BUFFER_DIFF_USER, RENTAL_PRICING } from '../constants';
import Button from '../components/Button';
import { Calendar, ChevronLeft, ChevronRight, Clock, User, Check, AlertCircle, Info, Lock, Zap, LogOut, Loader2, Bed, Layers, Sparkles, History } from 'lucide-react';

interface StudioScheduleProps {
  currentUser: Practitioner;
  allBookings: Booking[];
  onBook: (bookingData: Partial<Booking>) => Promise<void>;
  onCancel: (bookingId: string) => void;
  onLogout: () => void;
}

const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];

// Helper: Convert time "14:30" -> minutes 870
const timeToMinutes = (time: string): number => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

// Helper: Convert minutes -> time string "14:30"
const minutesToTime = (minutes: number): string => {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
};

const StudioSchedule: React.FC<StudioScheduleProps> = ({ 
    currentUser, 
    allBookings, 
    onBook, 
    onCancel,
    onLogout
}) => {
    const [currentWeekStart, setCurrentWeekStart] = useState(new Date());
    const [selectedSlot, setSelectedSlot] = useState<{date: string, time: string, room: 1 | 2} | null>(null);

    // Booking Form State
    const [duration, setDuration] = useState<number>(60);
    const [clientName, setClientName] = useState('');
    const [equipment, setEquipment] = useState<'table' | 'futon'>('table'); 
    const [isProcessing, setIsProcessing] = useState(false);

    // --- CALENDAR LOGIC ---

    const changeWeek = (offset: number) => {
        const newDate = new Date(currentWeekStart);
        newDate.setDate(newDate.getDate() + (offset * 7));
        setCurrentWeekStart(newDate);
    };

    // Generate 5 days (Mon-Fri) for the view
    const weekDays = useMemo(() => {
        return Array.from({ length: 5 }, (_, i) => {
            const d = new Date(currentWeekStart);
            const day = d.getDay();
            const diff = d.getDate() - day + (day === 0 ? -6 : 1);
            d.setDate(diff + i);
            return d;
        });
    }, [currentWeekStart]);

    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    // Determine status of a specific slot (Free, Mine, Occupied, Cleaning, Past)
    const getSlotStatus = (date: Date, time: string, room: 1 | 2) => {
        const dateStr = formatDate(date);
        const slotStart = timeToMinutes(time);
        const slotEnd = slotStart + 30; // Visual slot size

        // 1. PAST CHECK Logic
        const now = new Date();
        const slotDateTime = new Date(`${dateStr}T${time}`);
        // Add minimal buffer (e.g. current minute) so we can't book this exact minute if it just passed
        if (slotDateTime < now) {
             // We still want to show bookings in the past, but mark empty slots as 'past'
             // So we proceed to check bookings first, and if no booking, return 'past'
        }

        // Check against existing bookings
        const overlap = allBookings.find(b => {
            if (b.date !== dateStr || b.status !== 'confirmed' || b.room !== room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            // DYNAMIC BUFFER CALCULATION
            const bufferDuration = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferDuration;

            const isBooking = (slotStart < bEnd && slotEnd > bStart);
            const isBuffer = (slotStart < bBufferEnd && slotEnd > bEnd);

            return isBooking || isBuffer;
        });

        if (!overlap) {
            // If no booking overlap, check if it's in the past
            if (slotDateTime < now) {
                return { status: 'past' as const };
            }
            return { status: 'free' as const };
        }

        const bStart = timeToMinutes(overlap.time);
        const bEnd = bStart + overlap.durationMinutes;

        // Distinguish actual booking vs buffer
        const isBuffer = slotStart >= bEnd; 

        const isMine = overlap.bookedByUserId === currentUser.id;

        return {
            status: isBuffer ? 'cleaning' as const : (isMine ? 'mine' as const : 'occupied' as const),
            booking: overlap,
            bufferUsed: (overlap.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER
        };
    };

    // --- HANDLERS ---

    const handleSlotClick = (date: Date, time: string, room: 1 | 2, statusData: ReturnType<typeof getSlotStatus>) => {
        if (statusData.status === 'past') {
            // Do nothing for past slots
            return;
        }

        if (statusData.status === 'free') {
            // Open Booking Modal
            setSelectedSlot({
                date: formatDate(date),
                time,
                room
            });
            setDuration(60);
            setClientName('');
            setEquipment('table'); // Default
        } else if (statusData.status === 'mine' && statusData.booking) {
            // 2. CANCELLATION POLICY CHECK
            const bookingStart = new Date(`${statusData.booking.date}T${statusData.booking.time}`);
            const now = new Date();
            const hoursDifference = (bookingStart.getTime() - now.getTime()) / (1000 * 60 * 60);

            if (hoursDifference < 24) {
                alert("Rezervaci nelze zrušit méně než 24 hodin předem.\n\nPro storno prosím kontaktujte manažera studia.");
                return;
            }

            // Confirm Cancellation
            if (window.confirm(`Chcete zrušit svou rezervaci?\n\n${statusData.booking.date} v ${statusData.booking.time}\n(Zbývá ${Math.floor(hoursDifference)}h do začátku)`)) {
                onCancel(statusData.booking.id);
            }
        }
    };

    const handleConfirmBooking = async () => {
        if (!selectedSlot) return;

        // Check for collisions with new duration
        const newStart = timeToMinutes(selectedSlot.time);
        const newEnd = newStart + duration;

        // 1. Check if USER is already booked in ANY room at this time (Bilocation check)
        const isUserDoubleBooked = allBookings.some(b => {
             if (b.bookedByUserId !== currentUser.id) return false; // Check only my bookings
             if (b.date !== selectedSlot.date || b.status !== 'confirmed') return false;

             const bStart = timeToMinutes(b.time);
             const bEnd = bStart + b.durationMinutes;

             // Check overlap
             return (newStart < bEnd && newEnd > bStart);
        });

        if (isUserDoubleBooked) {
             alert("Nelze rezervovat: V tomto čase již máte rezervaci v jiné místnosti. Nemůžete být na dvou místech najednou.");
             return;
        }

        // 2. Determine collision with OTHER bookings in the SAME room
        const hasCollision = allBookings.some(b => {
            if (b.date !== selectedSlot.date || b.status !== 'confirmed' || b.room !== selectedSlot.room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            // COLLISION LOGIC A: OVERLAP WITH BOOKING ITSELF
            if (newStart < bEnd && newEnd > bStart) return true;

            // COLLISION LOGIC B: BUFFER AFTER EXISTING BOOKING (THEY BLOCK ME)
            const bufferAfterThem = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferAfterThem;
            if (newStart < bBufferEnd && newStart >= bEnd) return true;

            // COLLISION LOGIC C: BUFFER AFTER MY NEW BOOKING (I BLOCK THEM)
            const bufferAfterMe = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const myBufferEnd = newEnd + bufferAfterMe;
            if (newEnd <= bStart && myBufferEnd > bStart) return true;

            return false;
        });

        if (hasCollision) {
            alert("Nelze rezervovat: Zvolený čas koliduje s jinou rezervací nebo povinným úklidem (60 min pro různé lektory, 30 min pro stejného).");
            return;
        }

        setIsProcessing(true);

        // Calculate Price
        const priceRate = selectedSlot.room === 1 ? RENTAL_PRICING.room1 : RENTAL_PRICING.room2;
        const finalPrice = (duration / 60) * priceRate;

        await onBook({
            bookedByUserId: currentUser.id,
            bookedByName: currentUser.name,
            date: selectedSlot.date,
            time: selectedSlot.time,
            durationMinutes: duration,
            room: selectedSlot.room,
            price: finalPrice,
            paymentStatus: 'unpaid', // In real app, redirect to gateway
            clientName: clientName,
            equipment: equipment // Pass equipment selection
        });

        setIsProcessing(false);
        setSelectedSlot(null);
    };

    return (
        <div className="min-h-screen bg-stone-50 pb-20">
            {/* Header / Navbar */}
            <div className="bg-white border-b border-stone-200 sticky top-0 z-30 shadow-sm">
                <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                         <div className="w-10 h-10 rounded-full overflow-hidden border border-stone-200">
                             <img src={currentUser.imageUrl} alt="Profile" className="w-full h-full object-cover" />
                         </div>
                         <div>
                             <h1 className="font-bold text-stone-900 leading-tight">{currentUser.name}</h1>
                             <div className="text-xs text-stone-500 font-medium">Kredit: 1200 Kč</div>
                         </div>
                    </div>

                    <div className="flex items-center gap-4">
                        <div className="hidden md:flex items-center gap-6 mr-6 text-sm font-medium text-stone-500">
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-white border border-stone-300 rounded-sm"></div> Volno</div>
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-stone-100 rounded-sm"></div> Uplynulé</div>
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-emerald-500 rounded-sm"></div> Moje</div>
                        </div>
                        <button onClick={onLogout} className="p-2 hover:bg-red-50 text-stone-400 hover:text-red-600 rounded-lg transition-colors">
                            <LogOut className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-4 py-6">

                {/* Controls */}
                <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                     <h2 className="text-2xl font-bold font-heading text-stone-800">Rozvrh Studia</h2>

                     <div className="flex items-center gap-4 bg-white p-1.5 rounded-xl shadow-sm border border-stone-200">
                        <button onClick={() => changeWeek(-1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600"><ChevronLeft className="w-5 h-5" /></button>
                        <div className="flex items-center gap-2 px-2 font-medium text-stone-800 min-w-[140px] justify-center">
                            <Calendar className="w-4 h-4 text-sage-600" />
                            <span>{weekDays[0].getDate()}.{weekDays[0].getMonth()+1}. – {weekDays[4].getDate()}.{weekDays[4].getMonth()+1}.</span>
                        </div>
                        <button onClick={() => changeWeek(1)} className="p-2 hover:bg-stone-100 rounded-lg text-stone-600"><ChevronRight className="w-5 h-5" /></button>
                     </div>
                </div>

                {/* --- THE CALENDAR GRID --- */}
                <div className="bg-white rounded-2xl shadow-sm border border-stone-200 overflow-hidden">

                    {/* Header Row (Days) */}
                    <div className="grid grid-cols-[60px_1fr_1fr_1fr_1fr_1fr] border-b border-stone-200">
                         <div className="p-4 bg-stone-50/50 border-r border-stone-100"></div> {/* Time Corner */}
                         {weekDays.map(d => (
                             <div key={d.toISOString()} className="text-center border-r border-stone-100 last:border-0 flex flex-col h-full">
                                 {/* Top part: Date */}
                                 <div className="p-2 border-b border-stone-100/50 bg-white">
                                     <div className="text-xs uppercase font-bold text-stone-400 mb-0.5">{DAYS_MAP[d.getDay()]}</div>
                                     <div className={`font-bold text-lg ${d.toDateString() === new Date().toDateString() ? 'text-sage-700' : 'text-stone-800'}`}>
                                         {d.getDate()}
                                     </div>
                                 </div>
                                 {/* Bottom part: Room Columns Headers */}
                                 <div className="flex flex-1 text-[10px] font-bold uppercase tracking-wider text-stone-500">
                                     <div className="flex-1 py-1 bg-stone-50 border-r border-stone-100 flex items-center justify-center gap-1">
                                         <span className="w-2 h-2 rounded-full bg-stone-300"></span> M1 <span className="hidden xl:inline">(Malá)</span>
                                     </div>
                                     <div className="flex-1 py-1 bg-indigo-50/30 flex items-center justify-center gap-1">
                                         <span className="w-2 h-2 rounded-full bg-indigo-200"></span> M2 <span className="hidden xl:inline">(Velká)</span>
                                     </div>
                                 </div>
                             </div>
                         ))}
                    </div>

                    {/* Time Rows */}
                    <div className="relative">
                        {GENERATED_TIMES.map((time, tIdx) => (
                            <div key={time} className="grid grid-cols-[60px_1fr_1fr_1fr_1fr_1fr] min-h-[50px] border-b border-stone-100 last:border-0 group">
                                {/* Time Column */}
                                <div className="py-2 px-1 text-center text-xs font-medium text-stone-400 border-r border-stone-100 flex items-start justify-center pt-3 bg-stone-50/30">
                                    {time}
                                </div>

                                {/* Day Columns */}
                                {weekDays.map((date, dIdx) => {
                                    const r1 = getSlotStatus(date, time, 1);
                                    const r2 = getSlotStatus(date, time, 2);

                                    const renderSubSlot = (roomNum: 1|2, data: typeof r1) => {
                                        let bgClass = roomNum === 1 ? "bg-white hover:bg-stone-50" : "bg-indigo-50/10 hover:bg-indigo-50";
                                        let content = null;

                                        if (data.status === 'past') {
                                            bgClass = "bg-stone-100/60 cursor-not-allowed";
                                            // Optional: visual indicator for past
                                            // content = <span className="text-stone-300">●</span>;
                                        } else if (data.status === 'mine') {
                                            bgClass = "bg-emerald-500 hover:bg-emerald-600 text-white shadow-sm";
                                            content = <span className="text-[10px] font-bold">MOJE</span>;
                                        } else if (data.status === 'occupied') {
                                            bgClass = "bg-stone-200 cursor-not-allowed";
                                            content = <span className="text-[9px] font-bold text-stone-500 truncate px-1">{data.booking?.bookedByName}</span>;
                                        } else if (data.status === 'cleaning') {
                                            bgClass = "bg-amber-100 cursor-not-allowed repeating-linear-gradient-45";
                                        }

                                        return (
                                            <div 
                                                onClick={() => handleSlotClick(date, time, roomNum, data)}
                                                className={`flex-1 flex items-center justify-center transition-all cursor-pointer relative ${bgClass} ${roomNum === 1 ? 'border-r border-stone-200' : ''}`}
                                            >
                                                {content}
                                                {/* Hover Hint for Free Slots */}
                                                {data.status === 'free' && (
                                                    <div className="opacity-0 hover:opacity-100 absolute inset-0 flex items-center justify-center bg-sage-100/50 text-sage-700 font-bold text-xs">
                                                        +
                                                    </div>
                                                )}
                                            </div>
                                        );
                                    };

                                    return (
                                        <div key={`${date}-${time}`} className="border-r border-stone-100 last:border-0 flex">
                                            {/* Room 1 Column */}
                                            {renderSubSlot(1, r1)}
                                            {/* Room 2 Column */}
                                            {renderSubSlot(2, r2)}
                                        </div>
                                    );
                                })}
                            </div>
                        ))}
                    </div>
                </div>

                <div className="mt-6 flex gap-4 text-xs text-stone-400 justify-center">
                    <span className="flex items-center gap-2"><span className="w-3 h-3 bg-stone-50 border border-stone-200"></span> Místnost 1 (Malá)</span>
                    <span className="text-stone-300">|</span>
                    <span className="flex items-center gap-2"><span className="w-3 h-3 bg-indigo-50 border border-indigo-100"></span> Místnost 2 (Velká)</span>
                    <span className="ml-4 text-amber-600 font-bold">* Úklid: 30 min (stejný lektor) / 60 min (výměna)</span>
                    <span className="ml-4 text-red-400 font-bold">* Storno: min. 24h předem</span>
                </div>

            </div>

            {/* Booking Modal */}
            {selectedSlot && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in">
                    <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col max-h-[90vh]">
                        <div className="bg-stone-900 text-white p-6 relative flex-shrink-0">
                            <h3 className="text-xl font-bold font-heading">Nová Rezervace</h3>
                            <div className="flex items-center gap-4 text-stone-400 text-sm mt-2">
                                <span className="flex items-center gap-1"><Calendar className="w-3 h-3" /> {new Date(selectedSlot.date).toLocaleDateString('cs-CZ')}</span>
                                <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {selectedSlot.time}</span>
                            </div>
                            <button onClick={() => setSelectedSlot(null)} className="absolute top-4 right-4 p-2 bg-white/10 rounded-full hover:bg-white/20"><X className="w-4 h-4" /></button>
                        </div>

                        <div className="p-6 space-y-6 overflow-y-auto">
                            {/* Room Info */}
                            <div className="flex gap-4">
                                <div className={`flex-1 p-3 rounded-xl border-2 text-center ${selectedSlot.room === 1 ? 'border-sage-500 bg-sage-50 text-sage-800' : 'border-stone-100 text-stone-400 bg-stone-50 opacity-50'}`}>
                                    <div className="text-xs font-bold uppercase mb-1">Místnost 1</div>
                                    <div className="font-bold">Malá Terapeutovna</div>
                                    <div className="text-xs mt-1">300 Kč/h</div>
                                </div>
                                <div className={`flex-1 p-3 rounded-xl border-2 text-center ${selectedSlot.room === 2 ? 'border-sage-500 bg-sage-50 text-sage-800' : 'border-stone-100 text-stone-400 bg-stone-50 opacity-50'}`}>
                                    <div className="text-xs font-bold uppercase mb-1">Místnost 2</div>
                                    <div className="font-bold">Velký Sál</div>
                                    <div className="text-xs mt-1">500 Kč/h</div>
                                </div>
                            </div>

                            {/* Equipment Selection - NEW */}
                            <div>
                                <label className="block text-sm font-bold text-stone-700 mb-2">Jaké vybavení potřebujete?</label>
                                <div className="grid grid-cols-2 gap-3">
                                    <button
                                        onClick={() => setEquipment('table')}
                                        className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${
                                            equipment === 'table' 
                                            ? 'border-sage-600 bg-sage-50 text-sage-900 shadow-sm' 
                                            : 'border-stone-200 text-stone-500 hover:border-sage-200 hover:bg-stone-50'
                                        }`}
                                    >
                                        <Bed className="w-6 h-6" />
                                        <span className="font-bold text-sm">Lehátko (Stůl)</span>
                                    </button>
                                    <button
                                        onClick={() => setEquipment('futon')}
                                        className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${
                                            equipment === 'futon' 
                                            ? 'border-sage-600 bg-sage-50 text-sage-900 shadow-sm' 
                                            : 'border-stone-200 text-stone-500 hover:border-sage-200 hover:bg-stone-50'
                                        }`}
                                    >
                                        <Layers className="w-6 h-6" />
                                        <span className="font-bold text-sm">Futon (Země)</span>
                                    </button>
                                </div>
                            </div>

                            {/* Duration Slider/Select */}
                            <div>
                                <label className="block text-sm font-bold text-stone-700 mb-2">Délka rezervace</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {[60, 90, 120, 150, 180, 210, 240, 270, 300].map(m => (
                                        <button
                                            key={m}
                                            onClick={() => setDuration(m)}
                                            className={`py-2 rounded-lg text-sm font-bold transition-all ${duration === m ? 'bg-stone-800 text-white' : 'bg-stone-100 text-stone-600 hover:bg-stone-200'}`}
                                        >
                                            {m} min
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Client Note (Optional) */}
                            <div>
                                <label className="block text-sm font-bold text-stone-700 mb-1">Klient / Poznámka (Volitelné)</label>
                                <input 
                                    type="text" 
                                    className="w-full p-3 bg-white border border-stone-200 rounded-xl text-stone-900 placeholder-stone-400 focus:ring-2 focus:ring-sage-500 outline-none"
                                    placeholder="Jméno klienta pro vaši orientaci..."
                                    value={clientName}
                                    onChange={e => setClientName(e.target.value)}
                                />
                            </div>

                            {/* Summary & Action */}
                            <div className="bg-stone-50 p-4 rounded-xl flex justify-between items-center border border-stone-100 mt-auto">
                                <div>
                                    <div className="text-xs font-bold text-stone-500 uppercase">Cena celkem</div>
                                    <div className="text-xl font-bold text-stone-900">
                                        {((duration/60) * (selectedSlot.room === 1 ? RENTAL_PRICING.room1 : RENTAL_PRICING.room2)).toFixed(0)} Kč
                                    </div>
                                </div>
                                <Button 
                                    onClick={handleConfirmBooking} 
                                    disabled={isProcessing}
                                    className="bg-black text-white hover:bg-stone-800 px-6"
                                >
                                    {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Potvrdit a Zaplatit'}
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

        </div>
    );
};

// Simple Close Icon Helper
const X = ({ className }: { className?: string }) => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M18 6 6 18"/><path d="m6 6 18 18"/></svg>
);

export default StudioSchedule;

import React, { useState, useMemo, useEffect } from 'react';
import { Booking, Practitioner } from '../types';
import { GENERATED_TIMES, BUFFER_SAME_USER, BUFFER_DIFF_USER, RENTAL_PRICING } from '../constants';
import Button from '../components/Button';
import { Calendar, ChevronLeft, ChevronRight, Clock, User, Check, AlertCircle, Info, Lock, Zap, LogOut, Loader2, Bed, Layers, Sparkles, History, Monitor, Smartphone } from 'lucide-react';

interface StudioScheduleProps {
  currentUser: Practitioner;
  allBookings: Booking[];
  onBook: (bookingData: Partial<Booking>) => Promise<void>;
  onCancel: (bookingId: string) => void;
  onLogout: () => void;
}

const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];

// Helper: Convert time "14:30" -> minutes 870
const timeToMinutes = (time: string): number => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

// Helper: Convert minutes -> time string "14:30"
const minutesToTime = (minutes: number): string => {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
};

const StudioSchedule: React.FC<StudioScheduleProps> = ({ 
    currentUser, 
    allBookings, 
    onBook, 
    onCancel,
    onLogout
}) => {
    // View State
    const [viewMode, setViewMode] = useState<'day' | 'week'>('week');
    const [currentDate, setCurrentDate] = useState(new Date()); // Tracks the start date (Monday for week, or specific day for day view)

    // Check screen size on mount and resize
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) {
                setViewMode('day');
            } else {
                setViewMode('week');
            }
        };

        // Initial check
        handleResize();

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const [selectedSlot, setSelectedSlot] = useState<{date: string, time: string, room: 1 | 2} | null>(null);

    // Booking Form State
    const [duration, setDuration] = useState<number>(60);
    const [clientName, setClientName] = useState('');
    const [equipment, setEquipment] = useState<'table' | 'futon'>('table'); 
    const [isProcessing, setIsProcessing] = useState(false);

    // --- CALENDAR LOGIC ---

    const handleNavigate = (offset: number) => {
        const newDate = new Date(currentDate);
        if (viewMode === 'day') {
            // Move by 1 day
            // Skip weekends if desired, but let's keep it simple for now (allow all days or skip Sat/Sun)
            // Let's verify if we want to skip weekends in day view? 
            // The week view logic enforced Mon-Fri. Let's try to stick to Mon-Fri for consistency, or allow Sat/Sun in Day view.
            // For this logic, let's just do simple day add, but if it lands on Sat/Sun, maybe user wants that? 
            // The original logic only showed 5 days. Let's allow full navigation in Day mode, but maybe skip Sat/Sun in Week mode logic.

            let daysToAdd = offset;
            newDate.setDate(newDate.getDate() + daysToAdd);

            // Optional: Skip weekend in day view if strict B2B
            const day = newDate.getDay();
            if (day === 0) newDate.setDate(newDate.getDate() + (offset > 0 ? 1 : -2)); // Skip Sun -> Mon or Fri
            if (day === 6) newDate.setDate(newDate.getDate() + (offset > 0 ? 2 : -1)); // Skip Sat -> Mon or Fri

        } else {
            // Move by 1 week
            newDate.setDate(newDate.getDate() + (offset * 7));
        }
        setCurrentDate(newDate);
    };

    // Generate days to display based on View Mode
    const visibleDays = useMemo(() => {
        if (viewMode === 'day') {
            return [new Date(currentDate)];
        } else {
            // Week View: Always calculate Monday of the current week
            return Array.from({ length: 5 }, (_, i) => {
                const d = new Date(currentDate);
                const day = d.getDay();
                // If current date is Sat(6) or Sun(0), logic needs to find previous Monday
                // Standard normalize to Monday:
                const diff = d.getDate() - day + (day === 0 ? -6 : 1);
                d.setDate(diff + i);
                return d;
            });
        }
    }, [currentDate, viewMode]);

    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    // Determine status of a specific slot (Free, Mine, Occupied, Cleaning, Past)
    const getSlotStatus = (date: Date, time: string, room: 1 | 2) => {
        const dateStr = formatDate(date);
        const slotStart = timeToMinutes(time);
        const slotEnd = slotStart + 30; // Visual slot size

        // 1. PAST CHECK Logic
        const now = new Date();
        const slotDateTime = new Date(`${dateStr}T${time}`);
        // Add minimal buffer (e.g. current minute) so we can't book this exact minute if it just passed
        if (slotDateTime < now) {
             // We still want to show bookings in the past, but mark empty slots as 'past'
        }

        // Check against existing bookings
        const overlap = allBookings.find(b => {
            if (b.date !== dateStr || b.status !== 'confirmed' || b.room !== room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            // DYNAMIC BUFFER CALCULATION
            const bufferDuration = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferDuration;

            const isBooking = (slotStart < bEnd && slotEnd > bStart);
            const isBuffer = (slotStart < bBufferEnd && slotEnd > bEnd);

            return isBooking || isBuffer;
        });

        if (!overlap) {
            // If no booking overlap, check if it's in the past
            if (slotDateTime < now) {
                return { status: 'past' as const };
            }
            return { status: 'free' as const };
        }

        const bStart = timeToMinutes(overlap.time);
        const bEnd = bStart + overlap.durationMinutes;

        // Distinguish actual booking vs buffer
        const isBuffer = slotStart >= bEnd; 

        const isMine = overlap.bookedByUserId === currentUser.id;

        return {
            status: isBuffer ? 'cleaning' as const : (isMine ? 'mine' as const : 'occupied' as const),
            booking: overlap,
            bufferUsed: (overlap.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER
        };
    };

    // --- HANDLERS ---

    const handleSlotClick = (date: Date, time: string, room: 1 | 2, statusData: ReturnType<typeof getSlotStatus>) => {
        if (statusData.status === 'past') return;

        if (statusData.status === 'free') {
            // Open Booking Modal
            setSelectedSlot({
                date: formatDate(date),
                time,
                room
            });
            setDuration(60);
            setClientName('');
            setEquipment('table'); // Default
        } else if (statusData.status === 'mine' && statusData.booking) {
            // 2. CANCELLATION POLICY CHECK
            const bookingStart = new Date(`${statusData.booking.date}T${statusData.booking.time}`);
            const now = new Date();
            const hoursDifference = (bookingStart.getTime() - now.getTime()) / (1000 * 60 * 60);

            if (hoursDifference < 24) {
                alert("Rezervaci nelze zrušit méně než 24 hodin předem.\n\nPro storno prosím kontaktujte manažera studia.");
                return;
            }

            if (window.confirm(`Chcete zrušit svou rezervaci?\n\n${statusData.booking.date} v ${statusData.booking.time}\n(Zbývá ${Math.floor(hoursDifference)}h do začátku)`)) {
                onCancel(statusData.booking.id);
            }
        }
    };

    const handleConfirmBooking = async () => {
        if (!selectedSlot) return;

        // Check for collisions with new duration
        const newStart = timeToMinutes(selectedSlot.time);
        const newEnd = newStart + duration;

        // 1. Check if USER is already booked in ANY room at this time (Bilocation check)
        const isUserDoubleBooked = allBookings.some(b => {
             if (b.bookedByUserId !== currentUser.id) return false; // Check only my bookings
             if (b.date !== selectedSlot.date || b.status !== 'confirmed') return false;

             const bStart = timeToMinutes(b.time);
             const bEnd = bStart + b.durationMinutes;

             return (newStart < bEnd && newEnd > bStart);
        });

        if (isUserDoubleBooked) {
             alert("Nelze rezervovat: V tomto čase již máte rezervaci v jiné místnosti. Nemůžete být na dvou místech najednou.");
             return;
        }

        // 2. Determine collision with OTHER bookings in the SAME room
        const hasCollision = allBookings.some(b => {
            if (b.date !== selectedSlot.date || b.status !== 'confirmed' || b.room !== selectedSlot.room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            // COLLISION LOGIC A: OVERLAP WITH BOOKING ITSELF
            if (newStart < bEnd && newEnd > bStart) return true;

            // COLLISION LOGIC B: BUFFER AFTER EXISTING BOOKING (THEY BLOCK ME)
            const bufferAfterThem = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferAfterThem;
            if (newStart < bBufferEnd && newStart >= bEnd) return true;

            // COLLISION LOGIC C: BUFFER AFTER MY NEW BOOKING (I BLOCK THEM)
            const bufferAfterMe = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const myBufferEnd = newEnd + bufferAfterMe;
            if (newEnd <= bStart && myBufferEnd > bStart) return true;

            return false;
        });

        if (hasCollision) {
            alert("Nelze rezervovat: Zvolený čas koliduje s jinou rezervací nebo povinným úklidem (60 min pro různé lektory, 30 min pro stejného).");
            return;
        }

        setIsProcessing(true);

        // Calculate Price
        const priceRate = selectedSlot.room === 1 ? RENTAL_PRICING.room1 : RENTAL_PRICING.room2;
        const finalPrice = (duration / 60) * priceRate;

        await onBook({
            bookedByUserId: currentUser.id,
            bookedByName: currentUser.name,
            date: selectedSlot.date,
            time: selectedSlot.time,
            durationMinutes: duration,
            room: selectedSlot.room,
            price: finalPrice,
            paymentStatus: 'unpaid', // In real app, redirect to gateway
            clientName: clientName,
            equipment: equipment 
        });

        setIsProcessing(false);
        setSelectedSlot(null);
    };

    return (
        <div className="min-h-screen bg-stone-50 pb-20">
            {/* Header / Navbar */}
            <div className="bg-white border-b border-stone-200 sticky top-0 z-30 shadow-sm">
                <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                         <div className="w-10 h-10 rounded-full overflow-hidden border border-stone-200">
                             <img src={currentUser.imageUrl} alt="Profile" className="w-full h-full object-cover" />
                         </div>
                         <div>
                             <h1 className="font-bold text-stone-900 leading-tight truncate max-w-[120px] md:max-w-none">{currentUser.name}</h1>
                             <div className="text-xs text-stone-500 font-medium">Kredit: 1200 Kč</div>
                         </div>
                    </div>

                    <div className="flex items-center gap-4">
                        <div className="hidden md:flex items-center gap-6 mr-6 text-sm font-medium text-stone-500">
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-white border border-stone-300 rounded-sm"></div> Volno</div>
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-stone-100 rounded-sm"></div> Uplynulé</div>
                             <div className="flex items-center gap-2"><div className="w-3 h-3 bg-emerald-500 rounded-sm"></div> Moje</div>
                        </div>
                        <button onClick={onLogout} className="p-2 hover:bg-red-50 text-stone-400 hover:text-red-600 rounded-lg transition-colors">
                            <LogOut className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-2 md:px-4 py-6">

                {/* Controls */}
                <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                     <div className="flex items-center justify-between w-full md:w-auto gap-4">
                        <h2 className="text-2xl font-bold font-heading text-stone-800">Rozvrh</h2>
                        {/* View Toggle for Desktop/Mobile testing manually */}
                        <div className="flex bg-stone-200 rounded-lg p-1 md:hidden">
                            <button 
                                onClick={() => setViewMode('day')} 
                                className={`p-1.5 rounded-md transition-all ${viewMode === 'day' ? 'bg-white shadow-sm text-stone-900' : 'text-stone-500'}`}
                            >
                                <Smartphone className="w-4 h-4" />
                            </button>
                            <button 
                                onClick={() => setViewMode('week')} 
                                className={`p-1.5 rounded-md transition-all ${viewMode === 'week' ? 'bg-white shadow-sm text-stone-900' : 'text-stone-500'}`}
                            >
                                <Monitor className="w-4 h-4" />
                            </button>
                        </div>
                     </div>

                     <div className="flex items-center gap-2 md:gap-4 bg-white p-1.5 rounded-xl shadow-sm border border-stone-200 w-full md:w-auto justify-between md:justify-start">
                        <button onClick={() => handleNavigate(-1)} className="p-3 md:p-2 hover:bg-stone-100 rounded-lg text-stone-600 active:scale-95 transition-transform"><ChevronLeft className="w-5 h-5" /></button>
                        <div className="flex items-center gap-2 px-2 font-medium text-stone-800">
                            <Calendar className="w-4 h-4 text-sage-600 hidden md:block" />
                            {viewMode === 'day' ? (
                                <span className="text-sm font-bold capitalize">
                                    {visibleDays[0].toLocaleDateString('cs-CZ', { weekday: 'long', day: 'numeric', month: 'long' })}
                                </span>
                            ) : (
                                <span className="text-sm">
                                    {visibleDays[0].getDate()}.{visibleDays[0].getMonth()+1}. – {visibleDays[4].getDate()}.{visibleDays[4].getMonth()+1}.
                                </span>
                            )}
                        </div>
                        <button onClick={() => handleNavigate(1)} className="p-3 md:p-2 hover:bg-stone-100 rounded-lg text-stone-600 active:scale-95 transition-transform"><ChevronRight className="w-5 h-5" /></button>
                     </div>
                </div>

                {/* --- THE CALENDAR GRID --- */}
                <div className="bg-white rounded-2xl shadow-sm border border-stone-200 overflow-hidden">

                    {/* Header Row (Days) */}
                    <div 
                        className="grid border-b border-stone-200"
                        style={{ gridTemplateColumns: viewMode === 'day' ? '60px 1fr' : '60px 1fr 1fr 1fr 1fr 1fr' }}
                    >
                         <div className="p-4 bg-stone-50/50 border-r border-stone-100"></div> {/* Time Corner */}
                         {visibleDays.map(d => (
                             <div key={d.toISOString()} className="text-center border-r border-stone-100 last:border-0 flex flex-col h-full animate-in fade-in">
                                 {/* Top part: Date */}
                                 <div className="p-2 border-b border-stone-100/50 bg-white">
                                     <div className="text-xs uppercase font-bold text-stone-400 mb-0.5">{DAYS_MAP[d.getDay()]}</div>
                                     <div className={`font-bold text-lg ${d.toDateString() === new Date().toDateString() ? 'text-sage-700' : 'text-stone-800'}`}>
                                         {d.getDate()}
                                     </div>
                                 </div>
                                 {/* Bottom part: Room Columns Headers */}
                                 <div className="flex flex-1 text-[10px] font-bold uppercase tracking-wider text-stone-500">
                                     <div className="flex-1 py-1 bg-stone-50 border-r border-stone-100 flex items-center justify-center gap-1">
                                         <span className="w-2 h-2 rounded-full bg-stone-300"></span> M1 <span className={`${viewMode === 'week' ? 'hidden xl:inline' : ''}`}>(Malá)</span>
                                     </div>
                                     <div className="flex-1 py-1 bg-indigo-50/30 flex items-center justify-center gap-1">
