                                    };

                                    return (
                                        <div key={`${date}-${time}`} className="border-r border-stone-100 last:border-0 flex">
                                            {/* Room 1 Column */}
                                            {renderSubSlot(1, r1)}
                                            {/* Room 2 Column */}
                                            {renderSubSlot(2, r2)}
                                        </div>
                                    );
                                })}
                            </div>
                        ))}
                    </div>
