                        <span className="text-red-400 font-bold">* Storno: min. 24h předem</span>
                    </div>
                </div>

            </div>

            {/* Booking Modal */}
            {selectedSlot && (
                <div className="fixed inset-0 z-50 flex items-end md:items-center justify-center p-0 md:p-4 bg-black/50 backdrop-blur-sm animate-in fade-in">
                    <div className="bg-white w-full md:max-w-md rounded-t-2xl md:rounded-2xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-10 md:zoom-in-95 flex flex-col max-h-[90vh]">
                        <div className="bg-stone-900 text-white p-6 relative flex-shrink-0">
                            <h3 className="text-xl font-bold font-heading">Nová Rezervace</h3>
                            <div className="flex items-center gap-4 text-stone-400 text-sm mt-2">
                                <span className="flex items-center gap-1"><Calendar className="w-3 h-3" /> {new Date(selectedSlot.date).toLocaleDateString('cs-CZ')}</span>
                                <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {selectedSlot.time}</span>
                            </div>
                            <button onClick={() => setSelectedSlot(null)} className="absolute top-4 right-4 p-2 bg-white/10 rounded-full hover:bg-white/20"><X className="w-4 h-4" /></button>
                        </div>

                        <div className="p-6 space-y-6 overflow-y-auto">
                            {/* Room Info */}
                            <div className="flex gap-4">
                                <div className={`flex-1 p-3 rounded-xl border-2 text-center ${selectedSlot.room === 1 ? 'border-sage-500 bg-sage-50 text-sage-800' : 'border-stone-100 text-stone-400 bg-stone-50 opacity-50'}`}>
                                    <div className="text-xs font-bold uppercase mb-1">Místnost 1</div>
                                    <div className="font-bold text-sm md:text-base">Malá Terapeutovna</div>
                                    <div className="text-xs mt-1">300 Kč/h</div>
                                </div>
                                <div className={`flex-1 p-3 rounded-xl border-2 text-center ${selectedSlot.room === 2 ? 'border-sage-500 bg-sage-50 text-sage-800' : 'border-stone-100 text-stone-400 bg-stone-50 opacity-50'}`}>
                                    <div className="text-xs font-bold uppercase mb-1">Místnost 2</div>
                                    <div className="font-bold text-sm md:text-base">Velký Sál</div>
                                    <div className="text-xs mt-1">500 Kč/h</div>
                                </div>
                            </div>

                            {/* Equipment Selection - NEW */}
                            <div>
                                <label className="block text-sm font-bold text-stone-700 mb-2">Jaké vybavení potřebujete?</label>
                                <div className="grid grid-cols-2 gap-3">
                                    <button
                                        onClick={() => setEquipment('table')}
                                        className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${
                                            equipment === 'table' 
                                            ? 'border-sage-600 bg-sage-50 text-sage-900 shadow-sm' 
                                            : 'border-stone-200 text-stone-500 hover:border-sage-200 hover:bg-stone-50'
                                        }`}
                                    >
                                        <Bed className="w-6 h-6" />
                                        <span className="font-bold text-sm">Lehátko (Stůl)</span>
                                    </button>
                                    <button
                                        onClick={() => setEquipment('futon')}
                                        className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${
                                            equipment === 'futon' 
                                            ? 'border-sage-600 bg-sage-50 text-sage-900 shadow-sm' 
                                            : 'border-stone-200 text-stone-500 hover:border-sage-200 hover:bg-stone-50'
                                        }`}
                                    >
                                        <Layers className="w-6 h-6" />
                                        <span className="font-bold text-sm">Futon (Země)</span>
                                    </button>
                                </div>
                            </div>

                            {/* Duration Slider/Select */}
                            <div>
                                <label className="block text-sm font-bold text-stone-700 mb-2">Délka rezervace</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {[60, 90, 120, 150, 180, 210, 240, 270, 300].map(m => (
                                        <button
                                            key={m}
                                            onClick={() => setDuration(m)}
                                            className={`py-2 rounded-lg text-sm font-bold transition-all ${duration === m ? 'bg-stone-800 text-white' : 'bg-stone-100 text-stone-600 hover:bg-stone-200'}`}
                                        >
                                            {m} min
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Client Note (Optional) */}
                            <div>
                                <label className="block text-sm font-bold text-stone-700 mb-1">Klient / Poznámka (Volitelné)</label>
                                <input 
                                    type="text" 
                                    className="w-full p-3 bg-white border border-stone-200 rounded-xl text-stone-900 placeholder-stone-400 focus:ring-2 focus:ring-sage-500 outline-none"
                                    placeholder="Jméno klienta pro vaši orientaci..."
                                    value={clientName}
                                    onChange={e => setClientName(e.target.value)}
                                />
                            </div>

                            {/* Summary & Action */}
                            <div className="bg-stone-50 p-4 rounded-xl flex flex-col md:flex-row gap-4 md:justify-between md:items-center border border-stone-100 mt-auto">
                                <div>
                                    <div className="text-xs font-bold text-stone-500 uppercase">Cena celkem</div>
                                    <div className="text-xl font-bold text-stone-900">
                                        {((duration/60) * (selectedSlot.room === 1 ? RENTAL_PRICING.room1 : RENTAL_PRICING.room2)).toFixed(0)} Kč
                                    </div>
                                </div>
                                <Button 
                                    onClick={handleConfirmBooking} 
                                    disabled={isProcessing}
                                    className="bg-black text-white hover:bg-stone-800 px-6 w-full md:w-auto"
                                >
                                    {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Potvrdit a Zaplatit'}
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

        </div>
    );
};

// Simple Close Icon Helper
const X = ({ className }: { className?: string }) => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M18 6 6 18"/><path d="m6 6 18 18"/></svg>
);

export default StudioSchedule;

import React, { useState, useMemo, useEffect } from 'react';
import { Booking, Practitioner } from '../types';
import { GENERATED_TIMES, BUFFER_SAME_USER, BUFFER_DIFF_USER, RENTAL_PRICING } from '../constants';
import Button from '../components/Button';
import { Calendar, ChevronLeft, ChevronRight, Clock, User, Check, AlertCircle, Info, Lock, Zap, LogOut, Loader2, Bed, Layers, Sparkles, History, Monitor, Smartphone, Mail, Phone } from 'lucide-react';

interface StudioScheduleProps {
  currentUser: Practitioner;
  allBookings: Booking[];
  onBook: (bookingData: Partial<Booking>) => Promise<void>;
  onCancel: (bookingId: string) => void;
  onLogout: () => void;
}

const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];

// Helper: Convert time "14:30" -> minutes 870
const timeToMinutes = (time: string): number => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

// Helper: Convert minutes -> time string "14:30"
const minutesToTime = (minutes: number): string => {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
};

const StudioSchedule: React.FC<StudioScheduleProps> = ({ 
    currentUser, 
    allBookings, 
    onBook, 
    onCancel,
    onLogout
}) => {
    // View State
    const [viewMode, setViewMode] = useState<'day' | 'week'>('week');
    const [currentDate, setCurrentDate] = useState(new Date()); 

    // Check screen size on mount and resize
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) {
                setViewMode('day');
            } else {
                setViewMode('week');
            }
        };
        handleResize();
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const [selectedSlot, setSelectedSlot] = useState<{date: string, time: string, room: 1 | 2} | null>(null);

    // Booking Form State
    const [duration, setDuration] = useState<number>(60);
    const [clientName, setClientName] = useState(''); // This is "End Client" for regulars, but unused/optional for guests
    const [equipment, setEquipment] = useState<'table' | 'futon'>('table'); 
    const [isProcessing, setIsProcessing] = useState(false);

    // GUEST SPECIFIC STATE
    const [guestName, setGuestName] = useState('');
    const [guestEmail, setGuestEmail] = useState('');
    const [guestPhone, setGuestPhone] = useState('');

    const isGuest = currentUser.id === 'guest';

    // Reset fields when modal opens/closes
    useEffect(() => {
        if (selectedSlot) {
            setDuration(60);
            setClientName('');
            setEquipment('table');
            setGuestName('');
            setGuestEmail('');
            setGuestPhone('');
        }
    }, [selectedSlot]);

    // --- CALENDAR LOGIC ---

    const handleNavigate = (offset: number) => {
        const newDate = new Date(currentDate);
        if (viewMode === 'day') {
            let daysToAdd = offset;
            newDate.setDate(newDate.getDate() + daysToAdd);

            // Optional: Skip weekend logic if needed
            const day = newDate.getDay();
            if (day === 0) newDate.setDate(newDate.getDate() + (offset > 0 ? 1 : -2)); 
            if (day === 6) newDate.setDate(newDate.getDate() + (offset > 0 ? 2 : -1)); 

        } else {
            newDate.setDate(newDate.getDate() + (offset * 7));
        }
        setCurrentDate(newDate);
    };

    const visibleDays = useMemo(() => {
        if (viewMode === 'day') {
            return [new Date(currentDate)];
        } else {
            return Array.from({ length: 5 }, (_, i) => {
                const d = new Date(currentDate);
                const day = d.getDay();
                const diff = d.getDate() - day + (day === 0 ? -6 : 1);
                d.setDate(diff + i);
                return d;
            });
        }
    }, [currentDate, viewMode]);

    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    const getSlotStatus = (date: Date, time: string, room: 1 | 2) => {
        const dateStr = formatDate(date);
        const slotStart = timeToMinutes(time);
        const slotEnd = slotStart + 30; 

        const now = new Date();
        const slotDateTime = new Date(`${dateStr}T${time}`);

        // Past check logic...

        const overlap = allBookings.find(b => {
            if (b.date !== dateStr || b.status !== 'confirmed' || b.room !== room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            const bufferDuration = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferDuration;

            const isBooking = (slotStart < bEnd && slotEnd > bStart);
            const isBuffer = (slotStart < bBufferEnd && slotEnd > bEnd);

            return isBooking || isBuffer;
        });

        if (!overlap) {
            if (slotDateTime < now) return { status: 'past' as const };
            return { status: 'free' as const };
        }

        const bStart = timeToMinutes(overlap.time);
        const bEnd = bStart + overlap.durationMinutes;
        const isBuffer = slotStart >= bEnd; 
        const isMine = overlap.bookedByUserId === currentUser.id;

        return {
            status: isBuffer ? 'cleaning' as const : (isMine ? 'mine' as const : 'occupied' as const),
            booking: overlap,
            bufferUsed: (overlap.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER
        };
    };

    // --- HANDLERS ---

    const handleSlotClick = (date: Date, time: string, room: 1 | 2, statusData: ReturnType<typeof getSlotStatus>) => {
        if (statusData.status === 'past') return;

        if (statusData.status === 'free') {
            setSelectedSlot({
                date: formatDate(date),
                time,
                room
            });
        } else if (statusData.status === 'mine' && statusData.booking) {
            const bookingStart = new Date(`${statusData.booking.date}T${statusData.booking.time}`);
            const now = new Date();
            const hoursDifference = (bookingStart.getTime() - now.getTime()) / (1000 * 60 * 60);

            if (hoursDifference < 24) {
                alert("Rezervaci nelze zrušit méně než 24 hodin předem.\n\nPro storno prosím kontaktujte manažera studia.");
                return;
            }

            if (window.confirm(`Chcete zrušit svou rezervaci?\n\n${statusData.booking.date} v ${statusData.booking.time}\n(Zbývá ${Math.floor(hoursDifference)}h do začátku)`)) {
                onCancel(statusData.booking.id);
            }
        }
    };

    const handleConfirmBooking = async () => {
        if (!selectedSlot) return;

        // Validation for Guest
        if (isGuest) {
            if (!guestName.trim() || !guestEmail.trim() || !guestPhone.trim()) {
                alert("Jako host musíte vyplnit jméno, email a telefon pro zaslání platebních údajů.");
                return;
            }
        }

        const newStart = timeToMinutes(selectedSlot.time);
        const newEnd = newStart + duration;

        const isUserDoubleBooked = allBookings.some(b => {
             // For guests, we don't strictly check ID collision since 'guest' ID is shared,
             // BUT we might want to check name collision? 
             // For simplicity, guests can double book (different people), 
             // regular users cannot.
             if (!isGuest && b.bookedByUserId !== currentUser.id) return false; 
             if (isGuest) return false; // Allow multiple 'guests' to book different rooms at same time

             if (b.date !== selectedSlot.date || b.status !== 'confirmed') return false;

             const bStart = timeToMinutes(b.time);
             const bEnd = bStart + b.durationMinutes;

             return (newStart < bEnd && newEnd > bStart);
        });

        if (isUserDoubleBooked) {
             alert("Nelze rezervovat: V tomto čase již máte rezervaci.");
             return;
        }

        const hasCollision = allBookings.some(b => {
            if (b.date !== selectedSlot.date || b.status !== 'confirmed' || b.room !== selectedSlot.room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            if (newStart < bEnd && newEnd > bStart) return true;

            const bufferAfterThem = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferAfterThem;
            if (newStart < bBufferEnd && newStart >= bEnd) return true;

            const bufferAfterMe = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const myBufferEnd = newEnd + bufferAfterMe;
            if (newEnd <= bStart && myBufferEnd > bStart) return true;

            return false;
        });

        if (hasCollision) {
            alert("Nelze rezervovat: Kolize s jinou rezervací nebo úklidem.");
            return;
        }

        setIsProcessing(true);

        const priceRate = selectedSlot.room === 1 ? RENTAL_PRICING.room1 : RENTAL_PRICING.room2;
        const finalPrice = (duration / 60) * priceRate;

        await onBook({
            bookedByUserId: currentUser.id,
            // If guest, use the input name. If regular, use profile name.
            bookedByName: isGuest ? guestName : currentUser.name,
            date: selectedSlot.date,
            time: selectedSlot.time,
            durationMinutes: duration,
            room: selectedSlot.room,
            price: finalPrice,
            paymentStatus: 'unpaid',
            clientName: clientName, // End-client (optional for both)
            clientEmail: isGuest ? guestEmail : undefined, // Contact for invoice
            clientPhone: isGuest ? guestPhone : undefined, // Contact for invoice
            equipment: equipment 
        });

        setIsProcessing(false);
        setSelectedSlot(null);
    };

    return (
        <div className="min-h-screen bg-stone-50 pb-20">
            {/* Header / Navbar */}
            <div className="bg-white border-b border-stone-200 sticky top-0 z-30 shadow-sm">
