    );
};

export default StudioSchedule;

import React, { useState, useMemo, useEffect } from 'react';
import { Booking, Practitioner } from '../types';
import { GENERATED_TIMES, BUFFER_SAME_USER, BUFFER_DIFF_USER, RENTAL_PRICING } from '../constants';
import Button from '../components/Button';
import { Calendar, ChevronLeft, ChevronRight, Clock, User, Check, AlertCircle, Info, Lock, Zap, LogOut, Loader2, Bed, Layers, Sparkles, History, Monitor, Smartphone, Mail, Phone, X } from 'lucide-react';

interface StudioScheduleProps {
  currentUser: Practitioner;
  allBookings: Booking[];
  onBook: (bookingData: Partial<Booking>) => Promise<void>;
  onCancel: (bookingId: string) => void;
  onLogout: () => void;
}

const DAYS_MAP = ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'];

// Helper: Convert time "14:30" -> minutes 870
const timeToMinutes = (time: string): number => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
};

// Helper: Convert minutes -> time string "14:30"
const minutesToTime = (minutes: number): string => {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
};

const StudioSchedule: React.FC<StudioScheduleProps> = ({ 
    currentUser, 
    allBookings, 
    onBook, 
    onCancel,
    onLogout
}) => {
    // View State
    const [viewMode, setViewMode] = useState<'day' | 'week'>('week');
    const [currentDate, setCurrentDate] = useState(new Date()); 

    // Check screen size on mount and resize
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) {
                setViewMode('day');
            } else {
                setViewMode('week');
            }
        };
        handleResize();
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const [selectedSlot, setSelectedSlot] = useState<{date: string, time: string, room: 1 | 2} | null>(null);

    // Booking Form State
    const [duration, setDuration] = useState<number>(60);
    const [clientName, setClientName] = useState(''); // This is "End Client" for regulars, but unused/optional for guests
    const [equipment, setEquipment] = useState<'table' | 'futon'>('table'); 
    const [isProcessing, setIsProcessing] = useState(false);

    // GUEST SPECIFIC STATE
    const [guestName, setGuestName] = useState('');
    const [guestEmail, setGuestEmail] = useState('');
    const [guestPhone, setGuestPhone] = useState('');

    const isGuest = currentUser.id === 'guest';

    // Reset fields when modal opens/closes
    useEffect(() => {
        if (selectedSlot) {
            setDuration(60);
            setClientName('');
            setEquipment('table');
            setGuestName('');
            setGuestEmail('');
            setGuestPhone('');
        }
    }, [selectedSlot]);

    // --- CALENDAR LOGIC ---

    const handleNavigate = (offset: number) => {
        const newDate = new Date(currentDate);
        if (viewMode === 'day') {
            let daysToAdd = offset;
            newDate.setDate(newDate.getDate() + daysToAdd);

            // Optional: Skip weekend logic if needed
            const day = newDate.getDay();
            if (day === 0) newDate.setDate(newDate.getDate() + (offset > 0 ? 1 : -2)); 
            if (day === 6) newDate.setDate(newDate.getDate() + (offset > 0 ? 2 : -1)); 

        } else {
            newDate.setDate(newDate.getDate() + (offset * 7));
        }
        setCurrentDate(newDate);
    };

    const visibleDays = useMemo(() => {
        if (viewMode === 'day') {
            return [new Date(currentDate)];
        } else {
            return Array.from({ length: 5 }, (_, i) => {
                const d = new Date(currentDate);
                const day = d.getDay();
                const diff = d.getDate() - day + (day === 0 ? -6 : 1);
                d.setDate(diff + i);
                return d;
            });
        }
    }, [currentDate, viewMode]);

    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    const getSlotStatus = (date: Date, time: string, room: 1 | 2) => {
        const dateStr = formatDate(date);
        const slotStart = timeToMinutes(time);
        const slotEnd = slotStart + 30; 

        const now = new Date();
        const slotDateTime = new Date(`${dateStr}T${time}`);

        // Past check logic...

        const overlap = allBookings.find(b => {
            if (b.date !== dateStr || b.status !== 'confirmed' || b.room !== room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            const bufferDuration = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferDuration;

            const isBooking = (slotStart < bEnd && slotEnd > bStart);
            const isBuffer = (slotStart < bBufferEnd && slotEnd > bEnd);

            return isBooking || isBuffer;
        });

        if (!overlap) {
            if (slotDateTime < now) return { status: 'past' as const };
            return { status: 'free' as const };
        }

        const bStart = timeToMinutes(overlap.time);
        const bEnd = bStart + overlap.durationMinutes;
        const isBuffer = slotStart >= bEnd; 
        const isMine = overlap.bookedByUserId === currentUser.id;

        return {
            status: isBuffer ? 'cleaning' as const : (isMine ? 'mine' as const : 'occupied' as const),
            booking: overlap,
            bufferUsed: (overlap.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER
        };
    };

    // --- HANDLERS ---

    const handleSlotClick = (date: Date, time: string, room: 1 | 2, statusData: ReturnType<typeof getSlotStatus>) => {
        if (statusData.status === 'past') return;

        if (statusData.status === 'free') {
            setSelectedSlot({
                date: formatDate(date),
                time,
                room
            });
        } else if (statusData.status === 'mine' && statusData.booking) {
            const bookingStart = new Date(`${statusData.booking.date}T${statusData.booking.time}`);
            const now = new Date();
            const hoursDifference = (bookingStart.getTime() - now.getTime()) / (1000 * 60 * 60);

            if (hoursDifference < 24) {
                alert("Rezervaci nelze zrušit méně než 24 hodin předem.\n\nPro storno prosím kontaktujte manažera studia.");
                return;
            }

            if (window.confirm(`Chcete zrušit svou rezervaci?\n\n${statusData.booking.date} v ${statusData.booking.time}\n(Zbývá ${Math.floor(hoursDifference)}h do začátku)`)) {
                onCancel(statusData.booking.id);
            }
        }
    };

    const handleConfirmBooking = async () => {
        if (!selectedSlot) return;

        // Validation for Guest
        if (isGuest) {
            if (!guestName.trim() || !guestEmail.trim() || !guestPhone.trim()) {
                alert("Jako host musíte vyplnit jméno, email a telefon pro zaslání platebních údajů.");
                return;
            }
        }

        const newStart = timeToMinutes(selectedSlot.time);
        const newEnd = newStart + duration;

        const isUserDoubleBooked = allBookings.some(b => {
             // For guests, we don't strictly check ID collision since 'guest' ID is shared,
             // BUT we might want to check name collision? 
             // For simplicity, guests can double book (different people), 
             // regular users cannot.
             if (!isGuest && b.bookedByUserId !== currentUser.id) return false; 
             if (isGuest) return false; // Allow multiple 'guests' to book different rooms at same time

             if (b.date !== selectedSlot.date || b.status !== 'confirmed') return false;

             const bStart = timeToMinutes(b.time);
             const bEnd = bStart + b.durationMinutes;

             return (newStart < bEnd && newEnd > bStart);
        });

        if (isUserDoubleBooked) {
             alert("Nelze rezervovat: V tomto čase již máte rezervaci.");
             return;
        }

        const hasCollision = allBookings.some(b => {
            if (b.date !== selectedSlot.date || b.status !== 'confirmed' || b.room !== selectedSlot.room) return false;

            const bStart = timeToMinutes(b.time);
            const bEnd = bStart + b.durationMinutes;

            if (newStart < bEnd && newEnd > bStart) return true;

            const bufferAfterThem = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const bBufferEnd = bEnd + bufferAfterThem;
            if (newStart < bBufferEnd && newStart >= bEnd) return true;

            const bufferAfterMe = (b.bookedByUserId === currentUser.id) ? BUFFER_SAME_USER : BUFFER_DIFF_USER;
            const myBufferEnd = newEnd + bufferAfterMe;
            if (newEnd <= bStart && myBufferEnd > bStart) return true;

            return false;
        });

        if (hasCollision) {
            alert("Nelze rezervovat: Kolize s jinou rezervací nebo úklidem.");
            return;
        }

        setIsProcessing(true);

        const priceRate = selectedSlot.room === 1 ? RENTAL_PRICING.room1 : RENTAL_PRICING.room2;
        const finalPrice = (duration / 60) * priceRate;

        await onBook({
            bookedByUserId: currentUser.id,
