            clientEmail: isGuest ? guestEmail : undefined, // Contact for invoice
            clientPhone: isGuest ? guestPhone : undefined, // Contact for invoice
            equipment: equipment 
        });

        setIsProcessing(false);
        setSelectedSlot(null);
    };

    return (
