const PageTracker = () => {
  const location = useLocation();
  useEffect(() => {
    Monitoring.trackPageView(location.pathname);
    window.scrollTo(0, 0); 
  }, [location]);
  return null;
};

const AppContent = () => {
  const [currentUser, setCurrentUser] = useState<Practitioner | null>(null);
  const [bookings, setBookings] = useState<Booking[]>(generateMockBookings());
  const [practitionersList, setPractitionersList] = useState<Practitioner[]>(PRACTITIONERS);

  const navigate = useNavigate();

  const handleLogin = (user: Practitioner) => { 
      setCurrentUser(user); 
      if (user.role === Role.ADMIN) {
          navigate('/admin');
      } else {
          navigate('/schedule');
      }
  };

  const handleLogout = () => { 
      setCurrentUser(null); 
      navigate('/login'); 
  };

  const handleBooking = async (bookingData: Partial<Booking>) => {
      const newBooking: Booking = {
          id: Date.now().toString(),
          bookedByUserId: bookingData.bookedByUserId!,
          bookedByName: bookingData.bookedByName!,
          date: bookingData.date!,
          time: bookingData.time!,
          durationMinutes: bookingData.durationMinutes!,
          room: bookingData.room!,
          price: bookingData.price!,
          status: 'confirmed',
          paymentStatus: 'unpaid',
          paymentMethod: 'invoice',
          clientName: bookingData.clientName,
          clientEmail: bookingData.clientEmail,
          clientPhone: bookingData.clientPhone,
          equipment: bookingData.equipment,
          createdAt: new Date().toISOString()
      };

      await saveBookingToFirestore(newBooking);
      setBookings(prev => [...prev, newBooking]);
  };

  const handleCancel = (bookingId: string) => {
      setBookings(prev => prev.map(b => b.id === bookingId ? { ...b, status: 'cancelled', cancelledAt: new Date().toISOString() } : b));
  };

  const handlePractitionerUpdate = (updatedP: Practitioner) => {
      setPractitionersList(prev => prev.map(p => p.id === updatedP.id ? updatedP : p));
  };

  const handleAdminReschedule = (bookingId: string, newDate: string, newTime: string, reason?: string) => {
      setBookings(prev => prev.map(b => {
          if (b.id !== bookingId) return b;
          return {
              ...b,
              date: newDate,
              time: newTime,
              note: reason ? `ADMIN RESCHEDULE: ${reason}` : b.note
          };
      }));
  };

  return (
      <div className="min-h-screen bg-stone-50 font-sans text-stone-800">
          <Routes>
            <Route path="/login" element={<Login onLogin={handleLogin} />} />

            <Route path="/schedule" element={
                currentUser ? (
                    currentUser.role === Role.ADMIN ? <Navigate to="/admin" /> : (
                        <StudioSchedule 
                            currentUser={currentUser}
                            allBookings={bookings}
                            onBook={handleBooking}
                            onCancel={handleCancel}
                            onLogout={handleLogout}
                        />
                    )
                ) : <Navigate to="/login" />
            } />

            <Route path="/admin" element={
                currentUser && currentUser.role === Role.ADMIN ? (
                    <AdminDashboard 
                        allBookings={bookings}
                        practitioners={practitionersList}
                        updatePractitioner={handlePractitionerUpdate}
                        onAdminReschedule={handleAdminReschedule}
                        onLogout={handleLogout}
                    />
                ) : <Navigate to="/login" />
            } />

            <Route path="*" element={<Navigate to={currentUser ? (currentUser.role === Role.ADMIN ? "/admin" : "/schedule") : "/login"} />} />
          </Routes>
          <AIChatBot />
      </div>
  );
};

